// Minimal JSON value type, parser and serializer.
#pragma once
#include <cstdint>
#include <map>
#include <memory>
#include <string>
#include <utility>
#include <vector>

namespace js {

enum class type_t { null, boolean, integer, real, string, array, object };

class value;
using array_t = std::vector<value>;
using object_t = std::vector<std::pair<std::string, value>>;

class value {
public:
    type_t t = type_t::null;
    bool b = false;
    int64_t i = 0;
    double d = 0.0;
    std::string s;  // also keeps the original numeric text
    std::shared_ptr<array_t> arr;
    std::shared_ptr<object_t> obj;

    value() = default;
    static value make_null() { return value(); }
    static value make_bool(bool v) { value r; r.t = type_t::boolean; r.b = v; return r; }
    static value make_int(int64_t v) { value r; r.t = type_t::integer; r.i = v; return r; }
    static value make_real(double v) { value r; r.t = type_t::real; r.d = v; return r; }
    static value make_string(const std::string& v) { value r; r.t = type_t::string; r.s = v; return r; }
    static value make_array() { value r; r.t = type_t::array; r.arr = std::make_shared<array_t>(); return r; }
    static value make_object() { value r; r.t = type_t::object; r.obj = std::make_shared<object_t>(); return r; }

    bool is_null() const { return t == type_t::null; }
    bool is_bool() const { return t == type_t::boolean; }
    bool is_int() const { return t == type_t::integer; }
    bool is_real() const { return t == type_t::real; }
    bool is_number() const { return t == type_t::integer || t == type_t::real; }
    bool is_string() const { return t == type_t::string; }
    bool is_array() const { return t == type_t::array; }
    bool is_object() const { return t == type_t::object; }

    const value* get(const std::string& key) const;
    value* get_mut(const std::string& key);
    void set(const std::string& key, const value& v);
    void push(const value& v) { arr->push_back(v); }
    size_t size() const {
        if (is_array()) return arr->size();
        if (is_object()) return obj->size();
        return 0;
    }
    std::string as_string(const std::string& def = "") const {
        return is_string() ? s : def;
    }
    bool as_bool(bool def = false) const { return is_bool() ? b : def; }
    double as_double() const { return is_int() ? (double) i : (is_real() ? d : 0.0); }
    int64_t as_int() const { return is_int() ? i : (is_real() ? (int64_t) d : 0); }
};

struct parse_error {
    std::string msg;
    size_t offset = 0;
    int line = 1;
};

// Parse JSON text.  Returns true on success.
bool parse(const std::string& text, value& out, parse_error* err = nullptr,
           bool allow_trailing = false, size_t* consumed = nullptr);

std::string quote(const std::string& s);
// compact serialization
std::string dump(const value& v);
// pretty serialization with given indent
std::string dump_pretty(const value& v, int indent = 4);
std::string format_double(double d);

}  // namespace js
