    bool is_null() const { return t == type_t::null; }
    bool is_bool() const { return t == type_t::boolean; }
    bool is_int() const { return t == type_t::integer; }
    bool is_real() const { return t == type_t::real; }
    bool is_number() const { return t == type_t::integer || t == type_t::real; }
    bool is_string() const { return t == type_t::string; }
    bool is_array() const { return t == type_t::array; }
    bool is_object() const { return t == type_t::object; }

    const value* get(const std::string& key) const;
    value* get_mut(const std::string& key);
    void set(const std::string& key, const value& v);
    void push(const value& v) { arr->push_back(v); }
    size_t size() const {
        if (is_array()) return arr->size();
        if (is_object()) return obj->size();
        return 0;
    }
    std::string as_string(const std::string& def = "") const {
        return is_string() ? s : def;
    }
    bool as_bool(bool def = false) const { return is_bool() ? b : def; }
    double as_double() const { return is_int() ? (double) i : (is_real() ? d : 0.0); }
    int64_t as_int() const { return is_int() ? i : (is_real() ? (int64_t) d : 0); }
};

