namespace {

struct parser {
    const std::string& text;
    size_t pos = 0;
    std::string err;
    size_t err_pos = 0;

    explicit parser(const std::string& t) : text(t) {}

    void ws()
    {
        while (pos < text.size()) {
            char c = text[pos];
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                pos++;
            } else {
                break;
            }
        }
    }

    bool fail(const std::string& m)
    {
        if (err.empty()) {
            err = m;
            err_pos = pos;
        }
        return false;
    }

    static void append_utf8(std::string& out, uint32_t cp)
    {
        if (cp < 0x80) {
            out.push_back((char) cp);
        } else if (cp < 0x800) {
            out.push_back((char) (0xC0 | (cp >> 6)));
            out.push_back((char) (0x80 | (cp & 0x3F)));
        } else if (cp < 0x10000) {
            out.push_back((char) (0xE0 | (cp >> 12)));
            out.push_back((char) (0x80 | ((cp >> 6) & 0x3F)));
            out.push_back((char) (0x80 | (cp & 0x3F)));
        } else {
            out.push_back((char) (0xF0 | (cp >> 18)));
            out.push_back((char) (0x80 | ((cp >> 12) & 0x3F)));
            out.push_back((char) (0x80 | ((cp >> 6) & 0x3F)));
            out.push_back((char) (0x80 | (cp & 0x3F)));
        }
    }

    bool parse_hex4(uint32_t& out)
    {
        if (pos + 4 > text.size()) return fail("bad unicode escape");
        out = 0;
        for (int i = 0; i < 4; i++) {
            char c = text[pos++];
            out <<= 4;
            if (c >= '0' && c <= '9') out |= c - '0';
            else if (c >= 'a' && c <= 'f') out |= c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') out |= c - 'A' + 10;
            else return fail("bad unicode escape");
        }
        return true;
    }

    bool parse_string(std::string& out)
    {
        // assumes text[pos] == '"'
        pos++;
        while (true) {
            if (pos >= text.size()) return fail("unterminated string");
            char c = text[pos];
            if (c == '"') {
                pos++;
                return true;
            }
            if (c == '\\') {
                pos++;
                if (pos >= text.size()) return fail("unterminated string");
                char e = text[pos++];
                switch (e) {
                    case '"': out.push_back('"'); break;
                    case '\\': out.push_back('\\'); break;
                    case '/': out.push_back('/'); break;
                    case 'b': out.push_back('\b'); break;
                    case 'f': out.push_back('\f'); break;
                    case 'n': out.push_back('\n'); break;
                    case 'r': out.push_back('\r'); break;
                    case 't': out.push_back('\t'); break;
                    case 'u': {
                        uint32_t cp;
                        if (!parse_hex4(cp)) return false;
                        if (cp >= 0xD800 && cp <= 0xDBFF && pos + 6 <= text.size()
                            && text[pos] == '\\' && text[pos + 1] == 'u')
                        {
                            pos += 2;
                            uint32_t lo;
                            if (!parse_hex4(lo)) return false;
                            if (lo >= 0xDC00 && lo <= 0xDFFF) {
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            } else {
                                append_utf8(out, cp);
                                cp = lo;
                            }
                        }
                        append_utf8(out, cp);
                        break;
                    }
                    default:
                        pos--;
                        return fail("invalid escape");
                }
                continue;
            }
            if ((unsigned char) c < 0x20) {
                return fail("invalid character in string");
            }
            out.push_back(c);
            pos++;
        }
    }

    bool parse_value(value& out, int depth)
    {
        if (depth > 512) return fail("too deep");
        ws();
        if (pos >= text.size()) return fail("unexpected end of input");
        char c = text[pos];
        if (c == '{') {
            pos++;
            out = value::make_object();
            ws();
            if (pos < text.size() && text[pos] == '}') {
                pos++;
                return true;
            }
            while (true) {
                ws();
                if (pos >= text.size() || text[pos] != '"') return fail("expecting object key");
                std::string key;
                if (!parse_string(key)) return false;
                ws();
                if (pos >= text.size() || text[pos] != ':') return fail("expecting ':'");
                pos++;
                value v;
                if (!parse_value(v, depth + 1)) return false;
                out.obj->emplace_back(std::move(key), std::move(v));
                ws();
                if (pos >= text.size()) return fail("unexpected end of input");
                if (text[pos] == ',') {
                    pos++;
                    continue;
                }
                if (text[pos] == '}') {
                    pos++;
                    return true;
                }
                return fail("expecting ',' or '}'");
            }
        }
        if (c == '[') {
            pos++;
            out = value::make_array();
            ws();
            if (pos < text.size() && text[pos] == ']') {
                pos++;
                return true;
            }
            while (true) {
                value v;
                if (!parse_value(v, depth + 1)) return false;
                out.arr->push_back(std::move(v));
                ws();
                if (pos >= text.size()) return fail("unexpected end of input");
                if (text[pos] == ',') {
                    pos++;
                    continue;
                }
                if (text[pos] == ']') {
                    pos++;
                    return true;
                }
                return fail("expecting ',' or ']'");
            }
        }
        if (c == '"') {
            out = value::make_string("");
            return parse_string(out.s);
        }
        if (text.compare(pos, 4, "true") == 0) {
            pos += 4;
            out = value::make_bool(true);
            return true;
        }
        if (text.compare(pos, 5, "false") == 0) {
            pos += 5;
            out = value::make_bool(false);
            return true;
        }
        if (text.compare(pos, 4, "null") == 0) {
            pos += 4;
            out = value();
            return true;
        }
        if (c == '-' || (c >= '0' && c <= '9')) {
            size_t start = pos;
            bool is_real = false;
            if (text[pos] == '-') pos++;
            if (pos >= text.size() || !isdigit((unsigned char) text[pos])) return fail("invalid number");
            while (pos < text.size() && isdigit((unsigned char) text[pos])) pos++;
            if (pos < text.size() && text[pos] == '.') {
                is_real = true;
                pos++;
                if (pos >= text.size() || !isdigit((unsigned char) text[pos])) return fail("invalid number");
                while (pos < text.size() && isdigit((unsigned char) text[pos])) pos++;
            }
            if (pos < text.size() && (text[pos] == 'e' || text[pos] == 'E')) {
                is_real = true;
                pos++;
                if (pos < text.size() && (text[pos] == '+' || text[pos] == '-')) pos++;
                if (pos >= text.size() || !isdigit((unsigned char) text[pos])) return fail("invalid number");
                while (pos < text.size() && isdigit((unsigned char) text[pos])) pos++;
            }
            std::string num = text.substr(start, pos - start);
            if (!is_real) {
                errno = 0;
                char* end = nullptr;
                long long v = strtoll(num.c_str(), &end, 10);
                if (errno == ERANGE) {
                    out = value::make_real(strtod(num.c_str(), nullptr));
                } else {
                    out = value::make_int(v);
                }
            } else {
                out = value::make_real(strtod(num.c_str(), nullptr));
            }
            out.s = num;
            return true;
        }
        return fail("invalid value");
    }
};

}  // namespace

bool parse(const std::string& text, value& out, parse_error* err, bool allow_trailing,
           size_t* consumed)
{
    parser p(text);
    if (!p.parse_value(out, 0)) {
        if (err) {
            err->msg = p.err;
            err->offset = p.err_pos;
            int line = 1;
            for (size_t i = 0; i < p.err_pos && i < text.size(); i++) {
                if (text[i] == '\n') line++;
            }
            err->line = line;
        }
        return false;
    }
    p.ws();
    if (consumed) *consumed = p.pos;
    if (!allow_trailing && p.pos != text.size()) {
        if (err) {
            err->msg = "trailing garbage";
            err->offset = p.pos;
        }
        return false;
    }
    return true;
}

std::string quote(const std::string& s)
{
    std::string out;
    out.reserve(s.size() + 2);
    out.push_back('"');
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            default:
                if (c < 0x20) {
                    char buf[8];
                    snprintf(buf, sizeof(buf), "\\u%04X", c);
                    out += buf;
                } else {
                    out.push_back((char) c);
                }
        }
    }
    out.push_back('"');
    return out;
}

std::string format_double(double d)
{
    if (std::isnan(d) || std::isinf(d)) {
        return "null";
    }
    char buf[64];
    for (int prec = 1; prec <= 17; prec++) {
        snprintf(buf, sizeof(buf), "%.*g", prec, d);
        if (strtod(buf, nullptr) == d) break;
    }
    std::string r = buf;
    return r;
}

static void dump_impl(const value& v, std::string& out)
{
    switch (v.t) {
        case type_t::null: out += "null"; break;
        case type_t::boolean: out += v.b ? "true" : "false"; break;
        case type_t::integer: out += std::to_string(v.i); break;
        case type_t::real:
            if (!v.s.empty()) out += v.s;
            else out += format_double(v.d);
            break;
        case type_t::string: out += quote(v.s); break;
        case type_t::array: {
            out.push_back('[');
            bool first = true;
            for (auto& e : *v.arr) {
                if (!first) out.push_back(',');
                first = false;
                dump_impl(e, out);
            }
            out.push_back(']');
            break;
        }
        case type_t::object: {
            out.push_back('{');
            bool first = true;
            for (auto& kv : *v.obj) {
                if (!first) out.push_back(',');
                first = false;
                out += quote(kv.first);
                out.push_back(':');
                dump_impl(kv.second, out);
            }
            out.push_back('}');
            break;
        }
    }
}

std::string dump(const value& v)
{
    std::string out;
    dump_impl(v, out);
    return out;
}

static void dump_pretty_impl(const value& v, std::string& out, int indent, int level)
{
    switch (v.t) {
        case type_t::array: {
            if (v.arr->empty()) {
                out += "[]";
                return;
            }
            out += "[\n";
            bool first = true;
            for (auto& e : *v.arr) {
                if (!first) out += ",\n";
                first = false;
                out.append((level + 1) * indent, ' ');
                dump_pretty_impl(e, out, indent, level + 1);
            }
            out += "\n";
            out.append(level * indent, ' ');
            out += "]";
            break;
        }
        case type_t::object: {
            if (v.obj->empty()) {
                out += "{}";
                return;
            }
            out += "{\n";
            bool first = true;
            for (auto& kv : *v.obj) {
                if (!first) out += ",\n";
                first = false;
                out.append((level + 1) * indent, ' ');
                out += quote(kv.first);
                out += ": ";
                dump_pretty_impl(kv.second, out, indent, level + 1);
            }
            out += "\n";
            out.append(level * indent, ' ');
            out += "}";
            break;
        }
        default:
            dump_impl(v, out);
    }
}

std::string dump_pretty(const value& v, int indent)
{
    std::string out;
    dump_pretty_impl(v, out, indent, 0);
    return out;
}

}  // namespace js
