#include "regex.hh"

regex::~regex()
{
    if (md) pcre2_match_data_free(md);
    if (code) pcre2_code_free(code);
}

std::shared_ptr<regex> regex::compile(const std::string& pattern, std::string* err,
                                      int* err_offset, uint32_t options)
{
    int errcode = 0;
    PCRE2_SIZE erroff = 0;
    pcre2_code* code = pcre2_compile((PCRE2_SPTR) pattern.data(), pattern.size(),
                                     PCRE2_UTF | PCRE2_MATCH_INVALID_UTF | options, &errcode,
                                     &erroff, nullptr);
    if (code == nullptr) {
        if (err) {
            PCRE2_UCHAR buf[256];
            pcre2_get_error_message(errcode, buf, sizeof(buf));
            *err = (const char*) buf;
        }
        if (err_offset) *err_offset = (int) erroff;
        return nullptr;
    }
    pcre2_jit_compile(code, PCRE2_JIT_COMPLETE);
    auto r = std::make_shared<regex>();
    r->code = code;
    r->pat = pattern;
    uint32_t cc = 0;
    pcre2_pattern_info(code, PCRE2_INFO_CAPTURECOUNT, &cc);
    r->cap_count = (int) cc;
    r->idx_names.resize(cc + 1);
    uint32_t namecount = 0, entsize = 0;
    PCRE2_SPTR table = nullptr;
    pcre2_pattern_info(code, PCRE2_INFO_NAMECOUNT, &namecount);
    pcre2_pattern_info(code, PCRE2_INFO_NAMEENTRYSIZE, &entsize);
    pcre2_pattern_info(code, PCRE2_INFO_NAMETABLE, &table);
    for (uint32_t i = 0; i < namecount; i++) {
        const unsigned char* ent = table + i * entsize;
        int idx = (ent[0] << 8) | ent[1];
        std::string name((const char*) ent + 2);
        r->name_list.emplace_back(name, idx);
        if (idx >= 0 && idx < (int) r->idx_names.size()) r->idx_names[idx] = name;
    }
    r->md = pcre2_match_data_create_from_pattern(code, nullptr);
    return r;
}

bool regex::match(const char* data, size_t len, size_t offset, std::vector<regex_capture>& caps,
                  uint32_t options) const
{
    int rc = pcre2_match(code, (PCRE2_SPTR) data, len, offset, options, md, nullptr);
    caps.assign(cap_count + 1, regex_capture{});
    if (rc < 0) return false;
    PCRE2_SIZE* ov = pcre2_get_ovector_pointer(md);
    uint32_t n = pcre2_get_ovector_count(md);
    for (uint32_t i = 0; i < n && i <= (uint32_t) cap_count; i++) {
        if (ov[2 * i] == PCRE2_UNSET) continue;
        caps[i].start = (int) ov[2 * i];
        caps[i].end = (int) ov[2 * i + 1];
    }
    return true;
}

bool regex::search(const std::string& s) const
{
    return search(s.data(), s.size());
}

bool regex::search(const char* data, size_t len) const
{
    int rc = pcre2_match(code, (PCRE2_SPTR) data, len, 0, 0, md, nullptr);
    return rc >= 0;
}

int regex::name_index(const std::string& name) const
{
    for (auto& p : name_list) {
        if (p.first == name) return p.second;
    }
    return -1;
}

std::string regex::index_name(int idx) const
{
    if (idx < 0 || idx >= (int) idx_names.size()) return "";
    return idx_names[idx];
}
