#include "timefmt.hh"

#include <sys/time.h>

#include <cctype>
#include <cstring>

int64_t days_from_civil(int64_t y, unsigned m, unsigned d)
{
    y -= m <= 2;
    const int64_t era = (y >= 0 ? y : y - 399) / 400;
    const unsigned yoe = (unsigned) (y - era * 400);
    const unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + (int64_t) doe - 719468;
}

void civil_from_days(int64_t z, int& y, int& m, int& d)
{
    z += 719468;
    const int64_t era = (z >= 0 ? z : z - 146096) / 146097;
    const unsigned doe = (unsigned) (z - era * 146097);
    const unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    const int64_t yy = (int64_t) yoe + era * 400;
    const unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    const unsigned mp = (5 * doy + 2) / 153;
    d = (int) (doy - (153 * mp + 2) / 5 + 1);
    m = (int) (mp < 10 ? mp + 3 : mp - 9);
    y = (int) (yy + (m <= 2));
}

int64_t tm_to_epoch(const exttm& tm)
{
    int64_t days = days_from_civil(tm.year, tm.mon + 1, 1) + (tm.mday - 1);
    return days * 86400 + tm.hour * 3600 + tm.min * 60 + tm.sec - tm.gmtoff;
}

exttm epoch_to_tm(int64_t secs, int nsec)
{
    exttm tm;
    int64_t days = secs / 86400;
    int64_t rem = secs % 86400;
    if (rem < 0) {
        rem += 86400;
        days -= 1;
    }
    int y, m, d;
    civil_from_days(days, y, m, d);
    tm.year = y;
    tm.mon = m - 1;
    tm.mday = d;
    tm.hour = (int) (rem / 3600);
    tm.min = (int) ((rem % 3600) / 60);
    tm.sec = (int) (rem % 60);
    tm.nsec = nsec;
    tm.wday = (int) ((days % 7 + 11) % 7);  // 1970-01-01 was Thursday(4)
    tm.yday = (int) (days - days_from_civil(y, 1, 1));
    return tm;
}

static const char* MONTHS[] = {"jan", "feb", "mar", "apr", "may", "jun",
