                                    "september", "october", "november", "december"};
static const char* WDAYS[] = {"sun", "mon", "tue", "wed", "thu", "fri", "sat"};
static const char* WDAYS_FULL[] = {"sunday",   "monday", "tuesday", "wednesday",
                                   "thursday", "friday", "saturday"};
static const char* MONTHS_CAP[] = {"Jan", "Feb", "Mar", "Apr", "May", "Jun",
                                   "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
static const char* WDAYS_CAP[] = {"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"};

static bool ieq_prefix(const char* str, size_t off, size_t len, const char* word)
{
    size_t wl = strlen(word);
    if (off + wl > len) return false;
    for (size_t i = 0; i < wl; i++) {
        if (tolower((unsigned char) str[off + i]) != word[i]) return false;
    }
    return true;
}

// lnav-compatible two character numeric parse (does not validate 2nd char)
static bool two_char_num(const char* str, size_t& off, size_t len, int lo, int hi, int& out)
{
    if (off + 2 > len) return false;
    if (!isdigit((unsigned char) str[off])) return false;
    int v = (str[off] - '0') * 10 + (str[off + 1] - '0');
    if (v < lo || v > hi) return false;
    out = v;
    off += 2;
    return true;
}

static bool digits_num(const char* str, size_t& off, size_t len, int mind, int maxd, int64_t& out)
{
    size_t start = off;
    int64_t v = 0;
    while (off < len && (int) (off - start) < maxd && isdigit((unsigned char) str[off])) {
        v = v * 10 + (str[off] - '0');
        off++;
    }
    if ((int) (off - start) < mind) {
        off = start;
        return false;
    }
    out = v;
    return true;
}

struct tz_abbr {
    const char* name;
    int offset;
};

static const tz_abbr TZ_ABBRS[] = {
    {"UTC", 0},          {"GMT", 0},          {"UT", 0},           {"Z", 0},
    {"EST", -5 * 3600},  {"EDT", -4 * 3600},  {"CST", -6 * 3600},  {"CDT", -5 * 3600},
    {"MST", -7 * 3600},  {"MDT", -6 * 3600},  {"PST", -8 * 3600},  {"PDT", -7 * 3600},
    {"AKST", -9 * 3600}, {"AKDT", -8 * 3600}, {"HST", -10 * 3600}, {"CET", 1 * 3600},
    {"CEST", 2 * 3600},  {"EET", 2 * 3600},   {"EEST", 3 * 3600},  {"WET", 0},
    {"WEST", 1 * 3600},  {"BST", 1 * 3600},   {"IST", 19800},      {"JST", 9 * 3600},
    {"KST", 9 * 3600},   {"AEST", 10 * 3600}, {"AEDT", 11 * 3600}, {"MSK", 3 * 3600},
    {nullptr, 0},
};

static bool parse_zone_offset(const char* str, size_t& off, size_t len, exttm& tm)
{
    if (off < len && str[off] == 'Z') {
        off++;
        tm.gmtoff = 0;
        tm.flags |= ETF_Z_IS_UTC;
        return true;
    }
    if (off >= len || (str[off] != '+' && str[off] != '-')) return false;
    int sign = str[off] == '-' ? -1 : 1;
    size_t p = off + 1;
    if (p + 2 > len || !isdigit((unsigned char) str[p]) || !isdigit((unsigned char) str[p + 1]))
        return false;
    int hh = (str[p] - '0') * 10 + (str[p + 1] - '0');
    p += 2;
    bool colon = false;
    if (p < len && str[p] == ':') {
        colon = true;
        p++;
    }
    if (p + 2 > len || !isdigit((unsigned char) str[p]) || !isdigit((unsigned char) str[p + 1]))
        return false;
    int mm = (str[p] - '0') * 10 + (str[p + 1] - '0');
    p += 2;
    off = p;
    tm.gmtoff = sign * (hh * 3600 + mm * 60);
    tm.flags |= ETF_ZONE_SET;
    if (colon) tm.flags |= ETF_Z_COLON;
    return true;
}

static void set_frac(exttm& tm, int64_t v, int ndigits)
{
    int64_t ns = v;
    for (int i = ndigits; i < 9; i++) ns *= 10;
    for (int i = ndigits; i > 9; i--) ns /= 10;
    tm.nsec = (int) ns;
    tm.flags &= ~(ETF_MILLIS_SET | ETF_MICROS_SET | ETF_NANOS_SET);
    if (ndigits <= 3) tm.flags |= ETF_MILLIS_SET;
    else if (ndigits <= 6) tm.flags |= ETF_MICROS_SET;
    else tm.flags |= ETF_NANOS_SET;
}

bool ptime_fmt(const char* fmt, exttm& tm, const char* str, size_t& off, size_t len)
{
    for (size_t fi = 0; fmt[fi]; fi++) {
        char fc = fmt[fi];
        if (fc != '%') {
            if (off >= len || str[off] != fc) return false;
            off++;
            continue;
        }
        fi++;
        char code = fmt[fi];
        if (!code) return false;
        int iv;
        int64_t lv;
        switch (code) {
            case '%':
                if (off >= len || str[off] != '%') return false;
                off++;
                break;
            case 'Y':
                if (off + 4 > len) return false;
                for (int i = 0; i < 4; i++)
                    if (!isdigit((unsigned char) str[off + i])) return false;
                tm.year = (str[off] - '0') * 1000 + (str[off + 1] - '0') * 100
                    + (str[off + 2] - '0') * 10 + (str[off + 3] - '0');
                off += 4;
                tm.flags |= ETF_YEAR_SET;
                break;
            case 'y':
                if (off + 2 > len || !isdigit((unsigned char) str[off])
                    || !isdigit((unsigned char) str[off + 1]))
                    return false;
                iv = (str[off] - '0') * 10 + (str[off + 1] - '0');
                tm.year = iv < 69 ? 2000 + iv : 1900 + iv;
                off += 2;
                tm.flags |= ETF_YEAR_SET;
                break;
            case 'm':
                if (!digits_num(str, off, len, 1, 2, lv)) return false;
                if (lv < 1 || lv > 12) return false;
                tm.mon = (int) lv - 1;
                tm.flags |= ETF_MONTH_SET;
                break;
            case 'd':
                if (!two_char_num(str, off, len, 1, 31, iv)) return false;
                tm.mday = iv;
                tm.flags |= ETF_DAY_SET;
                break;
            case 'e':
                if (off < len && str[off] == ' ') off++;
                if (!digits_num(str, off, len, 1, 2, lv)) return false;
                if (lv < 1 || lv > 31) return false;
                tm.mday = (int) lv;
                tm.flags |= ETF_DAY_SET;
                break;
            case 'H':
                if (!two_char_num(str, off, len, 0, 23, iv)) return false;
                tm.hour = iv;
                tm.flags |= ETF_HOUR_SET;
                break;
            case 'k':
                if (off < len && str[off] == ' ') off++;
                if (!digits_num(str, off, len, 1, 2, lv)) return false;
                if (lv > 23) return false;
                tm.hour = (int) lv;
                tm.flags |= ETF_HOUR_SET;
                break;
            case 'I':
                if (!two_char_num(str, off, len, 1, 12, iv)) return false;
                tm.hour = iv;
                tm.flags |= ETF_HOUR_SET;
                break;
            case 'l':
                if (off < len && str[off] == ' ') off++;
                if (!digits_num(str, off, len, 1, 2, lv)) return false;
                if (lv < 1 || lv > 12) return false;
                tm.hour = (int) lv;
                tm.flags |= ETF_HOUR_SET;
                break;
            case 'p':
                if (ieq_prefix(str, off, len, "am")) {
                    tm.pm = 0;
                } else if (ieq_prefix(str, off, len, "pm")) {
                    tm.pm = 1;
                } else {
                    return false;
                }
                off += 2;
                break;
            case 'M':
                if (!two_char_num(str, off, len, 0, 59, iv)) return false;
                tm.min = iv;
                tm.flags |= ETF_MINUTE_SET;
                break;
            case 'S':
                if (!two_char_num(str, off, len, 0, 60, iv)) return false;
                tm.sec = iv;
                tm.flags |= ETF_SECOND_SET;
                break;
            case 'T':
                if (!ptime_fmt("%H:%M:%S", tm, str, off, len)) return false;
                break;
            case 'b':
            case 'h': {
                bool found = false;
                for (int i = 0; i < 12; i++) {
                    if (ieq_prefix(str, off, len, MONTHS[i])) {
                        tm.mon = i;
                        off += 3;
                        found = true;
                        break;
                    }
                }
                if (!found) return false;
                tm.flags |= ETF_MONTH_SET;
                break;
            }
            case 'B': {
                bool found = false;
                for (int i = 0; i < 12; i++) {
                    if (ieq_prefix(str, off, len, MONTHS_FULL[i])) {
                        tm.mon = i;
                        off += strlen(MONTHS_FULL[i]);
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    for (int i = 0; i < 12; i++) {
                        if (ieq_prefix(str, off, len, MONTHS[i])) {
                            tm.mon = i;
                            off += 3;
                            found = true;
                            break;
                        }
                    }
                }
                if (!found) return false;
                tm.flags |= ETF_MONTH_SET;
                break;
            }
            case 'a': {
                bool found = false;
                for (int i = 0; i < 7; i++) {
                    if (ieq_prefix(str, off, len, WDAYS[i])) {
                        tm.wday = i;
                        off += 3;
                        found = true;
                        break;
                    }
                }
                if (!found) return false;
                break;
            }
            case 'A': {
                bool found = false;
                for (int i = 0; i < 7; i++) {
                    if (ieq_prefix(str, off, len, WDAYS_FULL[i])) {
                        tm.wday = i;
                        off += strlen(WDAYS_FULL[i]);
                        found = true;
                        break;
                    }
                }
                if (!found) return false;
                break;
            }
            case 'f': {
                size_t start = off;
                int64_t v = 0;
                int nd = 0;
                while (off < len && isdigit((unsigned char) str[off])) {
                    if (nd < 9) v = v * 10 + (str[off] - '0');
                    nd++;
                    off++;
                }
                if (nd == 0) {
                    off = start;
                    return false;
                }
                set_frac(tm, v, nd > 9 ? 9 : nd);
                if (nd > 9) {
                    tm.flags &= ~(ETF_MILLIS_SET | ETF_MICROS_SET);
                    tm.flags |= ETF_NANOS_SET;
                }
                break;
            }
            case 'L':
                if (off + 3 > len) return false;
                for (int i = 0; i < 3; i++)
                    if (!isdigit((unsigned char) str[off + i])) return false;
                set_frac(tm,
                         (str[off] - '0') * 100 + (str[off + 1] - '0') * 10 + (str[off + 2] - '0'),
                         3);
                off += 3;
                break;
            case 'N': {
                if (!digits_num(str, off, len, 9, 9, lv)) return false;
                set_frac(tm, lv, 9);
                break;
            }
            case 'z':
                if (!parse_zone_offset(str, off, len, tm)) return false;
                break;
            case 'Z': {
                bool found = false;
                for (int i = 0; TZ_ABBRS[i].name; i++) {
                    size_t nl = strlen(TZ_ABBRS[i].name);
                    if (off + nl <= len && strncmp(str + off, TZ_ABBRS[i].name, nl) == 0
                        && (off + nl == len || !isalpha((unsigned char) str[off + nl])))
                    {
                        tm.gmtoff = TZ_ABBRS[i].offset;
                        off += nl;
                        if (strcmp(TZ_ABBRS[i].name, "Z") == 0) {
                            tm.flags |= ETF_Z_IS_UTC;
                        } else {
                            tm.flags |= ETF_ZONE_SET | ETF_Z_NAME;
                        }
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    if (!parse_zone_offset(str, off, len, tm)) return false;
                }
                break;
            }
            case 's': {
                size_t start = off;
                bool neg = false;
                if (off < len && str[off] == '-') {
                    neg = true;
                    off++;
                }
                if (!digits_num(str, off, len, 1, 18, lv)) {
                    off = start;
                    return false;
                }
                exttm e = epoch_to_tm(neg ? -lv : lv);
                e.flags = tm.flags | ETF_YEAR_SET | ETF_MONTH_SET | ETF_DAY_SET | ETF_HOUR_SET
                    | ETF_MINUTE_SET | ETF_SECOND_SET | ETF_EPOCH_TIME | ETF_Z_IS_UTC;
                e.nsec = tm.nsec;
                tm = e;
                break;
            }
            case 'i':
            case '6':
            case '9': {
                if (!digits_num(str, off, len, 1, 19, lv)) return false;
                int64_t div = code == 'i' ? 1000 : (code == '6' ? 1000000 : 1000000000);
                exttm e = epoch_to_tm(lv / div, (int) ((lv % div) * (1000000000 / div)));
                e.flags = tm.flags | ETF_YEAR_SET | ETF_MONTH_SET | ETF_DAY_SET | ETF_HOUR_SET
                    | ETF_MINUTE_SET | ETF_SECOND_SET | ETF_EPOCH_TIME | ETF_Z_IS_UTC
                    | (code == 'i' ? ETF_MILLIS_SET : (code == '6' ? ETF_MICROS_SET : ETF_NANOS_SET));
                tm = e;
                break;
            }
            case 'j':
                if (!digits_num(str, off, len, 3, 3, lv)) return false;
                tm.yday = (int) lv - 1;
                break;
            case 'q': {
                // optional fraction
                break;
            }
            default:
                return false;
        }
    }
    return true;
}

static void append2(std::string& out, int v)
{
    out.push_back('0' + (v / 10) % 10);
    out.push_back('0' + v % 10);
}

std::string ftime_fmt(const std::string& fmt, const exttm& tm)
{
    std::string out;
    char buf[64];
    for (size_t i = 0; i < fmt.size(); i++) {
        char c = fmt[i];
        if (c != '%' || i + 1 >= fmt.size()) {
            out.push_back(c);
            continue;
        }
        char code = fmt[++i];
        switch (code) {
            case 'Y':
                snprintf(buf, sizeof(buf), "%04d", tm.year);
                out += buf;
                break;
            case 'y': append2(out, tm.year % 100); break;
            case 'm': append2(out, tm.mon + 1); break;
            case 'd': append2(out, tm.mday); break;
            case 'e':
                if (tm.mday < 10) {
                    out.push_back(' ');
                    out.push_back('0' + tm.mday);
                } else {
                    append2(out, tm.mday);
                }
                break;
            case 'H': append2(out, tm.hour); break;
            case 'k':
                if (tm.hour < 10) {
                    out.push_back(' ');
                    out.push_back('0' + tm.hour);
                } else {
                    append2(out, tm.hour);
                }
                break;
            case 'I': {
                int h = tm.hour % 12;
                if (h == 0) h = 12;
                append2(out, h);
                break;
            }
            case 'l': {
                int h = tm.hour % 12;
                if (h == 0) h = 12;
                if (h < 10) {
                    out.push_back(' ');
                    out.push_back('0' + h);
                } else {
                    append2(out, h);
                }
                break;
            }
            case 'p': out += tm.hour >= 12 ? "PM" : "AM"; break;
            case 'M': append2(out, tm.min); break;
            case 'S': append2(out, tm.sec); break;
            case 'T':
                append2(out, tm.hour);
                out.push_back(':');
                append2(out, tm.min);
                out.push_back(':');
                append2(out, tm.sec);
                break;
            case 'b':
            case 'h': out += MONTHS_CAP[tm.mon % 12]; break;
            case 'B': {
                std::string m = MONTHS_FULL[tm.mon % 12];
                m[0] = toupper(m[0]);
                out += m;
                break;
            }
            case 'a': out += WDAYS_CAP[tm.wday % 7]; break;
            case 'A': {
                std::string w = WDAYS_FULL[tm.wday % 7];
                w[0] = toupper(w[0]);
                out += w;
                break;
            }
            case 'f':
                if (tm.flags & ETF_NANOS_SET) {
                    snprintf(buf, sizeof(buf), "%09d", tm.nsec);
                } else if (tm.flags & ETF_MICROS_SET) {
                    snprintf(buf, sizeof(buf), "%06d", tm.nsec / 1000);
                } else {
                    snprintf(buf, sizeof(buf), "%03d", tm.nsec / 1000000);
                }
                out += buf;
                break;
            case 'L':
                snprintf(buf, sizeof(buf), "%03d", tm.nsec / 1000000);
                out += buf;
                break;
            case 'N':
                snprintf(buf, sizeof(buf), "%09d", tm.nsec);
                out += buf;
                break;
            case 'z':
            case 'Z': {
                int off = tm.gmtoff;
                char sign = off < 0 ? '-' : '+';
                if (off < 0) off = -off;
                if (code == 'z' && (tm.flags & ETF_Z_COLON)) {
                    snprintf(buf, sizeof(buf), "%c%02d:%02d", sign, off / 3600, (off % 3600) / 60);
                } else {
                    snprintf(buf, sizeof(buf), "%c%02d%02d", sign, off / 3600, (off % 3600) / 60);
                }
                out += buf;
                break;
            }
            case 's':
                out += std::to_string(tm_to_epoch(tm));
                break;
            case 'j':
                snprintf(buf, sizeof(buf), "%03d", tm.yday + 1);
                out += buf;
                break;
            case '%': out.push_back('%'); break;
            default:
                out.push_back('%');
                out.push_back(code);
        }
    }
    return out;
}

