int64_t tm_to_epoch(const exttm& tm)
{
    int64_t days = days_from_civil(tm.year, tm.mon + 1, 1) + (tm.mday - 1);
    return days * 86400 + tm.hour * 3600 + tm.min * 60 + tm.sec - tm.gmtoff;
}

exttm epoch_to_tm(int64_t secs, int nsec)
{
    exttm tm;
    int64_t days = secs / 86400;
