// lnav-compatible two character numeric parse (does not validate 2nd char)
static bool two_char_num(const char* str, size_t& off, size_t len, int lo, int hi, int& out)
{
    if (off + 2 > len) return false;
    if (!isdigit((unsigned char) str[off])) return false;
    int v = (str[off] - '0') * 10 + (str[off + 1] - '0');
    if (v < lo || v > hi) return false;
    out = v;
    off += 2;
    return true;
}

static bool digits_num(const char* str, size_t& off, size_t len, int mind, int maxd, int64_t& out)
