    size_t start = off;
    int64_t v = 0;
    while (off < len && (int) (off - start) < maxd && isdigit((unsigned char) str[off])) {
        v = v * 10 + (str[off] - '0');
        off++;
    }
    if ((int) (off - start) < mind) {
        off = start;
        return false;
