void date_time_scanner::set_base_time(int64_t epoch_secs)
{
    base = epoch_to_tm(epoch_secs);
    base_set = true;
}

static const std::string EMPTY_STR;

const std::string& date_time_scanner::locked_format() const
{
    const auto& fmts = custom ? *custom : default_time_formats();
    if (fmt_lock < 0 || fmt_lock >= (int) fmts.size()) return EMPTY_STR;
    return fmts[fmt_lock];
}

static bool parse_tai64(const char* s, size_t len, size_t& off, exttm& tm)
{
    // @4000000065c3a1b2[nnnnnnnn]
    if (len < 17 || s[0] != '@') return false;
    size_t p = 1;
    uint64_t v = 0;
    int nd = 0;
    while (p < len && nd < 16 && isxdigit((unsigned char) s[p])) {
        char c = tolower(s[p]);
        v = v * 16 + (isdigit((unsigned char) c) ? c - '0' : c - 'a' + 10);
        p++;
        nd++;
    }
    if (nd != 16) return false;
    int64_t secs = (int64_t) (v - 0x4000000000000000ULL);
    int nsec = 0;
    int nd2 = 0;
    uint64_t nv = 0;
    while (p < len && nd2 < 8 && isxdigit((unsigned char) s[p])) {
        char c = tolower(s[p]);
        nv = nv * 16 + (isdigit((unsigned char) c) ? c - '0' : c - 'a' + 10);
        p++;
        nd2++;
    }
    if (nd2 == 8) nsec = (int) nv;
    exttm e = epoch_to_tm(secs - 10, nsec);
    e.flags = ETF_YEAR_SET | ETF_MONTH_SET | ETF_DAY_SET | ETF_HOUR_SET | ETF_MINUTE_SET
        | ETF_SECOND_SET | ETF_EPOCH_TIME | ETF_Z_IS_UTC;
    if (nd2 == 8) e.flags |= ETF_NANOS_SET;
    tm = e;
    off = p;
    return true;
}

int date_time_scanner::scan(const char* s, size_t len, exttm& out, int64_t& out_usecs,
                            bool use_lock)
{
    const auto& fmts = custom ? *custom : default_time_formats();
    if (!base_set) {
        set_base_time(now_usecs() / 1000000);
    }
    auto try_one = [&](int idx, size_t& off) -> bool {
        exttm tm;
        tm.year = base.year;
        tm.mon = base.mon;
        tm.mday = base.mday;
        tm.hour = base.hour;
        tm.min = 0;
        tm.sec = 0;
        tm.flags = 0;
        off = 0;
        const std::string& f = fmts[idx];
        if (f == "@%@") {
            if (!parse_tai64(s, len, off, tm)) return false;
            out = tm;
            return true;
        }
        if (!ptime_fmt(f.c_str(), tm, s, off, len)) return false;
        if (!custom) {
            // nothing
        } else {
            // custom formats must be followed by end, '.', or ','
        }
        if (tm.flags & ETF_EPOCH_TIME) {
            out = tm;
            return true;
        }
        if (!(tm.flags & ETF_YEAR_SET)) tm.year = base.year;
        if (!(tm.flags & (ETF_MONTH_SET | ETF_DAY_SET))) {
            tm.mon = base.mon;
            tm.mday = base.mday;
        } else {
            if (!(tm.flags & ETF_MONTH_SET)) tm.mon = 0;
            if (!(tm.flags & ETF_DAY_SET)) tm.mday = 1;
            if (!(tm.flags & ETF_HOUR_SET)) tm.hour = 0;
        }
        if (!(tm.flags & ETF_HOUR_SET) && (tm.flags & (ETF_MONTH_SET | ETF_DAY_SET))) {
            tm.hour = 0;
        }
        if (tm.pm == 1 && tm.hour < 12) tm.hour += 12;
        if (tm.pm == 0 && tm.hour == 12) tm.hour = 0;
        out = tm;
        return true;
    };

    size_t off = 0;
    bool found = false;
    if (use_lock && fmt_lock >= 0) {
        if (try_one(fmt_lock, off)) found = true;
    } else {
        for (int i = 0; i < (int) fmts.size(); i++) {
            if (try_one(i, off)) {
                if (custom) {
                    if (!(off == len || s[off] == '.' || s[off] == ',')) {
                        // lnav requires custom formats consume until a fraction or end
                        continue;
                    }
                }
                fmt_lock = i;
                found = true;
                break;
            }
        }
    }
    if (!found) return -1;
    if (custom && !(off == len || s[off] == '.' || s[off] == ',' ) && use_lock && fmt_lock >= 0) {
        // locked custom format must also satisfy the trailing constraint
        if (!(off == len || s[off] == '.' || s[off] == ',')) return -1;
    }
    if (!(out.flags & (ETF_MILLIS_SET | ETF_MICROS_SET | ETF_NANOS_SET)) && off + 1 < len
        && (s[off] == '.' || s[off] == ',') && isdigit((unsigned char) s[off + 1]))
    {
        if (s[off] == ',') out.flags |= ETF_FRAC_COMMA;
        size_t p = off + 1;
        int64_t v = 0;
        int nd = 0;
        while (p < len && isdigit((unsigned char) s[p])) {
            if (nd < 9) v = v * 10 + (s[p] - '0');
            nd++;
            p++;
        }
        set_frac(out, v, nd > 9 ? 9 : nd);
        off = p;
    }
    fmt_len = off;
    int64_t secs = tm_to_epoch(out);
    out_usecs = secs * 1000000 + out.nsec / 1000;
    exttm norm = epoch_to_tm(secs + out.gmtoff);
    out.wday = norm.wday;
    out.yday = norm.yday;
    return (int) off;
}

std::string format_sql_time(int64_t usecs)
{
    int64_t secs = usecs / 1000000;
    int64_t us = usecs % 1000000;
    if (us < 0) {
        us += 1000000;
        secs -= 1;
    }
    exttm tm = epoch_to_tm(secs);
    char buf[64];
    snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d.%06d", tm.year, tm.mon + 1, tm.mday,
             tm.hour, tm.min, tm.sec, (int) us);
    return buf;
}

std::string format_iso_time(int64_t usecs, int prec, char sep)
{
    int64_t secs = usecs / 1000000;
    int64_t us = usecs % 1000000;
    if (us < 0) {
        us += 1000000;
        secs -= 1;
    }
    exttm tm = epoch_to_tm(secs);
    char buf[64];
    snprintf(buf, sizeof(buf), "%04d-%02d-%02d%c%02d:%02d:%02d", tm.year, tm.mon + 1, tm.mday, sep,
             tm.hour, tm.min, tm.sec);
    std::string r = buf;
    if (prec == 3) {
        snprintf(buf, sizeof(buf), ".%03d", (int) (us / 1000));
        r += buf;
    } else if (prec == 6) {
        snprintf(buf, sizeof(buf), ".%06d", (int) us);
        r += buf;
    }
    return r;
}

int64_t now_usecs()
{
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    return (int64_t) tv.tv_sec * 1000000 + tv.tv_usec;
}

bool parse_time_relaxed(const std::string& s, int64_t& usecs)
{
    date_time_scanner dts;
    exttm tm;
    int rc = dts.scan(s.data(), s.size(), tm, usecs, false);
    return rc > 0;
}
