std::vector<std::pair<std::string, std::string>> embedded_files();

static const char* LEVEL_NAMES[] = {
    "unknown", "trace", "debug5", "debug4", "debug3", "debug2", "debug", "info",
    "stats",   "notice", "warning", "error", "critical", "fatal", "invalid",
};

const char* level_name(int lvl)
{
    if (lvl < 0 || lvl > LEVEL_INVALID) return "unknown";
    return LEVEL_NAMES[lvl];
}

int level_from_name(const std::string& name)
{
    for (int i = 0; i <= LEVEL_INVALID; i++) {
        if (name == LEVEL_NAMES[i]) return i;
    }
    return -1;
}

static int abbrev2level(char c)
{
    switch (tolower((unsigned char) c)) {
        case 't': return LEVEL_TRACE;
        case 'd': return LEVEL_DEBUG;
        case 'i': return LEVEL_INFO;
        case 'n': return LEVEL_NOTICE;
        case 'w': return LEVEL_WARNING;
        case 'e': return LEVEL_ERROR;
        case 'c': return LEVEL_CRITICAL;
        case 'f': return LEVEL_FATAL;
    }
    return LEVEL_UNKNOWN;
}

log_level_t scan_level_in_text(const char* s, size_t len)
{
    static auto RE = regex::compile(
        "(?i)(trace|verbose|debug[2-5]?|info|notice|stats|warn|err|fail|fatal|critical|"
        "emergency|alert|severe)");
    std::vector<regex_capture> caps;
    if (!RE->match(s, len, 0, caps)) return LEVEL_UNKNOWN;
    std::string m = lower(std::string(s + caps[1].start, caps[1].length()));
    if (m == "trace" || m == "verbose") return LEVEL_TRACE;
    if (m == "debug") return LEVEL_DEBUG;
    if (m == "debug2") return LEVEL_DEBUG2;
    if (m == "debug3") return LEVEL_DEBUG3;
    if (m == "debug4") return LEVEL_DEBUG4;
    if (m == "debug5") return LEVEL_DEBUG5;
    if (m == "info") return LEVEL_INFO;
    if (m == "notice") return LEVEL_NOTICE;
    if (m == "stats") return LEVEL_STATS;
    if (m == "warn") return LEVEL_WARNING;
    if (m == "err" || m == "fail") return LEVEL_ERROR;
    if (m == "fatal" || m == "emergency") return LEVEL_FATAL;
    if (m == "critical" || m == "alert" || m == "severe") return LEVEL_CRITICAL;
    return LEVEL_UNKNOWN;
}

log_level_t string2level(const char* s, size_t len)
{
    if (len == 1 || (len > 1 && s[1] == ' ')) {
        int l = abbrev2level(s[0]);
        if (l != LEVEL_UNKNOWN) return (log_level_t) l;
    }
    return scan_level_in_text(s, len);
}

int log_format::convert_level(const std::string& val) const
{
    if (!level_values.empty()) {
        // numeric / exact values
        for (auto& lv : level_values) {
            if (lv.second.is_number()) {
                char* end = nullptr;
                double d = strtod(val.c_str(), &end);
                if (end != val.c_str() && *end == '\0' && d == lv.second.as_double()) {
                    return lv.first;
                }
            }
        }
    }
    if (!level_patterns.empty()) {
        for (auto& lp : level_patterns) {
            if (lp.second->search(val)) return lp.first;
        }
        if (level_values.empty()) return LEVEL_INFO;
    }
    if (!level_values.empty()) return LEVEL_INFO;
    return string2level(val.data(), val.size());
}

static std::vector<std::shared_ptr<log_format>> FORMATS;

std::vector<std::shared_ptr<log_format>>& all_formats()
{
    return FORMATS;
}

std::shared_ptr<log_format> find_format(const std::string& name)
{
    for (auto& f : FORMATS) {
        if (f->name == name) return f;
    }
    return nullptr;
}

static std::vector<std::pair<std::string, std::string>>& emb()
{
    static auto files = embedded_files();
    return files;
}

std::vector<std::string> builtin_data_files(const std::string& suffix)
{
    std::vector<std::string> r;
    for (auto& e : emb()) {
        if (endswith(e.first, suffix)) r.push_back(e.first);
    }
    return r;
}

const std::string* builtin_data(const std::string& name)
{
    for (auto& e : emb()) {
        if (e.first == name) return &e.second;
    }
    return nullptr;
}

static value_kind kind_from_string(const std::string& k)
{
    if (k == "integer") return value_kind::integer;
    if (k == "float") return value_kind::real;
    if (k == "boolean") return value_kind::boolean;
    if (k == "json") return value_kind::json;
    if (k == "struct") return value_kind::strct;
    if (k == "quoted") return value_kind::quoted;
    if (k == "timestamp") return value_kind::timestamp;
    if (k == "any") return value_kind::any;
    if (k == "xml") return value_kind::xml;
    return value_kind::string;
}

static void add_value(log_format& fmt, const std::string& name, const js::value* def)
{
    if (fmt.value_index.count(name)) return;
    value_def vd;
    vd.name = name;
    if (def && def->is_object()) {
        if (auto* k = def->get("kind")) vd.kind = kind_from_string(k->as_string());
        if (auto* v = def->get("identifier")) vd.identifier = v->as_bool();
        if (auto* v = def->get("foreign-key")) vd.foreign_key = v->as_bool();
        if (auto* v = def->get("hidden")) vd.hidden = v->as_bool();
        if (auto* v = def->get("collate")) vd.collate = v->as_string();
        if (auto* v = def->get("description")) vd.description = v->as_string();
        if (auto* v = def->get("rewriter")) vd.rewriter = v->as_string();
        if (auto* u = def->get("unit")) {
            if (auto* f = u->get("field")) vd.unit_field = f->as_string();
        }
    }
    fmt.value_index[name] = (int) fmt.values.size();
    vd.column = (int) fmt.values.size();
    fmt.values.push_back(vd);
}

static bool build_format(const std::string& name, const js::value& def, const std::string& path,
                         std::vector<format_error>& errors, std::shared_ptr<log_format>& out)
{
    auto fmt = std::make_shared<log_format>();
    fmt->name = name;
    fmt->source_path = path;
    if (auto* v = def.get("title")) fmt->title = v->as_string();
    if (auto* v = def.get("description")) fmt->description = v->as_string();
    if (auto* v = def.get("file-type")) fmt->is_json = v->as_string() == "json";
    if (auto* v = def.get("json")) fmt->is_json = fmt->is_json || v->as_bool();
    if (auto* v = def.get("multiline")) fmt->multiline = v->as_bool(true);
    if (auto* v = def.get("convert-to-local-time")) fmt->convert_to_local = v->as_bool(true);
    if (auto* v = def.get("level-field")) fmt->level_field = v->as_string();
    if (auto* v = def.get("level-pointer")) fmt->level_pointer = v->as_string();
    if (auto* v = def.get("opid-field")) fmt->opid_field = v->as_string();
    if (auto* v = def.get("thread-id-field")) fmt->thread_id_field = v->as_string();
    if (auto* v = def.get("src-file-field")) fmt->src_file_field = v->as_string();
    if (auto* v = def.get("src-line-field")) fmt->src_line_field = v->as_string();
    if (auto* v = def.get("body-field")) fmt->body_field = v->as_string();
    if (auto* v = def.get("duration-field")) fmt->duration_field = v->as_string();
    if (auto* v = def.get("hide-extra")) fmt->hide_extra = v->as_bool();
    if (auto* v = def.get("timestamp-field")) fmt->timestamp_field = v->as_string();
    if (auto* v = def.get("timestamp-divisor")) {
        fmt->timestamp_divisor = (int64_t) v->as_double();
        if (fmt->timestamp_divisor <= 0) fmt->timestamp_divisor = 1;
    }
    if (auto* v = def.get("max-unrecognized-lines")) fmt->max_unrecognized_lines = (int) v->as_int();
    if (auto* v = def.get("file-pattern")) {
        fmt->file_pattern = v->as_string();
        fmt->file_pattern_re = regex::compile(fmt->file_pattern);
    }
    if (auto* v = def.get("timestamp-format")) {
        if (v->is_array()) {
            for (auto& e : *v->arr) fmt->timestamp_formats.push_back(e.as_string());
        }
    }
    if (auto* v = def.get("sample")) {
        if (v->is_array()) {
            for (auto& e : *v->arr) {
                if (auto* l = e.get("line")) fmt->samples.push_back(l->as_string());
            }
        }
    }
    if (auto* lv = def.get("level")) {
        if (lv->is_object()) {
            for (auto& kv : *lv->obj) {
                int l = level_from_name(kv.first);
                if (l < 0) continue;
                if (kv.second.is_number()) {
                    fmt->level_values.emplace_back(l, kv.second);
                } else if (kv.second.is_string()) {
                    auto re = regex::compile(kv.second.s);
                    if (re) fmt->level_patterns.emplace_back(l, re);
                }
            }
            std::stable_sort(fmt->level_patterns.begin(), fmt->level_patterns.end(),
                             [](const auto& a, const auto& b) { return a.first < b.first; });
        }
    }
    const js::value* values = def.get("value");
    if (auto* rx = def.get("regex")) {
        if (rx->is_object()) {
            std::vector<std::pair<std::string, const js::value*>> pats;
            for (auto& kv : *rx->obj) pats.emplace_back(kv.first, &kv.second);
            std::sort(pats.begin(), pats.end(),
                      [](const auto& a, const auto& b) { return a.first < b.first; });
            for (auto& p : pats) {
                format_pattern fp;
                fp.name = p.first;
                if (auto* pt = p.second->get("pattern")) fp.text = pt->as_string();
                std::string err;
                int erroff = 0;
                fp.re = regex::compile(fp.text, &err, &erroff);
                if (!fp.re) {
                    format_error fe;
                    fe.message = "invalid regex for pattern " + p.first + " in format " + name;
                    fe.reason = err;
                    fe.location = path;
                    errors.push_back(fe);
                    return false;
                }
                fp.ts_idx = fp.re->name_index("timestamp");
                fp.body_idx = fp.re->name_index("body");
                fp.level_idx = fp.re->name_index(fmt->level_field);
                for (auto& nm : fp.re->names()) {
                    const std::string& cn = nm.first;
                    if (cn == "timestamp" || cn == "body") continue;
                    const js::value* vdef = values ? values->get(cn) : nullptr;
                    if (!vdef) continue;
                    add_value(*fmt, cn, vdef);
                }
                fmt->patterns.push_back(std::move(fp));
            }
            for (auto& fp : fmt->patterns) {
                for (auto& nm : fp.re->names()) {
                    auto it = fmt->value_index.find(nm.first);
                    if (it != fmt->value_index.end()) {
                        fp.cap_to_value.emplace_back(nm.second, it->second);
                    }
                }
            }
        }
    }
    if (fmt->is_json && values && values->is_object()) {
        for (auto& kv : *values->obj) {
            add_value(*fmt, kv.first, &kv.second);
        }
    } else if (values && values->is_object()) {
        // values not appearing in patterns are still defined (after)
    }
    if (auto* lf = def.get("line-format")) {
        if (lf->is_array()) {
            for (auto& e : *lf->arr) {
                line_format_elem el;
                if (e.is_string()) {
                    el.text = e.s;
                } else if (e.is_object()) {
                    if (auto* f = e.get("field")) {
                        el.is_field = true;
                        el.field = f->as_string();
                    }
                    if (auto* c = e.get("constant")) {
                        el.is_field = false;
                        el.text = c->as_string();
                    }
                    if (auto* d = e.get("default-value")) {
                        el.has_default = true;
                        el.default_value = d->as_string();
                    }
                    if (auto* p = e.get("prefix")) el.prefix = p->as_string();
                    if (auto* s = e.get("suffix")) el.suffix = s->as_string();
                    if (auto* m = e.get("min-width")) el.min_width = (int) m->as_int();
                    if (auto* m = e.get("max-width")) el.max_width = (int) m->as_int();
                    if (auto* a = e.get("align")) el.align = a->as_string();
                    if (auto* o = e.get("overflow")) el.overflow = o->as_string();
                    if (auto* t = e.get("text-transform")) el.text_transform = t->as_string();
                    if (auto* a = e.get("auto-width")) el.auto_width = a->as_bool();
                    if (auto* t = e.get("timestamp-format")) el.timestamp_format = t->as_string();
                }
                fmt->line_format.push_back(el);
            }
        }
    }
    if (auto* st = def.get("search-table")) {
        if (st->is_object()) {
            for (auto& kv : *st->obj) {
                search_table_def sd;
                sd.name = kv.first;
                if (auto* p = kv.second.get("pattern")) sd.pattern = p->as_string();
                if (auto* l = kv.second.get("level")) sd.level = l->as_string();
                sd.re = regex::compile(sd.pattern);
                if (sd.re) fmt->search_tables.push_back(sd);
            }
        }
    }
    if (!fmt->is_json && fmt->patterns.empty()) {
        format_error fe;
        fe.message = "“" + name + "” is not a valid log format";
        fe.reason = "no regexes specified";
        fe.location = path;
        errors.push_back(fe);
        return false;
    }
    out = fmt;
    return true;
}

static std::shared_ptr<log_format> make_generic()
{
    auto fmt = std::make_shared<log_format>();
    fmt->name = "generic_log";
    fmt->title = "Generic Log";
    fmt->description = "The default format for log files that have a timestamp";
    fmt->is_generic = true;
    const char* pats[] = {
        R"(^(?:\*\*\*\s+)?(?<timestamp>@[0-9a-zA-Z]{16,24})\s*(?<body>.*)$)",
        R"((?i)^(?:\*\*\*\s+)?(?<timestamp>(?:\s|\d{4}[\-\/]\d{2}[\-\/]\d{2}|T|\d{1,2}:\d{2}(?::\d{2}(?:[\.,]\d{1,9})?)?|Z|[+\-]\d{2}:?\d{2}|(?!ERR|INFO|WARN)[A-Z]{3,4})+)[:|\s]?\[?(?<level>trc|trace|dbg|debug|info|warn(?:ing)?|err(?:or)?)\]?(?::\s*|\s+)(?<body>.*)$)",
        R"(^(?:\*\*\*\s+)?(?<timestamp>[\w:+/\.-]+) \[\w (?<body>.*)$)",
        R"(^(?:\*\*\*\s+)?(?<timestamp>[\w:+,/\.-]+) (?<body>.*)$)",
        R"(^(?:\*\*\*\s+)?\[(?<timestamp>[^\]]+)\]\s*(?<level>\w+)\s+(?<body>.*)$)",
        R"(^(?:\*\*\*\s+)?\[(?<timestamp>[^\]]+)\]\s*(?<body>.*)$)",
        R"(^(?:\*\*\*\s+)?(?<timestamp>\S+(?:\s+\S+)*)\s+(?<body>.*)$)",
    };
    int idx = 0;
    for (auto* p : pats) {
        format_pattern fp;
        fp.name = "generic" + std::to_string(idx++);
        fp.text = p;
        fp.re = regex::compile(p);
        fp.ts_idx = fp.re->name_index("timestamp");
        fp.body_idx = fp.re->name_index("body");
        fp.level_idx = fp.re->name_index("level");
        fmt->patterns.push_back(std::move(fp));
    }
    return fmt;
}

static bool format_matches_sample(const log_format& fmt, const std::string& line)
{
    if (fmt.is_json) return false;
    std::vector<regex_capture> caps;
    for (auto& p : fmt.patterns) {
        if (!p.re->match(line, caps)) continue;
        if (p.ts_idx >= 0 && caps[p.ts_idx].valid()) {
            date_time_scanner dts;
            if (!fmt.timestamp_formats.empty()) dts.custom = &fmt.timestamp_formats;
            exttm tm;
            int64_t us;
            if (dts.scan(line.data() + caps[p.ts_idx].start, caps[p.ts_idx].length(), tm, us,
                         false)
                < 0)
                continue;
        }
        return true;
    }
    return false;
}

static void load_format_text(const std::string& text, const std::string& path,
                             std::vector<std::shared_ptr<log_format>>& out,
                             std::vector<format_error>& errors)
{
    js::value root;
    js::parse_error perr;
    if (!js::parse(text, root, &perr)) {
        format_error fe;
        fe.message = "invalid JSON";
        fe.reason = perr.msg;
        fe.location = path + ":" + std::to_string(perr.line);
        errors.push_back(fe);
        return;
    }
    if (!root.is_object()) return;
    for (auto& kv : *root.obj) {
        if (!kv.first.empty() && kv.first[0] == '$') continue;
        if (!kv.second.is_object()) continue;
        std::shared_ptr<log_format> fmt;
        if (build_format(kv.first, kv.second, path, errors, fmt)) {
            // replace existing
            bool replaced = false;
            for (auto& f : out) {
                if (f->name == fmt->name) {
                    f = fmt;
                    replaced = true;
                }
            }
            if (!replaced) out.push_back(fmt);
        }
    }
}

static void scan_dir_formats(const std::string& dir, std::vector<std::shared_ptr<log_format>>& out,
                             std::vector<format_error>& errors)
{
    DIR* d = opendir(dir.c_str());
    if (!d) return;
    std::vector<std::string> names;
    while (auto* ent = readdir(d)) {
        names.push_back(ent->d_name);
    }
    closedir(d);
    std::sort(names.begin(), names.end());
    for (auto& n : names) {
        if (n == "." || n == "..") continue;
        std::string full = dir + "/" + n;
        struct stat st;
        if (stat(full.c_str(), &st) != 0) continue;
        if (S_ISDIR(st.st_mode)) {
            scan_dir_formats(full, out, errors);
        } else if (endswith(n, ".json")) {
            std::string content;
            if (read_file(full, content)) {
                load_format_text(content, full, out, errors);
            }
        }
    }
}

std::vector<format_error> load_formats(const std::vector<std::string>& extra_dirs)
{
    std::vector<format_error> errors;
    std::vector<std::shared_ptr<log_format>> loaded;
    for (auto& e : emb()) {
        if (startswith(e.first, "formats/") && endswith(e.first, ".json")) {
            load_format_text(e.second, e.first, loaded, errors);
        }
    }
    const char* home = getenv("HOME");
    if (home) {
        scan_dir_formats(std::string(home) + "/.lnav/formats/installed", loaded, errors);
    }
    for (auto& d : extra_dirs) {
        scan_dir_formats(d + "/formats", loaded, errors);
    }
    // validate samples present
    std::vector<std::shared_ptr<log_format>> valid;
    for (auto& f : loaded) {
        if (f->samples.empty() && !f->is_json) {
            format_error fe;
            fe.message = "“" + f->name + "” is not a valid log format";
            fe.reason = "log message samples must be included in a format definition";
            fe.location = f->source_path;
            errors.push_back(fe);
            continue;
        }
        valid.push_back(f);
    }
    // sort alphabetically first, then order so that formats whose samples match
    // other formats come before them.
    std::sort(valid.begin(), valid.end(),
              [](const auto& a, const auto& b) { return a->name < b->name; });
    size_t n = valid.size();
    std::vector<std::set<size_t>> before(n);  // before[i] = set of j that must precede i
    for (size_t i = 0; i < n; i++) {
        for (auto& s : valid[i]->samples) {
            for (size_t j = 0; j < n; j++) {
                if (i == j) continue;
                if (format_matches_sample(*valid[j], s)) {
                    // sample of i matches j, so i is more specific: i before j
                    before[j].insert(i);
                }
            }
        }
    }
    std::vector<int> state(n, 0);
    std::vector<std::shared_ptr<log_format>> ordered;
    std::function<void(size_t)> visit = [&](size_t i) {
        if (state[i] != 0) return;
        state[i] = 1;
        for (auto j : before[i]) {
            if (state[j] == 0) visit(j);
        }
        state[i] = 2;
        ordered.push_back(valid[i]);
    };
    for (size_t i = 0; i < n; i++) visit(i);
    ordered.push_back(make_generic());
    FORMATS = ordered;
    return errors;
}

bool scan_regex_line(format_state& st, const std::string& line, scan_result& res)
{
    auto& fmt = *st.fmt;
    std::vector<regex_capture> caps;
    int npats = (int) fmt.patterns.size();
    for (int i = 0; i < npats; i++) {
        int pi = st.pattern_lock >= 0 ? st.pattern_lock : i;
        if (st.pattern_lock >= 0 && i > 0) break;
        auto& pat = fmt.patterns[pi];
        if (!pat.re->match(line, caps)) continue;
        if (pat.ts_idx < 0 || !caps[pat.ts_idx].valid()) continue;
        exttm tm;
        int64_t us = 0;
        auto saved_lock = st.dts.fmt_lock;
        int rc = st.dts.scan(line.data() + caps[pat.ts_idx].start, caps[pat.ts_idx].length(), tm,
                             us, st.dts.fmt_lock >= 0);
        if (rc < 0) {
            st.dts.fmt_lock = saved_lock;
            continue;
        }
        res.time_usecs = us;
        res.tm = tm;
        res.pattern = pi;
        res.ts_start = caps[pat.ts_idx].start;
        res.ts_end = caps[pat.ts_idx].end;
        if (pat.body_idx >= 0 && caps[pat.body_idx].valid()) {
            res.body_start = caps[pat.body_idx].start;
            res.body_end = caps[pat.body_idx].end;
        } else {
            res.body_start = res.body_end = -1;
        }
        if (fmt.is_generic) {
            if (pat.level_idx >= 0 && caps[pat.level_idx].valid()) {
                res.level = string2level(line.data() + caps[pat.level_idx].start,
                                         caps[pat.level_idx].length());
            } else if (res.body_start >= 0) {
                res.level = scan_level_in_text(line.data() + res.body_start,
                                               res.body_end - res.body_start);
            } else {
                res.level = LEVEL_UNKNOWN;
            }
        } else {
            int lidx = pat.level_idx;
            if (fmt.level_field == "body") lidx = pat.body_idx;
            if (lidx >= 0 && caps[lidx].valid()) {
                res.level = fmt.convert_level(
                    std::string(line.data() + caps[lidx].start, caps[lidx].length()));
            } else {
                res.level = LEVEL_INFO;
            }
        }
        st.pattern_lock = pi;
        st.last_flags = tm.flags;
        return true;
    }
    return false;
}
