bool startswith(const std::string& s, const std::string& prefix)
{
    return s.size() >= prefix.size() && s.compare(0, prefix.size(), prefix) == 0;
}

bool endswith(const std::string& s, const std::string& suffix)
{
    return s.size() >= suffix.size()
        && s.compare(s.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string lower(const std::string& s)
{
    std::string r = s;
    for (auto& c : r) c = tolower((unsigned char) c);
    return r;
}

std::string upper(const std::string& s)
{
    std::string r = s;
    for (auto& c : r) c = toupper((unsigned char) c);
    return r;
}

std::string trim(const std::string& s)
{
    return ltrim(rtrim(s));
}

std::string rtrim(const std::string& s)
{
    size_t e = s.size();
    while (e > 0 && isspace((unsigned char) s[e - 1])) e--;
    return s.substr(0, e);
}

std::string ltrim(const std::string& s)
{
    size_t b = 0;
    while (b < s.size() && isspace((unsigned char) s[b])) b++;
    return s.substr(b);
}

bool read_file(const std::string& path, std::string& out)
{
    FILE* f = fopen(path.c_str(), "rb");
    if (!f) return false;
    out.clear();
    char buf[65536];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) out.append(buf, n);
    fclose(f);
    return true;
}

std::vector<std::string> split(const std::string& s, char sep)
{
    std::vector<std::string> r;
    size_t start = 0;
    while (true) {
        size_t p = s.find(sep, start);
        if (p == std::string::npos) {
            r.push_back(s.substr(start));
            break;
        }
        r.push_back(s.substr(start, p - start));
        start = p + 1;
    }
    return r;
}

std::vector<std::string> split_lines(const std::string& s)
{
    std::vector<std::string> r;
    size_t start = 0;
    while (start < s.size()) {
        size_t p = s.find('\n', start);
        if (p == std::string::npos) {
            r.push_back(s.substr(start));
            break;
        }
        r.push_back(s.substr(start, p - start));
        start = p + 1;
    }
    return r;
}

uint32_t utf8_decode(const std::string& s, size_t& pos)
{
    unsigned char c = s[pos];
    if (c < 0x80) {
        pos++;
        return c;
    }
    int n = 0;
    uint32_t cp = 0;
    if ((c & 0xE0) == 0xC0) {
        n = 1;
        cp = c & 0x1F;
    } else if ((c & 0xF0) == 0xE0) {
        n = 2;
        cp = c & 0x0F;
    } else if ((c & 0xF8) == 0xF0) {
        n = 3;
        cp = c & 0x07;
    } else {
        pos++;
        return 0xFFFD;
    }
    if (pos + n >= s.size() + 0 && pos + n > s.size() - 1 + 1) {
        // not enough bytes
    }
    if (pos + n >= s.size() + 1) {
        pos++;
        return 0xFFFD;
    }
    for (int i = 1; i <= n; i++) {
        if (pos + i >= s.size()) {
            pos++;
            return 0xFFFD;
        }
        unsigned char cc = s[pos + i];
        if ((cc & 0xC0) != 0x80) {
            pos++;
            return 0xFFFD;
        }
        cp = (cp << 6) | (cc & 0x3F);
    }
    pos += n + 1;
    return cp;
}

void utf8_append(std::string& out, uint32_t cp)
{
    if (cp < 0x80) {
        out.push_back((char) cp);
    } else if (cp < 0x800) {
        out.push_back((char) (0xC0 | (cp >> 6)));
        out.push_back((char) (0x80 | (cp & 0x3F)));
    } else if (cp < 0x10000) {
        out.push_back((char) (0xE0 | (cp >> 12)));
        out.push_back((char) (0x80 | ((cp >> 6) & 0x3F)));
        out.push_back((char) (0x80 | (cp & 0x3F)));
    } else {
        out.push_back((char) (0xF0 | (cp >> 18)));
        out.push_back((char) (0x80 | ((cp >> 12) & 0x3F)));
        out.push_back((char) (0x80 | ((cp >> 6) & 0x3F)));
        out.push_back((char) (0x80 | (cp & 0x3F)));
    }
}

bool is_valid_utf8(const std::string& s)
{
    size_t pos = 0;
    while (pos < s.size()) {
        unsigned char c = s[pos];
        if (c < 0x80) {
            pos++;
            continue;
        }
        size_t before = pos;
        uint32_t cp = utf8_decode(s, pos);
        if (cp == 0xFFFD && pos == before + 1) return false;
    }
    return true;
}

int utf8_char_width(uint32_t cp)
{
    if (cp == 0) return 0;
    if (cp < 32 || (cp >= 0x7f && cp < 0xa0)) return 0;
    // combining marks
    if ((cp >= 0x0300 && cp <= 0x036F) || (cp >= 0x200B && cp <= 0x200F) || cp == 0xFE0F
        || (cp >= 0x20D0 && cp <= 0x20FF))
        return 0;
    if ((cp >= 0x1100 && cp <= 0x115F) || cp == 0x2329 || cp == 0x232A
        || (cp >= 0x2E80 && cp <= 0x303E) || (cp >= 0x3041 && cp <= 0x33FF)
        || (cp >= 0x3400 && cp <= 0x4DBF) || (cp >= 0x4E00 && cp <= 0x9FFF)
        || (cp >= 0xA000 && cp <= 0xA4CF) || (cp >= 0xAC00 && cp <= 0xD7A3)
        || (cp >= 0xF900 && cp <= 0xFAFF) || (cp >= 0xFE30 && cp <= 0xFE4F)
        || (cp >= 0xFF00 && cp <= 0xFF60) || (cp >= 0xFFE0 && cp <= 0xFFE6)
        || (cp >= 0x1F300 && cp <= 0x1F64F) || (cp >= 0x1F900 && cp <= 0x1F9FF)
        || (cp >= 0x1F680 && cp <= 0x1F6FF) || (cp >= 0x20000 && cp <= 0x3FFFD))
        return 2;
    return 1;
}

int utf8_width(const std::string& s)
{
    int w = 0;
    size_t pos = 0;
    while (pos < s.size()) {
        unsigned char c = s[pos];
        if (c < 0x80) {
            pos++;
            w += 1;
            continue;
        }
        uint32_t cp = utf8_decode(s, pos);
        w += utf8_char_width(cp);
    }
    return w;
}

std::string replace_all(const std::string& s, const std::string& from, const std::string& to)
{
    if (from.empty()) return s;
    std::string r;
    size_t start = 0;
    while (true) {
        size_t p = s.find(from, start);
        if (p == std::string::npos) {
            r += s.substr(start);
            break;
        }
        r += s.substr(start, p - start);
        r += to;
        start = p + from.size();
    }
    return r;
}

std::string realpath_str(const std::string& p)
{
    char buf[PATH_MAX];
    if (realpath(p.c_str(), buf)) return buf;
    return p;
}

std::string getcwd_str()
{
    char buf[PATH_MAX];
    if (getcwd(buf, sizeof(buf))) return buf;
    return ".";
}

std::string abspath(const std::string& p)
{
    if (!p.empty() && p[0] == '/') return p;
    return getcwd_str() + "/" + p;
}

bool is_number_str(const std::string& s)
{
    if (s.empty()) return false;
    char* end = nullptr;
    strtod(s.c_str(), &end);
    return end && *end == '\0';
}

std::vector<std::string> shlex_split(const std::string& s, bool* ok)
{
    std::vector<std::string> r;
    std::string cur;
    bool in_tok = false;
    char quote = 0;
    if (ok) *ok = true;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (quote) {
            if (c == quote) {
                quote = 0;
            } else if (c == '\\' && quote == '"' && i + 1 < s.size()) {
                cur.push_back(s[++i]);
            } else {
                cur.push_back(c);
            }
            continue;
        }
        if (c == '\'' || c == '"') {
            quote = c;
            in_tok = true;
            continue;
        }
        if (c == '\\' && i + 1 < s.size()) {
            cur.push_back(s[++i]);
            in_tok = true;
