        n = 1;
        cp = c & 0x1F;
    } else if ((c & 0xF0) == 0xE0) {
        n = 2;
        cp = c & 0x0F;
    } else if ((c & 0xF8) == 0xF0) {
        n = 3;
        cp = c & 0x07;
    } else {
        pos++;
        return 0xFFFD;
    }
    if (pos + n >= s.size() + 0 && pos + n > s.size() - 1 + 1) {
