void compute_unique_paths(std::vector<std::shared_ptr<logfile>>& files)
{
    // shortest unique suffix of path components
    std::vector<std::vector<std::string>> comps;
    for (auto& f : files) {
        auto parts = split(f->path, '/');
        std::vector<std::string> nonempty;
        for (auto& p : parts)
            if (!p.empty()) nonempty.push_back(p);
        comps.push_back(nonempty);
    }
    for (size_t i = 0; i < files.size(); i++) {
        auto& c = comps[i];
        size_t depth = 1;
        while (depth <= c.size()) {
            bool clash = false;
            for (size_t j = 0; j < files.size(); j++) {
                if (i == j) continue;
                auto& d = comps[j];
                if (d.size() < depth) continue;
                bool same = true;
                for (size_t k = 0; k < depth; k++) {
                    if (c[c.size() - 1 - k] != d[d.size() - 1 - k]) {
                        same = false;
                        break;
                    }
                }
                if (same) {
                    clash = true;
                    break;
                }
            }
            if (!clash) break;
            depth++;
        }
        std::string up;
        for (size_t k = c.size() - std::min(depth, c.size()); k < c.size(); k++) {
            if (!up.empty()) up += "/";
            up += c[k];
        }
        files[i]->unique_path = up;
    }
}
