static void check_for_new_year(std::vector<logline>& meta, int upto, const exttm& etm,
                               int64_t new_usecs)
{
    // find last valid message time
    int64_t last = 0;
    bool found = false;
    for (int i = upto - 1; i >= 0; i--) {
        if (!meta[i].continuation && meta[i].has_tm) {
            last = meta[i].actual_usecs;
            found = true;
            break;
        }
    }
    if (!found) return;
    int64_t diff = (last - new_usecs) / 1000000;
    if (diff <= 0) return;
    int off_year = 0, off_month = 0, off_day = 0, off_hour = 0;
    if ((etm.flags & ETF_MONTH_SET) && diff >= 24 * 60 * 60) {
        off_year = 1;
    } else if (diff >= 24 * 60 * 60) {
        off_month = 1;
    } else if (!(etm.flags & ETF_DAY_SET) && diff >= 60 * 60) {
        off_day = 1;
    } else if (!(etm.flags & ETF_DAY_SET)) {
        off_hour = 1;
    } else {
        return;
    }
    for (int i = 0; i < upto; i++) {
        auto& ll = meta[i];
        int64_t secs = ll.actual_usecs / 1000000;
        int64_t us = ll.actual_usecs % 1000000;
        exttm otm = epoch_to_tm(secs);
        otm.year -= off_year;
        otm.mon -= off_month;
        if (otm.mon < 0) otm.mon += 12;
        int64_t ns = tm_to_epoch(otm);
        ns -= off_day * 24 * 60 * 60 + off_hour * 60 * 60;
        ll.actual_usecs = ns * 1000000 + us;
        ll.time_usecs = ll.actual_usecs;
    }
}

