static bool eval_filter_expr(int file, int msg);

bool app_state::msg_passes_filters(int file, int msg, std::vector<int>* matched_in)
{
    auto& lf = *files[file];
    auto& m = lf.msgs[msg];
    auto& ll = lf.meta[m.first_line];
    if (min_level > LEVEL_UNKNOWN && ll.level < min_level && ll.level != LEVEL_INVALID) {
        return false;
    }
    if (min_level > LEVEL_UNKNOWN && ll.level == LEVEL_INVALID) {
        // invalid lines are kept
    }
    if (hide_before && ll.time_usecs < *hide_before) return false;
    if (hide_after && ll.time_usecs > *hide_after) return false;
    if (has_since && ll.time_usecs < since) return false;
    if (has_until && ll.time_usecs > until) return false;
    bool any_in = false;
    bool matched_any_in = false;
    std::string text;
    bool text_loaded = false;
    for (auto& f : filters) {
        if (!f.enabled) continue;
        if (f.lang != "regex") continue;
        if (!text_loaded) {
            text = lf.msg_text(msg);
            text_loaded = true;
        }
        bool hit = false;
        // match per line
        if (m.is_json) {
            for (auto& l : m.json_lines) {
                if (f.re->search(l)) {
                    hit = true;
                    break;
                }
            }
        } else {
            for (int i = 0; i < m.line_count; i++) {
                if (f.re->search(lf.lines[m.first_line + i])) {
                    hit = true;
                    break;
                }
            }
        }
        if (f.is_in) {
            any_in = true;
            if (hit) {
                matched_any_in = true;
                if (matched_in) matched_in->push_back(f.id);
            }
        } else if (hit) {
            return false;
        }
    }
    if (any_in && !matched_any_in) return false;
    if (!filter_expr.empty() && !eval_filter_expr(file, msg)) return false;
    return true;
}

extern bool sql_eval_msg_expr(sqlite3_stmt* stmt, int file, int msg);

static bool eval_filter_expr(int file, int msg)
{
    if (!APP.filter_expr_stmt) return true;
    return sql_eval_msg_expr(APP.filter_expr_stmt, file, msg);
}

void app_state::rebuild_log_view()
{
    log_dirty = false;
    struct ent {
        int64_t t;
        int file;
        int msg;
    };
    std::vector<ent> ents;
    for (int fi = 0; fi < (int) files.size(); fi++) {
        auto& lf = *files[fi];
        if (!lf.is_log() || !lf.visible) continue;
        for (int mi = 0; mi < (int) lf.msgs.size(); mi++) {
            auto& ll = lf.meta[lf.msgs[mi].first_line];
            ents.push_back({ll.time_usecs, fi, mi});
        }
    }
    std::stable_sort(ents.begin(), ents.end(), [](const ent& a, const ent& b) {
        if (a.t != b.t) return a.t < b.t;
        return false;
    });
    log_all.clear();
    log_view.clear();
    for (auto& f : filters) f.hits = 0;
    for (auto& e : ents) {
        auto& lf = *files[e.file];
        auto& m = lf.msgs[e.msg];
        int nsub = m.is_json ? (int) m.json_lines.size() : m.line_count;
        std::vector<int> matched;
        bool pass = msg_passes_filters(e.file, e.msg, &matched);
        for (int s = 0; s < nsub; s++) {
            view_line vl;
            vl.file = e.file;
            vl.msg = e.msg;
            vl.sub = s;
            vl.line = m.is_json ? m.first_line : m.first_line + s;
            log_all.push_back(vl);
            if (pass) log_view.push_back(vl);
        }
        if (pass) {
            for (auto& f : filters) {
                if (!f.enabled) continue;
                if (f.is_in && std::find(matched.begin(), matched.end(), f.id) != matched.end())
                    f.hits++;
            }
        } else {
            // count out filter hits
            for (auto& f : filters) {
                if (!f.enabled || f.is_in) continue;
                bool hit = false;
                if (m.is_json) {
                    for (auto& l : m.json_lines)
                        if (f.re->search(l)) hit = true;
                } else {
                    for (int i = 0; i < m.line_count; i++)
                        if (f.re->search(lf.lines[m.first_line + i])) hit = true;
                }
                if (hit) f.hits++;
            }
        }
    }
    if (log_top >= (int) log_view.size()) {
        log_top = log_view.empty() ? 0 : (int) log_view.size() - 1;
    }
}

void app_state::rebuild_text_view()
{
    text_visible.clear();
    if (text_file < 0 || text_file >= (int) files.size()) return;
    auto& lf = *files[text_file];
    bool any_in = false;
    for (auto& f : text_filters)
        if (f.enabled && f.is_in) any_in = true;
    for (auto& f : text_filters) f.hits = 0;
    for (int i = 0; i < (int) lf.lines.size(); i++) {
        bool pass = true;
        bool in_hit = false;
        for (auto& f : text_filters) {
            if (!f.enabled) continue;
            bool hit = f.re->search(lf.lines[i]);
            if (f.is_in) {
                if (hit) {
                    in_hit = true;
                    f.hits++;
                }
            } else if (hit) {
                pass = false;
                f.hits++;
            }
        }
        if (any_in && !in_hit) pass = false;
        if (pass) text_visible.push_back(i);
    }
}

std::string scrub_ws(const std::string& s)
{
    std::string r;
    r.reserve(s.size());
    for (char c : s) {
        if (c == '\n') r += "\xe2\x90\x8a";
        else if (c == '\t') r += "\xe2\x87\xa5";
        else if (c == '\r') r += "\xe2\x90\x8d";
        else r.push_back(c);
    }
    return r;
}

std::string truncate_cell(const std::string& s, int maxw)
{
    int w = utf8_width(s);
    if (w <= maxw) return s;
    // keep first half, ellipsis, last part
    int head = maxw / 2;
    int tail = maxw - head - 1;
    std::string r;
    size_t pos = 0;
    int cw = 0;
    while (pos < s.size()) {
        size_t before = pos;
        uint32_t cp = utf8_decode(s, pos);
        int chw = utf8_char_width(cp);
        if ((unsigned char) s[before] < 0x80) chw = 1;
        if (cw + chw > head) {
            pos = before;
            break;
        }
        cw += chw;
        r.append(s, before, pos - before);
    }
    r += "\xe2\x8b\xaf";
    // collect tail
    std::vector<std::pair<size_t, int>> chars;
    size_t p2 = 0;
    while (p2 < s.size()) {
        size_t before = p2;
        uint32_t cp = utf8_decode(s, p2);
        int chw = utf8_char_width(cp);
        if ((unsigned char) s[before] < 0x80) chw = 1;
        chars.emplace_back(before, chw);
    }
    int tw = 0;
    size_t start = s.size();
    for (int i = (int) chars.size() - 1; i >= 0; i--) {
        if (tw + chars[i].second > tail) break;
        tw += chars[i].second;
        start = chars[i].first;
    }
    r += s.substr(start);
    return r;
}
