static std::shared_ptr<log_table_def> make_search_table(const std::string& name,
                                                        std::shared_ptr<regex> re,
                                                        std::shared_ptr<log_format> fmt,
                                                        const std::string& level)
{
    auto t = std::make_shared<log_table_def>();
    t->name = name;
    t->fmt = fmt;
    t->search_table = true;
    t->search_re = re;
    t->search_level = level;
    add_col(*t, "log_line", "INTEGER", log_col_kind::line);
    add_col(*t, "log_time", "DATETIME", log_col_kind::time);
    add_col(*t, "log_level", "TEXT", log_col_kind::level, false, -1, "loglevel");
    if (fmt) add_format_fields(*t, *fmt);
    add_col(*t, "match_rowid", "INTEGER", log_col_kind::line);
    t->cols.back().field_index = -2;
    add_col(*t, "match_index", "INTEGER", log_col_kind::search_match_index);
    int unnamed = 0;
    for (int i = 1; i <= re->capture_count(); i++) {
        std::string n = re->index_name(i);
        if (n.empty()) n = "col_" + std::to_string(unnamed++);
        add_col(*t, n, "TEXT", log_col_kind::search_capture, false, i);
    }
    add_common_tail(*t);
    return t;
}

// ---------------------------------------------------------------------------
// Row model

struct log_row {
    int file;
    int msg;
    int view_line;  // index in APP.log_view of the first line
    int match_index = 0;
    std::vector<regex_capture> caps;  // search table captures
};

static std::string field_raw_value(const logfile& lf, int msg, const value_def& vd, bool& found);

struct log_vtab {
    sqlite3_vtab base;
    std::shared_ptr<log_table_def> def;
};

struct log_cursor {
    sqlite3_vtab_cursor base;
    std::vector<log_row> rows;
    size_t idx = 0;
    // cached captures for current row
    int cached_row = -1;
    std::vector<regex_capture> caps;
};

static bool table_includes_file(const log_table_def& def, const logfile& lf)
{
    if (def.all_logs) return true;
    if (!def.fmt) return true;
    return lf.fmt == def.fmt || (lf.fmt && lf.fmt->name == def.fmt->name);
}

static std::vector<log_row> build_rows(const log_table_def& def)
{
    APP.ensure_log_view();
    std::vector<log_row> rows;
    const auto& view = APP.log_view;
    for (int vi = 0; vi < (int) view.size(); vi++) {
        auto& vl = view[vi];
        if (vl.sub != 0) continue;
        auto& lf = *APP.files[vl.file];
        if (!table_includes_file(def, lf)) continue;
        if (def.search_table) {
            std::string body = lf.msg_text(vl.msg);
            if (!def.search_level.empty()) {
                int lvl = lf.meta[lf.msgs[vl.msg].first_line].level;
                int want = level_from_name(def.search_level);
                if (want >= 0 && lvl < want) continue;
            }
            std::vector<regex_capture> caps;
            size_t off = 0;
            int mi = 0;
            while (off <= body.size() && def.search_re->match(body.data(), body.size(), off, caps)) {
                log_row r{vl.file, vl.msg, vi, mi++, caps};
                rows.push_back(r);
                if (caps[0].end == caps[0].start) {
                    off = caps[0].end + 1;
                } else {
                    off = caps[0].end;
                }
            }
            continue;
        }
        rows.push_back({vl.file, vl.msg, vi, 0, {}});
    }
    return rows;
}

static int lv_connect(sqlite3* db, void* aux, int argc, const char* const* argv,
                      sqlite3_vtab** ppvt, char** err)
{
    if (argc < 4) {
        *err = sqlite3_mprintf("missing table name");
        return SQLITE_ERROR;
    }
    std::string name = argv[3];
    auto def = find_log_table(name);
    if (!def) {
        *err = sqlite3_mprintf("unknown log table: %s", name.c_str());
        return SQLITE_ERROR;
    }
    std::string sql = "CREATE TABLE x (";
    for (size_t i = 0; i < def->cols.size(); i++) {
        auto& c = def->cols[i].def;
        if (i) sql += ", ";
        sql += "\"" + c.name + "\" " + c.type;
        if (c.hidden) sql += " HIDDEN";
        if (!c.collate.empty()) sql += " COLLATE " + c.collate;
        if (i == 0 && !def->search_table) sql += " PRIMARY KEY";
    }
    sql += ")";
    int rc = sqlite3_declare_vtab(db, sql.c_str());
    if (rc != SQLITE_OK) {
        *err = sqlite3_mprintf("declare failed: %s %s", sqlite3_errmsg(db), sql.c_str());
        return rc;
    }
    auto* vt = new log_vtab();
    memset(&vt->base, 0, sizeof(vt->base));
    vt->def = def;
    *ppvt = &vt->base;
    return SQLITE_OK;
}

static int lv_disconnect(sqlite3_vtab* vt)
{
    delete (log_vtab*) vt;
    return SQLITE_OK;
}

static int lv_best_index(sqlite3_vtab*, sqlite3_index_info* info)
{
    info->estimatedCost = 1000000;
    return SQLITE_OK;
}

static int lv_open(sqlite3_vtab* vt, sqlite3_vtab_cursor** cur)
{
    auto* c = new log_cursor();
    memset(&c->base, 0, sizeof(c->base));
    *cur = &c->base;
    return SQLITE_OK;
}

static int lv_close(sqlite3_vtab_cursor* cur)
{
    delete (log_cursor*) cur;
    return SQLITE_OK;
}

static int lv_filter(sqlite3_vtab_cursor* cur, int, const char*, int, sqlite3_value**)
{
    auto* c = (log_cursor*) cur;
    auto* vt = (log_vtab*) cur->pVtab;
    c->rows = build_rows(*vt->def);
    c->idx = 0;
    c->cached_row = -1;
    return SQLITE_OK;
}

static int lv_next(sqlite3_vtab_cursor* cur)
{
    auto* c = (log_cursor*) cur;
    c->idx++;
    return SQLITE_OK;
}

static int lv_eof(sqlite3_vtab_cursor* cur)
{
    auto* c = (log_cursor*) cur;
    return c->idx >= c->rows.size();
}

static int lv_rowid(sqlite3_vtab_cursor* cur, sqlite3_int64* rowid)
{
    auto* c = (log_cursor*) cur;
    auto* vt = (log_vtab*) cur->pVtab;
    if (vt->def->search_table) {
        *rowid = (sqlite3_int64) c->idx;
    } else {
        *rowid = c->rows[c->idx].view_line;
    }
    return SQLITE_OK;
}

// annotations stored per message
struct msg_annot {
    std::string comment;
    std::string tags;
    std::string part;
    bool has_comment = false, has_tags = false, has_part = false;
};
static std::map<std::pair<int, int>, msg_annot> ANNOTS;

static std::string json_array_of_ints(const std::vector<int>& v)
{
    std::string r = "[";
    for (size_t i = 0; i < v.size(); i++) {
        if (i) r += ",";
        r += std::to_string(v[i]);
    }
    r += "]";
    return r;
}

std::string opid_for_msg(const logfile& lf, int msg);
std::string field_by_name(const logfile& lf, int msg, const std::string& name, bool& found);
extern void msg_format_and_values(const std::string& body, std::string& fmt, std::string& values);

static void result_field(sqlite3_context* ctx, const log_format& fmt, const value_def& vd,
                         const std::string& raw, bool found)
{
    if (!found) {
        sqlite3_result_null(ctx);
        return;
    }
    switch (vd.kind) {
        case value_kind::integer: {
            if (vd.name == fmt.thread_id_field && fmt.is_json) {
                sqlite3_result_text(ctx, raw.c_str(), (int) raw.size(), SQLITE_TRANSIENT);
                return;
            }
            char* end = nullptr;
            long long v = strtoll(raw.c_str(), &end, 10);
            if (end && *end != '\0' && *end != ' ') {
                double d = strtod(raw.c_str(), &end);
                if (end && *end == '\0' && d != (double) (long long) d) {
                    sqlite3_result_double(ctx, d);
                    return;
                }
            }
            sqlite3_result_int64(ctx, v);
            return;
        }
        case value_kind::real: {
            sqlite3_result_double(ctx, strtod(raw.c_str(), nullptr));
            return;
        }
        case value_kind::boolean: {
            std::string l = lower(raw);
            sqlite3_result_int(ctx, (l == "true" || l == "1" || l == "yes" || l == "on") ? 1 : 0);
            return;
        }
        case value_kind::json: {
            sqlite3_result_text(ctx, raw.c_str(), (int) raw.size(), SQLITE_TRANSIENT);
            sqlite3_result_subtype(ctx, 74);
            return;
        }
        default:
            sqlite3_result_text(ctx, raw.c_str(), (int) raw.size(), SQLITE_TRANSIENT);
    }
}

std::string line_hash_for(const logfile& lf, int msg);

static int lv_column(sqlite3_vtab_cursor* cur, sqlite3_context* ctx, int col)
{
    auto* c = (log_cursor*) cur;
    auto* vt = (log_vtab*) cur->pVtab;
    auto& def = *vt->def;
    auto& row = c->rows[c->idx];
    auto& lf = *APP.files[row.file];
    auto& m = lf.msgs[row.msg];
    auto& ll = lf.meta[m.first_line];
    auto& lc = def.cols[col];
    auto key = std::make_pair(row.file, m.first_line);
    switch (lc.kind) {
        case log_col_kind::line:
            if (lc.field_index == -2) {
                sqlite3_result_int64(ctx, (sqlite3_int64) c->idx);
            } else {
                sqlite3_result_int64(ctx, row.view_line);
            }
            break;
        case log_col_kind::time: {
            auto s = format_sql_time(ll.time_usecs);
            sqlite3_result_text(ctx, s.c_str(), -1, SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::actual_time: {
            auto s = format_sql_time(ll.actual_usecs);
            sqlite3_result_text(ctx, s.c_str(), -1, SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::level:
            sqlite3_result_text(ctx, level_name(ll.level), -1, SQLITE_STATIC);
            break;
        case log_col_kind::msg_format:
        case log_col_kind::msg_values: {
            std::string f, v;
            msg_format_and_values(lf.msg_body(row.msg), f, v);
            if (lc.kind == log_col_kind::msg_format) {
                sqlite3_result_text(ctx, f.c_str(), -1, SQLITE_TRANSIENT);
            } else {
                sqlite3_result_text(ctx, v.c_str(), -1, SQLITE_TRANSIENT);
                sqlite3_result_subtype(ctx, 74);
            }
            break;
        }
        case log_col_kind::msg_schema: {
            std::string f, v;
            msg_format_and_values(lf.msg_body(row.msg), f, v);
            std::string h = line_hash_for(lf, row.msg);
            sqlite3_result_null(ctx);
            break;
        }
        case log_col_kind::msg_src:
        case log_col_kind::stack_trace:
        case log_col_kind::sticky_mark:
            if (lc.kind == log_col_kind::sticky_mark) {
                sqlite3_result_int(ctx, 0);
            } else {
                sqlite3_result_null(ctx);
            }
            break;
        case log_col_kind::field: {
            auto& vd = def.fmt->values[lc.field_index];
            bool found = false;
            std::string raw = field_raw_value(lf, row.msg, vd, found);
            result_field(ctx, *def.fmt, vd, raw, found);
            break;
        }
        case log_col_kind::search_capture: {
            auto& cap = row.caps[lc.field_index];
            if (!cap.valid()) {
                sqlite3_result_null(ctx);
            } else {
                std::string body = lf.msg_text(row.msg);
                sqlite3_result_text(ctx, body.data() + cap.start, cap.length(), SQLITE_TRANSIENT);
            }
            break;
        }
        case log_col_kind::search_match_index:
            sqlite3_result_int(ctx, row.match_index);
            break;
        case log_col_kind::part: {
            auto it = ANNOTS.find(key);
            if (it != ANNOTS.end() && it->second.has_part) {
                sqlite3_result_text(ctx, it->second.part.c_str(), -1, SQLITE_TRANSIENT);
            } else {
                // partitions inherit from previous messages
                sqlite3_result_null(ctx);
            }
            break;
        }
        case log_col_kind::idle_msecs: {
            int64_t prev = -1;
            if (c->idx > 0) {
                auto& pr = c->rows[c->idx - 1];
                auto& plf = *APP.files[pr.file];
                prev = plf.meta[plf.msgs[pr.msg].first_line].time_usecs;
            }
            if (prev < 0) {
                sqlite3_result_int64(ctx, 0);
            } else {
                int64_t d = (ll.time_usecs - prev) / 1000;
                sqlite3_result_int64(ctx, d < 0 ? 0 : d);
            }
            break;
        }
        case log_col_kind::mark:
            sqlite3_result_int(ctx, APP.marks.count(key) ? 1 : 0);
            break;
        case log_col_kind::comment: {
            auto it = ANNOTS.find(key);
            if (it != ANNOTS.end() && it->second.has_comment) {
                sqlite3_result_text(ctx, it->second.comment.c_str(), -1, SQLITE_TRANSIENT);
            } else {
                sqlite3_result_null(ctx);
            }
            break;
        }
        case log_col_kind::tags: {
            auto it = ANNOTS.find(key);
            if (it != ANNOTS.end() && it->second.has_tags) {
                sqlite3_result_text(ctx, it->second.tags.c_str(), -1, SQLITE_TRANSIENT);
                sqlite3_result_subtype(ctx, 74);
            } else {
                sqlite3_result_null(ctx);
            }
            break;
        }
        case log_col_kind::annotations:
        case log_col_kind::user_opid:
        case log_col_kind::opid_definition:
        case log_col_kind::duration:
            sqlite3_result_null(ctx);
            break;
        case log_col_kind::filters: {
            std::vector<int> matched;
            APP.msg_passes_filters(row.file, row.msg, &matched);
            if (matched.empty()) {
                sqlite3_result_null(ctx);
            } else {
                auto s = json_array_of_ints(matched);
                sqlite3_result_text(ctx, s.c_str(), -1, SQLITE_TRANSIENT);
                sqlite3_result_subtype(ctx, 74);
            }
            break;
        }
        case log_col_kind::opid: {
            std::string op = opid_for_msg(lf, row.msg);
            if (op.empty()) {
                sqlite3_result_null(ctx);
            } else {
                sqlite3_result_text(ctx, op.c_str(), -1, SQLITE_TRANSIENT);
            }
            break;
        }
        case log_col_kind::format:
            sqlite3_result_text(ctx, lf.fmt->name.c_str(), -1, SQLITE_TRANSIENT);
            break;
        case log_col_kind::format_regex:
            if (ll.pattern >= 0 && !lf.fmt->is_json && !lf.fmt->is_generic) {
                sqlite3_result_text(ctx, lf.fmt->patterns[ll.pattern].name.c_str(), -1,
                                    SQLITE_TRANSIENT);
            } else {
                sqlite3_result_null(ctx);
            }
            break;
        case log_col_kind::time_msecs:
            sqlite3_result_int64(ctx, ll.time_usecs / 1000);
            break;
        case log_col_kind::path:
            sqlite3_result_text(ctx, lf.path.c_str(), -1, SQLITE_TRANSIENT);
            break;
        case log_col_kind::unique_path:
            sqlite3_result_text(ctx, lf.unique_path.c_str(), -1, SQLITE_TRANSIENT);
            break;
        case log_col_kind::text: {
            auto lines = lf.display_lines(row.msg);
            std::string s;
            for (size_t i = 0; i < lines.size(); i++) {
                if (i) s += "\n";
                s += lines[i];
            }
            if (m.is_json) s = lf.msg_text(row.msg);
            sqlite3_result_text(ctx, s.c_str(), (int) s.size(), SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::body: {
            std::string s = lf.msg_body(row.msg);
            sqlite3_result_text(ctx, s.c_str(), (int) s.size(), SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::raw_text: {
            std::string s;
            if (m.is_json) {
                s = lf.lines[m.first_line];
            } else {
                for (int i = 0; i < m.line_count; i++) {
                    if (i) s += "\n";
                    s += lf.lines[m.first_line + i];
                }
            }
            sqlite3_result_text(ctx, s.c_str(), (int) s.size(), SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::line_hash: {
            std::string h = line_hash_for(lf, row.msg);
            sqlite3_result_text(ctx, h.c_str(), -1, SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::line_link: {
            std::string h = line_hash_for(lf, row.msg);
            char buf[64];
            snprintf(buf, sizeof(buf), "#msg%016llx-", (unsigned long long) ll.time_usecs);
            std::string s = std::string(buf) + h;
            sqlite3_result_text(ctx, s.c_str(), -1, SQLITE_TRANSIENT);
            break;
        }
        case log_col_kind::src_file:
        case log_col_kind::src_line:
        case log_col_kind::thread_id: {
            const std::string& fname = lc.kind == log_col_kind::src_file ? lf.fmt->src_file_field
                : lc.kind == log_col_kind::src_line                     ? lf.fmt->src_line_field
                                                                        : lf.fmt->thread_id_field;
            if (fname.empty()) {
                sqlite3_result_null(ctx);
                break;
            }
            bool found = false;
            std::string v = field_by_name(lf, row.msg, fname, found);
            if (!found) {
                sqlite3_result_null(ctx);
            } else {
                sqlite3_result_text(ctx, v.c_str(), -1, SQLITE_TRANSIENT);
            }
            break;
        }
    }
    return SQLITE_OK;
}

static int lv_update(sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64* rowid)
{
    auto* vt = (log_vtab*) tab;
    if (argc == 1) {
        tab->zErrMsg = sqlite3_mprintf("Rows cannot be deleted from this table");
        return SQLITE_ERROR;
    }
    if (sqlite3_value_type(argv[0]) == SQLITE_NULL) {
        tab->zErrMsg = sqlite3_mprintf("Rows cannot be inserted into this table");
        return SQLITE_ERROR;
    }
    int64_t vline = sqlite3_value_int64(argv[0]);
    APP.ensure_log_view();
    if (vline < 0 || vline >= (int64_t) APP.log_view.size()) return SQLITE_OK;
    auto& vl = APP.log_view[vline];
    auto& lf = *APP.files[vl.file];
    auto key = std::make_pair(vl.file, lf.msgs[vl.msg].first_line);
    auto& def = *vt->def;
    for (size_t i = 0; i < def.cols.size(); i++) {
        sqlite3_value* v = argv[2 + i];
        auto kind = def.cols[i].kind;
        if (kind == log_col_kind::mark) {
            if (sqlite3_value_int(v)) {
                APP.marks.insert(key);
            } else {
                APP.marks.erase(key);
            }
        } else if (kind == log_col_kind::comment) {
            auto& a = ANNOTS[key];
            if (sqlite3_value_type(v) == SQLITE_NULL) {
                a.has_comment = false;
            } else {
                a.has_comment = true;
                a.comment = (const char*) sqlite3_value_text(v);
            }
        } else if (kind == log_col_kind::tags) {
            auto& a = ANNOTS[key];
            if (sqlite3_value_type(v) == SQLITE_NULL) {
                a.has_tags = false;
            } else {
                std::string t = (const char*) sqlite3_value_text(v);
                js::value jv;
                if (!js::parse(t, jv) || !jv.is_array()) {
                    tab->zErrMsg = sqlite3_mprintf("log_tags must be a JSON array");
                    return SQLITE_ERROR;
                }
                a.has_tags = !jv.arr->empty();
                a.tags = js::dump(jv);
            }
        } else if (kind == log_col_kind::part) {
            auto& a = ANNOTS[key];
            if (sqlite3_value_type(v) == SQLITE_NULL) {
                a.has_part = false;
            } else {
                a.has_part = true;
                a.part = (const char*) sqlite3_value_text(v);
            }
        }
    }
    return SQLITE_OK;
}

