static std::vector<regex_capture> captures_for(const logfile& lf, int msg)
{
    std::vector<regex_capture> caps;
    auto& ll = lf.meta[lf.msgs[msg].first_line];
    if (ll.pattern < 0 || !lf.fmt || lf.fmt->is_json) return caps;
    auto& pat = lf.fmt->patterns[ll.pattern];
    pat.re->match(lf.lines[lf.msgs[msg].first_line], caps);
    return caps;
}

static std::string field_raw_value(const logfile& lf, int msg, const value_def& vd, bool& found)
{
    found = false;
    auto& m = lf.msgs[msg];
    if (m.is_json) {
        const js::value* v = jsonlog_lookup(m.json, vd.name);
        if (!v || v->is_null()) return "";
        found = true;
        return jsonlog_value_str(*v);
    }
    auto& ll = lf.meta[m.first_line];
    if (ll.pattern < 0 || !lf.fmt) return "";
    auto& pat = lf.fmt->patterns[ll.pattern];
    int idx = pat.re->name_index(vd.name);
    if (idx < 0) return "";
    std::vector<regex_capture> caps;
    const std::string& line = lf.lines[m.first_line];
    if (!pat.re->match(line, caps)) return "";
    if (!caps[idx].valid()) return "";
    found = true;
    return line.substr(caps[idx].start, caps[idx].length());
}

std::string field_by_name(const logfile& lf, int msg, const std::string& name, bool& found)
{
    found = false;
    if (!lf.fmt) return "";
    auto* vd = lf.fmt->find_value(name);
    if (vd) return field_raw_value(lf, msg, *vd, found);
    value_def tmp;
    tmp.name = name;
    return field_raw_value(lf, msg, tmp, found);
}

std::string opid_for_msg(const logfile& lf, int msg)
{
    if (!lf.fmt || lf.fmt->opid_field.empty()) return "";
    bool found = false;
    std::string v = field_by_name(lf, msg, lf.fmt->opid_field, found);
    return found ? v : "";
}

static uint64_t fnv1a(const std::string& s, uint64_t h = 1469598103934665603ULL)
{
    for (unsigned char c : s) {
        h ^= c;
        h *= 1099511628211ULL;
    }
    return h;
}

std::string line_hash_for(const logfile& lf, int msg)
{
    std::string text = lf.msg_text(msg);
    uint64_t a = fnv1a(text);
    uint64_t b = fnv1a(text, a ^ 0x9e3779b97f4a7c15ULL);
    char buf[64];
    snprintf(buf, sizeof(buf), "v1:%016llx%016llx", (unsigned long long) a, (unsigned long long) b);
    return buf;
}

bool sql_eval_msg_expr(sqlite3_stmt* stmt, int file, int msg)
{
    auto& lf = *APP.files[file];
    auto& m = lf.msgs[msg];
    auto& ll = lf.meta[m.first_line];
    sqlite3_reset(stmt);
    sqlite3_clear_bindings(stmt);
    int n = sqlite3_bind_parameter_count(stmt);
    for (int i = 1; i <= n; i++) {
        const char* pname = sqlite3_bind_parameter_name(stmt, i);
        if (!pname) continue;
        std::string name = pname + 1;
        if (name == "log_level") {
            sqlite3_bind_text(stmt, i, level_name(ll.level), -1, SQLITE_STATIC);
        } else if (name == "log_time") {
            auto s = format_sql_time(ll.time_usecs);
            sqlite3_bind_text(stmt, i, s.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_time_msecs") {
            sqlite3_bind_int64(stmt, i, ll.time_usecs / 1000);
        } else if (name == "log_body") {
            auto s = lf.msg_body(msg);
            sqlite3_bind_text(stmt, i, s.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_text" || name == "log_raw_text") {
            auto s = lf.msg_text(msg);
            sqlite3_bind_text(stmt, i, s.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_format") {
            sqlite3_bind_text(stmt, i, lf.fmt->name.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_path") {
            sqlite3_bind_text(stmt, i, lf.path.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_unique_path") {
            sqlite3_bind_text(stmt, i, lf.unique_path.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_opid") {
            auto s = opid_for_msg(lf, msg);
            if (s.empty()) sqlite3_bind_null(stmt, i);
            else sqlite3_bind_text(stmt, i, s.c_str(), -1, SQLITE_TRANSIENT);
        } else if (name == "log_mark") {
            sqlite3_bind_int(stmt, i, APP.marks.count({file, m.first_line}) ? 1 : 0);
        } else {
            auto* vd = lf.fmt->find_value(name);
            if (!vd) {
                sqlite3_bind_null(stmt, i);
                continue;
            }
            bool found = false;
            std::string raw = field_raw_value(lf, msg, *vd, found);
            if (!found) {
                sqlite3_bind_null(stmt, i);
            } else if (vd->kind == value_kind::integer) {
                sqlite3_bind_int64(stmt, i, strtoll(raw.c_str(), nullptr, 10));
            } else if (vd->kind == value_kind::real) {
                sqlite3_bind_double(stmt, i, strtod(raw.c_str(), nullptr));
            } else {
                sqlite3_bind_text(stmt, i, raw.c_str(), -1, SQLITE_TRANSIENT);
            }
        }
    }
    int rc = sqlite3_step(stmt);
    bool result = false;
    if (rc == SQLITE_ROW) {
        result = sqlite3_column_int(stmt, 0) != 0;
    }
    sqlite3_reset(stmt);
    return result;
}

void register_search_table(const std::string& name, const std::string& pattern,
                           std::shared_ptr<log_format> fmt, const std::string& level)
{
    auto re = regex::compile(pattern);
    if (!re) return;
    auto t = make_search_table(name, re, fmt, level);
    for (auto& e : LOG_TABLES) {
        if (e->name == name) {
            e = t;
            return;
        }
    }
    LOG_TABLES.push_back(t);
}

static int collate_natural(void*, int l1, const void* s1, int l2, const void* s2, bool nocase)
{
    const char* a = (const char*) s1;
    const char* b = (const char*) s2;
    int i = 0, j = 0;
    while (i < l1 && j < l2) {
        if (isdigit((unsigned char) a[i]) && isdigit((unsigned char) b[j])) {
            int si = i, sj = j;
            while (si < l1 && a[si] == '0') si++;
            while (sj < l2 && b[sj] == '0') sj++;
            int ei = si, ej = sj;
            while (ei < l1 && isdigit((unsigned char) a[ei])) ei++;
            while (ej < l2 && isdigit((unsigned char) b[ej])) ej++;
            int la = ei - si, lb = ej - sj;
            if (la != lb) return la < lb ? -1 : 1;
            int c = memcmp(a + si, b + sj, la);
            if (c != 0) return c < 0 ? -1 : 1;
            i = ei;
            j = ej;
            continue;
        }
        int ca = (unsigned char) a[i], cb = (unsigned char) b[j];
        if (nocase) {
            ca = tolower(ca);
            cb = tolower(cb);
        }
        if (ca != cb) return ca < cb ? -1 : 1;
        i++;
        j++;
    }
    if (i < l1) return 1;
    if (j < l2) return -1;
    return 0;
}

static int collate_naturalnocase(void* p, int l1, const void* s1, int l2, const void* s2)
{
    return collate_natural(p, l1, s1, l2, s2, true);
}

static int collate_naturalcase(void* p, int l1, const void* s1, int l2, const void* s2)
{
    return collate_natural(p, l1, s1, l2, s2, false);
}

static int level_rank(const std::string& s)
{
    int l = level_from_name(s);
    if (l >= 0) return l;
    return string2level(s.data(), s.size());
}

static int collate_loglevel(void*, int l1, const void* s1, int l2, const void* s2)
{
    std::string a((const char*) s1, l1), b((const char*) s2, l2);
    int ra = level_rank(a), rb = level_rank(b);
    if (ra != rb) return ra < rb ? -1 : 1;
    return 0;
}

static bool parse_ip(const std::string& s, std::vector<int>& out)
{
    out.clear();
    auto parts = split(s, '.');
    if (parts.size() != 4) return false;
    for (auto& p : parts) {
        if (p.empty() || p.size() > 3) return false;
        for (char c : p)
            if (!isdigit((unsigned char) c)) return false;
        out.push_back(atoi(p.c_str()));
    }
    return true;
}

static int collate_ipaddress(void* p, int l1, const void* s1, int l2, const void* s2)
{
    std::string a((const char*) s1, l1), b((const char*) s2, l2);
    std::vector<int> ia, ib;
    bool va = parse_ip(a, ia), vb = parse_ip(b, ib);
    if (va && vb) {
        for (int i = 0; i < 4; i++)
            if (ia[i] != ib[i]) return ia[i] < ib[i] ? -1 : 1;
        return 0;
    }
    if (va != vb) return va ? -1 : 1;
    return collate_naturalnocase(p, l1, s1, l2, s2);
}

static void exec_sql_simple(sqlite3* db, const std::string& sql)
{
    char* err = nullptr;
    if (sqlite3_exec(db, sql.c_str(), nullptr, nullptr, &err) != SQLITE_OK) {
        if (getenv("LNAV_DEBUG_SQL")) fprintf(stderr, "init sql error: %s\n%s\n", err, sql.c_str());
        sqlite3_free(err);
    }
}

static std::string qualify_create(const std::string& sql)
{
    // insert lnav_db. after CREATE [UNIQUE] (TABLE|VIEW|TRIGGER|INDEX)
    static auto RE = regex::compile(
        R"(^(\s*CREATE\s+(?:UNIQUE\s+)?(?:TABLE|VIEW|TRIGGER|INDEX)\s+(?:IF\s+NOT\s+EXISTS\s+)?)(?!lnav_db\.))",
        nullptr, nullptr, PCRE2_CASELESS);
    std::vector<regex_capture> caps;
    if (RE->match(sql, caps)) {
        return sql.substr(0, caps[1].end) + "lnav_db." + sql.substr(caps[1].end);
    }
    return sql;
}

void sql_register_tables()
{
    sqlite3* db = APP.db_handle;
    LOG_TABLES.clear();
    LOG_TABLES.push_back(make_all_logs_table());
    for (auto& f : all_formats()) {
        LOG_TABLES.push_back(make_format_table(f));
    }
    for (auto& f : all_formats()) {
        for (auto& st : f->search_tables) {
            LOG_TABLES.push_back(make_search_table(st.name, st.re, f, st.level));
        }
    }
    for (auto& t : LOG_TABLES) {
        std::string sql = "CREATE VIRTUAL TABLE lnav_db." + t->name + " USING log_vtab_impl("
            + t->name + ")";
        exec_sql_simple(db, sql);
    }
    // schema objects
    const std::string* schema = builtin_data("sql/schema.json");
    if (schema) {
        js::value root;
        if (js::parse(*schema, root) && root.is_array()) {
            for (auto& e : *root.arr) {
                std::string sql = e.get("sql")->as_string();
                exec_sql_simple(db, qualify_create(sql));
            }
        }
    }
    auto load_rows = [&](const std::string& file, const std::string& table) {
        const std::string* data = builtin_data(file);
        if (!data) return;
        js::value root;
        if (!js::parse(*data, root) || !root.is_array()) return;
        exec_sql_simple(db, "BEGIN");
        for (auto& row : *root.arr) {
            std::string cols, vals;
            for (auto& kv : *row.obj) {
                if (!cols.empty()) {
                    cols += ",";
                    vals += ",";
                }
                cols += "\"" + kv.first + "\"";
                if (kv.second.is_null()) vals += "NULL";
                else if (kv.second.is_string()) {
                    char* q = sqlite3_mprintf("%Q", kv.second.s.c_str());
                    vals += q;
                    sqlite3_free(q);
                } else vals += js::dump(kv.second);
            }
            exec_sql_simple(db, "INSERT INTO lnav_db." + table + " (" + cols + ") VALUES (" + vals
                                    + ")");
        }
        exec_sql_simple(db, "COMMIT");
    };
    load_rows("sql/http_status_codes.json", "http_status_codes");
    load_rows("sql/lnav_example_log.json", "lnav_example_log");
}

void sql_init()
{
    sqlite3* db = nullptr;
    sqlite3_open(":memory:", &db);
    APP.db_handle = db;
    exec_sql_simple(db, "ATTACH DATABASE ':memory:' AS lnav_db");
    sqlite3_create_collation(db, "naturalnocase", SQLITE_UTF8, nullptr, collate_naturalnocase);
    sqlite3_create_collation(db, "naturalcase", SQLITE_UTF8, nullptr, collate_naturalcase);
    sqlite3_create_collation(db, "loglevel", SQLITE_UTF8, nullptr, collate_loglevel);
    sqlite3_create_collation(db, "ipaddress", SQLITE_UTF8, nullptr, collate_ipaddress);
    sqlite3_create_module(db, "log_vtab_impl", &LOG_VTAB_MODULE, nullptr);
    sqlite3_create_module(db, "log_vtab_no_rowid_impl", &LOG_VTAB_MODULE, nullptr);
    sql_register_functions(db);
    sql_register_misc_vtabs(db);
    sql_register_tables();
}
