void db_finalize_columns(db_result& res)
{
    for (size_t c = 0; c < res.cols.size(); c++) {
        auto& col = res.cols[c];
        int w = utf8_width(col.name);
        bool rj = false;
        for (auto& row : res.rows) {
            auto& cell = row[c];
            std::string disp = truncate_cell(scrub_ws(cell.text), 120);
            int cw = utf8_width(disp);
            if (cw > w) w = cw;
            if (cell.type == SQLITE_INTEGER || cell.type == SQLITE_FLOAT) {
                rj = true;
            } else if (cell.type != SQLITE_NULL && !cell.text.empty()
                       && isdigit((unsigned char) cell.text[0]))
            {
                rj = true;
            }
        }
        if (col.graphable && w < 10) w = 10;
        if (w > 120) w = 120;
        col.width = w;
        col.rjust = rj;
    }
}

std::string sql_value_to_cell_text(sqlite3_value* v)
{
    switch (sqlite3_value_type(v)) {
        case SQLITE_NULL: return "<NULL>";
        case SQLITE_INTEGER: return std::to_string(sqlite3_value_int64(v));
        case SQLITE_FLOAT: return format_double_cell(sqlite3_value_double(v));
        default: {
            const char* t = (const char*) sqlite3_value_text(v);
            return std::string(t ? t : "", sqlite3_value_bytes(v));
        }
    }
}

