std::string get_env_var(const std::string& name, bool* found)
{
    for (auto it = APP.env_overrides.rbegin(); it != APP.env_overrides.rend(); ++it) {
        if (it->first == name) {
            if (found) *found = true;
            return it->second;
        }
    }
    // positional script args
    if (!name.empty() && std::all_of(name.begin(), name.end(), ::isdigit)) {
        size_t idx = std::stoul(name);
        if (idx < APP.args.size()) {
            if (found) *found = true;
            return APP.args[idx];
        }
        if (found) *found = false;
        return "";
    }
