        return std::to_string(APP.args.empty() ? 0 : APP.args.size() - 1);
    }
    const char* v = getenv(name.c_str());
    if (found) *found = v != nullptr;
    return v ? v : "";
}

static bool numeric_text(const char* s)
{
    // digits, optional fraction, optional trailing whitespace
    const char* p = s;
    if (!isdigit((unsigned char) *p)) return false;
    while (isdigit((unsigned char) *p)) p++;
    if (*p == '.') {
        p++;
        if (!isdigit((unsigned char) *p)) return false;
        while (isdigit((unsigned char) *p)) p++;
    }
    while (*p == ' ' || *p == '\t') p++;
    return *p == '\0';
