void print_view(std::FILE* out)
{
    switch (APP.cur_view) {
        case view_t::log: {
            APP.ensure_log_view();
            for (int i = APP.log_top; i < (int) APP.log_view.size(); i++) {
                auto& vl = APP.log_view[i];
                auto& lf = *APP.files[vl.file];
                auto& m = lf.msgs[vl.msg];
                std::string s = m.is_json ? m.json_lines[vl.sub] : lf.display_line(vl.line);
                fputs(s.c_str(), out);
                fputc('\n', out);
            }
            break;
        }
        case view_t::text: {
            APP.rebuild_text_view();
            if (APP.text_file >= 0) {
                auto& lf = *APP.files[APP.text_file];
                for (int i = APP.text_top; i < (int) APP.text_visible.size(); i++) {
                    std::string s = lf.lines[APP.text_visible[i]];
                    if (!s.empty() && s.back() == '\r') s.pop_back();
                    fputs(s.c_str(), out);
                    fputc('\n', out);
                }
            }
            break;
        }
        case view_t::db: {
            if (APP.db.rows.empty()) break;
            db_result sub = APP.db;
            if (APP.db_top > 0) {
                sub.rows.erase(sub.rows.begin(),
                               sub.rows.begin() + std::min((size_t) APP.db_top, sub.rows.size()));
            }
            std::string s;
            render_db(sub, s, true);
            fputs(s.c_str(), out);
            break;
        }
        default: break;
    }
}

