static std::vector<filter_def>& cur_filters()
{
    return is_text_view() ? APP.text_filters : APP.filters;
}

static cmd_result add_filter(const std::string& args, bool is_in)
{
    if (APP.cur_view == view_t::db) {
        return make_error("db view does not support filtering");
    }
    if (args.empty()) {
        return make_error("expecting a regular expression to filter");
    }
    std::string err;
    int off = 0;
    auto re = regex::compile(args, &err, &off);
    if (!re) {
        return regex_error(args, err, off);
    }
    auto& fl = cur_filters();
    for (auto& f : fl) {
        if (f.pattern == args) {
            return make_error("filter already exists -- " + args);
        }
    }
    filter_def f;
    f.id = APP.next_filter_id++;
    f.is_in = is_in;
    f.pattern = args;
    f.re = re;
    fl.push_back(f);
    APP.log_dirty = true;
    return ok_result("info: filter now active");
}

static cmd_result cmd_filter_in(const std::string& args)
{
    return add_filter(args, true);
}

static cmd_result cmd_filter_out(const std::string& args)
{
    return add_filter(args, false);
}

static cmd_result cmd_delete_filter(const std::string& args)
{
    if (args.empty()) return make_error("expecting a filter to delete");
    auto& fl = cur_filters();
    for (auto it = fl.begin(); it != fl.end(); ++it) {
        if (it->pattern == args) {
            fl.erase(it);
            APP.log_dirty = true;
            return ok_result("info: deleted filter");
        }
    }
    return make_error("unknown filter -- " + args);
}

static cmd_result cmd_enable_disable_filter(const std::string& args, bool enable)
{
    if (args.empty()) return make_error("expecting a filter to " + std::string(enable ? "enable" : "disable"));
    auto& fl = cur_filters();
    for (auto& f : fl) {
        if (f.pattern == args) {
            if (f.enabled == enable) {
                return ok_result(std::string("info: filter already ") + (enable ? "enabled" : "disabled"));
            }
            f.enabled = enable;
            APP.log_dirty = true;
            return ok_result(std::string("info: filter ") + (enable ? "enabled" : "disabled"));
        }
    }
    return make_error("no such filter -- " + args);
}

static bool FILTERING_ENABLED = true;
static std::vector<bool> SAVED_ENABLED;

static cmd_result cmd_toggle_filtering(const std::string&)
{
    auto& fl = cur_filters();
    if (FILTERING_ENABLED) {
        SAVED_ENABLED.clear();
        for (auto& f : fl) {
            SAVED_ENABLED.push_back(f.enabled);
            f.enabled = false;
        }
        FILTERING_ENABLED = false;
    } else {
        for (size_t i = 0; i < fl.size() && i < SAVED_ENABLED.size(); i++)
            fl[i].enabled = SAVED_ENABLED[i];
        FILTERING_ENABLED = true;
    }
    APP.log_dirty = true;
    return ok_result();
}

