static std::string csv_quote(const std::string& s)
{
    bool need = s.find_first_of(",\"\n\r") != std::string::npos;
    if (!need) return s;
    std::string r = "\"";
    for (char c : s) {
        if (c == '"') r += "\"\"";
        else r.push_back(c);
    }
    r += "\"";
    return r;
}

static std::string json_double(double d)
{
    if (std::isnan(d) || std::isinf(d)) return "null";
    char buf[64];
    snprintf(buf, sizeof(buf), "%.20g", d);
    std::string s = buf;
    if (s.find_first_of(".eEn") == std::string::npos) s += ".0";
    return s;
}

static std::string cell_json(const db_cell& c)
{
    switch (c.type) {
        case SQLITE_NULL: return "null";
        case SQLITE_INTEGER: return std::to_string(c.ival);
        case SQLITE_FLOAT: return json_double(c.dval);
        default:
            if (c.is_json) {
                js::value v;
                if (js::parse(c.text, v)) return js::dump(v);
            }
            return js::quote(c.text);
    }
}

static std::string cell_json_pretty(const db_cell& c, int indent_level)
{
    if (c.is_json && c.type == SQLITE_TEXT) {
        js::value v;
        if (js::parse(c.text, v)) {
            std::string s = js::dump_pretty(v, 4);
            // indent continuation lines
            std::string pad(indent_level * 4, ' ');
            std::string r;
            for (char ch : s) {
                r.push_back(ch);
                if (ch == '\n') r += pad;
            }
            return r;
        }
    }
    return cell_json(c);
}

static cmd_result need_db_result()
{
    return make_error("no query result to write, use ';' to execute a query");
}

static bool parse_write_args(const std::string& args, std::string& path, bool& anonymize)
{
    anonymize = false;
    std::string a = trim(args);
    if (startswith(a, "--anonymize")) {
        anonymize = true;
        a = trim(a.substr(11));
    }
    path = a;
    return !path.empty();
}

extern std::string anonymize_text(const std::string& s);

static cmd_result cmd_write_csv(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s;
    for (size_t i = 0; i < APP.db.cols.size(); i++) {
        if (i) s += ",";
        s += csv_quote(APP.db.cols[i].name);
    }
    s += "\n";
    for (auto& row : APP.db.rows) {
        for (size_t i = 0; i < row.size(); i++) {
            if (i) s += ",";
            std::string t = row[i].text;
            if (anon && row[i].type == SQLITE_TEXT) t = anonymize_text(t);
            s += csv_quote(t);
        }
        s += "\n";
    }
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_json(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s = "[\n";
    for (size_t r = 0; r < APP.db.rows.size(); r++) {
        auto& row = APP.db.rows[r];
        s += "    {\n";
        for (size_t i = 0; i < row.size(); i++) {
            s += "        " + js::quote(APP.db.cols[i].name) + ": ";
            db_cell c = row[i];
            if (anon && c.type == SQLITE_TEXT) c.text = anonymize_text(c.text);
            s += cell_json_pretty(c, 2);
            if (i + 1 < row.size()) s += ",";
            s += "\n";
        }
        s += "    }";
        if (r + 1 < APP.db.rows.size()) s += ",";
        s += "\n";
    }
    s += "]\n";
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_jsonlines(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s;
    for (auto& row : APP.db.rows) {
        s += "{";
        for (size_t i = 0; i < row.size(); i++) {
            if (i) s += ",";
            db_cell c = row[i];
            if (anon && c.type == SQLITE_TEXT) c.text = anonymize_text(c.text);
            s += js::quote(APP.db.cols[i].name) + ":" + cell_json(c);
        }
        s += "}\n";
    }
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_json_cols(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s = "[\n";
    for (size_t c = 0; c < APP.db.cols.size(); c++) {
        auto& col = APP.db.cols[c];
        s += "    ";
        if (c) s += ",";
        std::string type = "null";
        switch (col.type) {
            case SQLITE_INTEGER: type = "integer"; break;
            case SQLITE_FLOAT: type = "float"; break;
            case SQLITE_TEXT: type = "string"; break;
            case SQLITE_BLOB: type = "blob"; break;
        }
        s += "{\"name\":" + js::quote(col.name) + ",\"type\":\"" + type
            + "\",\"width\":" + std::to_string(col.width) + ",\"values\":[";
        for (size_t r = 0; r < APP.db.rows.size(); r++) {
            if (r) s += ",";
            s += cell_json(APP.db.rows[r][c]);
        }
        s += "]}\n";
    }
    s += "    ]\n";
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static std::string repeat_str(const std::string& s, int n)
{
    std::string r;
    for (int i = 0; i < n; i++) r += s;
    return r;
}

static cmd_result cmd_write_table(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    auto& res = APP.db;
    std::string s;
    const std::string H = "\xe2\x94\x81";  // ━
    s += "\xe2\x94\x8f";  // ┏
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x94\xb3";  // ┳
        s += repeat_str(H, res.cols[c].width);
    }
    s += "\xe2\x94\x93\n";  // ┓
    s += "\xe2\x94\x83";    // ┃
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x94\x83";
        auto& col = res.cols[c];
        int hw = utf8_width(col.name);
        int pad = col.width - hw;
        if (pad < 0) pad = 0;
        int left = pad / 2;
        s += "\x1b[1m" + std::string(left, ' ') + col.name + std::string(pad - left, ' ') + "\x1b[0m";
    }
    s += "\xe2\x94\x83\n";
    s += "\xe2\x94\xa1";  // ┡
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x95\x87";  // ╇
        s += repeat_str(H, res.cols[c].width);
    }
    s += "\xe2\x94\xa9\n";  // ┩
    for (auto& row : res.rows) {
        s += "\xe2\x94\x82";  // │
        for (size_t c = 0; c < res.cols.size(); c++) {
            if (c) s += "\xe2\x94\x82";
            auto& col = res.cols[c];
            std::string disp = truncate_cell(scrub_ws(row[c].text), 120);
            if (anon && row[c].type == SQLITE_TEXT) disp = anonymize_text(disp);
            int w = utf8_width(disp);
            int pad = col.width - w;
            if (pad < 0) pad = 0;
            if (col.rjust) s += std::string(pad, ' ') + disp;
            else s += disp + std::string(pad, ' ');
        }
        s += "\xe2\x94\x82\n";
    }
    s += "\xe2\x94\x94";  // └
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x94\xb4";  // ┴
        s += repeat_str(H, res.cols[c].width);
    }
    s += "\xe2\x94\x98\n";  // ┘
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result write_marked(const std::string& args, bool append, bool raw)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    std::vector<std::string> lines;
    if (APP.cur_view == view_t::log) {
        APP.ensure_log_view();
        std::set<std::pair<int, int>> done_msgs;
        for (int i = 0; i < (int) APP.log_view.size(); i++) {
            if (!line_is_marked(i)) continue;
            auto& vl = APP.log_view[i];
            auto& lf = *APP.files[vl.file];
            if (raw) {
                if (done_msgs.count({vl.file, vl.msg})) continue;
                done_msgs.insert({vl.file, vl.msg});
                auto& m = lf.msgs[vl.msg];
                if (m.is_json) {
                    lines.push_back(lf.lines[m.first_line]);
                } else {
                    for (int k = 0; k < m.line_count; k++) {
                        std::string s = lf.lines[m.first_line + k];
                        lines.push_back(s);
                    }
                }
            } else {
                auto& m = lf.msgs[vl.msg];
                lines.push_back(m.is_json ? m.json_lines[vl.sub] : lf.display_line(vl.line));
            }
        }
    } else if (APP.cur_view == view_t::text) {
        APP.rebuild_text_view();
        for (int i : APP.text_visible) {
            if (APP.text_marks.count({APP.text_file, i})) {
                lines.push_back(APP.files[APP.text_file]->lines[i]);
            }
        }
    } else if (APP.cur_view == view_t::db) {
        if (raw) {
            // raw db rows
            for (auto& row : APP.db.rows) {
                std::string s;
                for (auto& c : row) s += c.text;
                lines.push_back(s);
            }
        }
    }
    if (lines.empty() && !(raw && APP.cur_view == view_t::db)) {
        return make_error("no lines marked to write, use 'm' to mark lines");
    }
    auto out = open_output(path, append);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    for (auto& l : lines) {
        std::string s = anon ? anonymize_text(l) : l;
        fputs(s.c_str(), out.fp);
        fputc('\n', out.fp);
    }
    close_output(out);
    return ok_result();
}

