static cmd_result cmd_write_view_to(const std::string& args, bool screen)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    if (APP.cur_view == view_t::db) {
        std::string s;
        db_result sub = APP.db;
        int top = screen ? APP.db_top : 0;
        if (top > 0)
            sub.rows.erase(sub.rows.begin(), sub.rows.begin() + std::min((size_t) top, sub.rows.size()));
        render_db(sub, s, screen);
        if (anon) s = anonymize_text(s);
        fputs(s.c_str(), out.fp);
    } else {
        auto lines = view_lines_text();
        int start = screen ? cur_top() : 0;
        for (int i = start; i < (int) lines.size(); i++) {
            std::string s = anon ? anonymize_text(lines[i]) : lines[i];
            fputs(s.c_str(), out.fp);
            fputc('\n', out.fp);
        }
    }
    close_output(out);
    return ok_result();
}

