static std::string unescape_echo(const std::string& s)
{
    std::string r;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            r.push_back(s[++i]);
        } else {
            r.push_back(s[i]);
        }
    }
    return r;
}

static cmd_result cmd_echo(const std::string& args_in)
{
    std::string args = args_in;
    bool nl = true;
    if (args == "-n" || startswith(args, "-n ")) {
        nl = false;
        args = args.size() > 3 ? args.substr(3) : "";
    }
    std::string msg = substitute_vars(args);
    msg = unescape_echo(msg);
    std::FILE* fp = APP.redirect ? APP.redirect : stdout;
    if (!APP.redirect) APP.stdout_used = true;
    fputs(msg.c_str(), fp);
    if (nl) fputc('\n', fp);
    fflush(fp);
    return ok_result();
}

static cmd_result cmd_eval(const std::string& args)
{
    if (args.empty()) return make_error("expecting a command or query to evaluate");
    bool ok = true;
    std::string errvar;
    std::string expanded = substitute_vars(args, &ok, &errvar);
    std::string saved_line = CUR_CMDLINE, saved_name = CUR_CMDNAME;
    auto r = execute_command_line(expanded);
    CUR_CMDLINE = saved_line;
    CUR_CMDNAME = saved_name;
    if (!r.ok) {
        // re-attribute
        if (r.err.location.empty()) {
            r.err.location = APP.src.name + ":" + std::to_string(APP.src.line);
            r.err.snippet = {CUR_CMDLINE};
            r.err.help = help_lines_for_command("eval");
        }
    }
    return r;
}

static std::string strftime_utc(const char* fmt, int64_t secs)
{
    time_t t = (time_t) secs;
    struct tm tm;
    gmtime_r(&t, &tm);
    char buf[256];
    strftime(buf, sizeof(buf), fmt, &tm);
    return buf;
}

static cmd_result cmd_current_time(const std::string&)
{
    int64_t now = now_usecs() / 1000000;
    return ok_result(strftime_utc("%a %b %d %H:%M:%S %Y  %z %Z", now) + " -- " + std::to_string(now));
}

static cmd_result cmd_unix_time(const std::string& args)
{
    if (args.empty()) return make_error("expecting a unix time value");
    char* end = nullptr;
    long long v = strtoll(args.c_str(), &end, 10);
    if (!end || *end != '\0') {
        return make_error("invalid unix time -- " + args);
    }
    return ok_result(strftime_utc("%a %b %d %H:%M:%S %Y  %z %Z", v) + " -- " + std::to_string(v));
}

