static cmd_result cmd_hide_show_fields(const std::string& args, bool hide)
{
    auto names = shlex_split(args);
    if (names.empty()) return make_error("Expecting a log message field name");
    std::vector<std::string> unknown;
    for (auto& n : names) {
        std::string fname = n;
        bool found = false;
        auto dot = n.find('.');
        for (auto& f : all_formats()) {
            if (dot != std::string::npos && n.substr(0, dot) == f->name) {
                if (f->find_value(n.substr(dot + 1))) found = true;
            } else if (f->find_value(n)) {
                found = true;
            }
        }
        if (!found) {
            unknown.push_back(n);
            continue;
        }
        if (hide) APP.hidden_fields.insert(n);
        else APP.hidden_fields.erase(n);
    }
    if (!unknown.empty()) {
        std::string s;
        for (auto& u : unknown) {
            if (!s.empty()) s += ", ";
            s += u;
        }
        return make_error("unknown field(s) -- " + s);
    }
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_highlight(const std::string& args)
{
    if (args.empty()) return make_error("expecting a regular expression to highlight");
    std::string err;
    int off = 0;
    auto re = regex::compile(args, &err, &off);
    if (!re) return regex_error(args, err, off);
    for (auto& h : APP.highlights) {
        if (h.first == args) return make_error("highlight already exists -- " + args);
    }
    APP.highlights.emplace_back(args, "");
    return ok_result();
}

static cmd_result cmd_clear_highlight(const std::string& args)
{
    if (args.empty()) return make_error("expecting a regular expression");
    for (auto it = APP.highlights.begin(); it != APP.highlights.end(); ++it) {
        if (it->first == args) {
            APP.highlights.erase(it);
            return ok_result();
        }
    }
    return make_error("highlight does not exist -- " + args);
}

