static cmd_result cmd_create_search_table(const std::string& args)
{
    auto sp = args.find_first_of(" \t");
    std::string name = sp == std::string::npos ? args : args.substr(0, sp);
    std::string pattern = sp == std::string::npos ? "" : trim(args.substr(sp));
    if (name.empty()) return make_error("expecting a table name");
    if (pattern.empty()) pattern = APP.last_search;
    if (pattern.empty()) return make_error("expecting a regular expression");
    std::string err;
    int off = 0;
    auto re = regex::compile(pattern, &err, &off);
    if (!re) return regex_error(pattern, err, off);
    register_search_table(name, pattern, nullptr, "");
    std::string sql = "CREATE VIRTUAL TABLE lnav_db." + name + " USING log_vtab_impl(" + name + ")";
    char* emsg = nullptr;
    if (sqlite3_exec(APP.db_handle, sql.c_str(), nullptr, nullptr, &emsg) != SQLITE_OK) {
        std::string e = emsg ? emsg : "";
        sqlite3_free(emsg);
        return make_error("unable to create table -- " + name, e);
    }
    APP.search_tables[name] = pattern;
    return ok_result();
}

static cmd_result cmd_delete_search_table(const std::string& args)
{
    auto names = shlex_split(args);
    if (names.empty()) return make_error("expecting a table name");
    for (auto& n : names) {
        if (!APP.search_tables.count(n)) {
            return make_error("unknown search table -- " + n);
        }
        std::string sql = "DROP TABLE lnav_db." + n;
        sqlite3_exec(APP.db_handle, sql.c_str(), nullptr, nullptr, nullptr);
        APP.search_tables.erase(n);
    }
    return ok_result();
}

static cmd_result cmd_config(const std::string& args)
{
    auto parts = shlex_split(args);
    if (parts.empty()) return make_error("expecting a configuration option to read or write");
    extern bool config_get(const std::string& path, std::string& out);
    extern bool config_set(const std::string& path, const std::string& value, std::string& err);
    if (parts.size() == 1) {
        std::string v;
        if (!config_get(parts[0], v)) {
            return make_error("unknown configuration option -- " + parts[0]);
        }
        return ok_result(parts[0] + " = " + v);
    }
    std::string value = trim(args.substr(args.find(parts[0]) + parts[0].size()));
    std::string err;
    if (!config_set(parts[0], value, err)) {
        return make_error(err);
    }
    return ok_result();
}

static cmd_result cmd_open(const std::string& args)
{
    auto paths = shlex_split(args);
    if (paths.empty()) return make_error("expecting file name to open");
    for (auto& p : paths) {
        if (p == "--since" || p == "--until" || startswith(p, "--since=") || startswith(p, "--until="))
            continue;
        std::shared_ptr<logfile> lf;
        std::string err = open_logfile(p, lf);
        if (!err.empty()) {
            return make_error("cannot open file: " + p, err);
        }
        bool dup = false;
        for (auto& f : APP.files)
            if (f->path == lf->path) dup = true;
        if (dup) continue;
        APP.files.push_back(lf);
        if (!lf->is_log()) APP.text_file = (int) APP.files.size() - 1;
    }
    compute_unique_paths(APP.files);
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_close(const std::string& args)
{
    if (args.empty()) {
        // close focused file
        if (APP.cur_view == view_t::text && APP.text_file >= 0) {
            APP.files.erase(APP.files.begin() + APP.text_file);
        } else {
            APP.ensure_log_view();
            if (!APP.log_view.empty()) {
                int fi = APP.log_view[std::min(APP.log_top, (int) APP.log_view.size() - 1)].file;
                APP.files.erase(APP.files.begin() + fi);
            }
        }
    } else {
        std::string p = abspath(args);
        bool found = false;
        for (size_t i = 0; i < APP.files.size(); i++) {
            if (APP.files[i]->path == realpath_str(p) || APP.files[i]->arg_path == args) {
                APP.files.erase(APP.files.begin() + i);
                found = true;
                break;
            }
        }
        if (!found) return make_error("no such file -- " + args);
    }
    APP.text_file = -1;
    for (int i = (int) APP.files.size() - 1; i >= 0; i--) {
        if (!APP.files[i]->is_log()) {
            APP.text_file = i;
            break;
        }
    }
    APP.marks.clear();
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_hide_show_file(const std::string& args, bool hide)
{
    bool found = false;
    for (auto& f : APP.files) {
        if (args.empty() || f->arg_path == args || f->path == realpath_str(args)
            || fnmatch_path(args, f->path))
        {
            f->visible = !hide;
            found = true;
        }
    }
    (void) found;
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_redirect_to(const std::string& args)
{
    if (APP.redirect) {
        fclose(APP.redirect);
        APP.redirect = nullptr;
    }
    if (args.empty()) return ok_result("info: cleared redirect");
    std::string p = trim(args);
    if (p == "-") return ok_result();
