static cmd_result run_sql_on_focused(const std::string& set_clause)
{
    APP.ensure_log_view();
    if (APP.log_view.empty()) return make_error("no log message focused");
    int t = std::min(APP.log_top, (int) APP.log_view.size() - 1);
    // find first line of message
    while (t > 0 && APP.log_view[t].sub != 0) t--;
    std::string sql = "UPDATE all_logs SET " + set_clause + " WHERE log_line = " + std::to_string(t);
    char* err = nullptr;
    if (sqlite3_exec(APP.db_handle, sql.c_str(), nullptr, nullptr, &err) != SQLITE_OK) {
        std::string e = err ? err : "";
        sqlite3_free(err);
        return make_error(e);
    }
    return ok_result();
}

static std::string sql_quote(const std::string& s)
{
    char* q = sqlite3_mprintf("%Q", s.c_str());
    std::string r = q;
    sqlite3_free(q);
    return r;
}

static cmd_result cmd_comment(const std::string& args)
{
    if (APP.cur_view != view_t::log) return make_error("The :comment command only works in the log view");
    if (args.empty()) return make_error("expecting some comment text");
    return run_sql_on_focused("log_comment = " + sql_quote(unescape_echo(args)));
}

static cmd_result cmd_clear_comment(const std::string&)
{
    return run_sql_on_focused("log_comment = NULL");
}

static cmd_result cmd_tag(const std::string& args, bool add)
{
    auto tags = shlex_split(args);
    if (tags.empty()) return make_error("expecting one or more tags");
    APP.ensure_log_view();
    if (APP.log_view.empty()) return ok_result();
    int t = std::min(APP.log_top, (int) APP.log_view.size() - 1);
    while (t > 0 && APP.log_view[t].sub != 0) t--;
    sqlite3_stmt* stmt = nullptr;
    std::string q = "SELECT log_tags FROM all_logs WHERE log_line = " + std::to_string(t);
    std::vector<std::string> cur;
    if (sqlite3_prepare_v2(APP.db_handle, q.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW && sqlite3_column_type(stmt, 0) != SQLITE_NULL) {
            js::value v;
            if (js::parse((const char*) sqlite3_column_text(stmt, 0), v) && v.is_array()) {
                for (auto& e : *v.arr) cur.push_back(e.as_string());
            }
        }
        sqlite3_finalize(stmt);
    }
    for (auto tg : tags) {
        if (!startswith(tg, "#")) tg = "#" + tg;
        auto it = std::find(cur.begin(), cur.end(), tg);
        if (add) {
            if (it == cur.end()) cur.push_back(tg);
        } else if (it != cur.end()) {
            cur.erase(it);
        }
    }
    js::value arr = js::value::make_array();
    for (auto& c : cur) arr.push(js::value::make_string(c));
    if (cur.empty()) return run_sql_on_focused("log_tags = NULL");
    return run_sql_on_focused("log_tags = " + sql_quote(js::dump(arr)));
}

static cmd_result cmd_partition_name(const std::string& args)
{
    if (args.empty()) return make_error("expecting partition name");
