static cmd_result cmd_mark_expr(const std::string& args)
{
    if (args.empty()) return make_error("expecting an SQL expression");
    sqlite3_stmt* stmt = nullptr;
    auto r = compile_msg_expr(args, &stmt, "mark");
    if (!r.ok) return r;
    APP.mark_expr = args;
    APP.ensure_log_view();
    for (auto& vl : APP.log_view) {
        if (vl.sub != 0) continue;
        extern bool sql_eval_msg_expr(sqlite3_stmt * stmt, int file, int msg);
        if (sql_eval_msg_expr(stmt, vl.file, vl.msg)) {
            APP.marks.insert({vl.file, vl.line * 1024});
        }
    }
    sqlite3_finalize(stmt);
    return ok_result();
}

static cmd_result cmd_clear_mark_expr(const std::string&)
