cmd_result run_colon_command(const std::string& line)
{
    // line starts after ':'
    std::string rest = line;
    size_t i = 0;
    while (i < rest.size() && isspace((unsigned char) rest[i])) i++;
    size_t j = i;
    while (j < rest.size() && !isspace((unsigned char) rest[j])) j++;
    std::string name = rest.substr(i, j - i);
    std::string args = j < rest.size() ? rest.substr(j) : "";
    // strip leading whitespace from args and trailing whitespace
    size_t k = 0;
    while (k < args.size() && isspace((unsigned char) args[k])) k++;
    args = args.substr(k);
    args = rtrim(args);
    CUR_CMDLINE = ":" + line;
    CUR_CMDNAME = name;
    auto& T = cmd_table();
    auto it = T.find(name);
    if (it == T.end()) {
        cmd_result r;
        r.ok = false;
        r.err.message = "unknown command: \xe2\x80\x9c" + name + "\xe2\x80\x9d";
        return r;
    }
    return it->second(args);
}
