static bool is_text_view()
{
    return APP.cur_view == view_t::text;
}

// --- output helpers ---------------------------------------------------------

struct out_target {
    std::FILE* fp = nullptr;
    bool is_stdout = false;
    bool close = false;
    std::string err;
};

static out_target open_output(const std::string& path, bool append)
{
    out_target t;
    if (path == "-" || path == "/dev/stdout") {
        if (APP.redirect) {
            t.fp = APP.redirect;
        } else {
            t.fp = stdout;
            t.is_stdout = true;
            APP.stdout_used = true;
        }
        return t;
    }
    std::string p = path;
    if (startswith(p, "~/")) {
        const char* home = getenv("HOME");
        if (home) p = std::string(home) + p.substr(1);
    }
    t.fp = fopen(p.c_str(), append ? "a" : "w");
    if (!t.fp) {
        t.err = strerror(errno);
        return t;
    }
    t.close = true;
    return t;
}

static void close_output(out_target& t)
{
    if (t.close && t.fp) fclose(t.fp);
    if (t.fp) fflush(t.fp);
}

// --- views ------------------------------------------------------------------

static std::string view_name(view_t v)
{
    switch (v) {
        case view_t::log: return "log";
        case view_t::text: return "text";
        case view_t::help: return "help";
        case view_t::histogram: return "histogram";
        case view_t::db: return "db";
        case view_t::schema: return "schema";
        case view_t::pretty: return "pretty";
        case view_t::spectro: return "spectro";
        case view_t::timeline: return "timeline";
    }
    return "log";
}

static bool view_from_name(const std::string& n, view_t& out)
{
    static const std::pair<const char*, view_t> NAMES[] = {
        {"log", view_t::log},         {"text", view_t::text},     {"help", view_t::help},
        {"histogram", view_t::histogram}, {"db", view_t::db},     {"schema", view_t::schema},
        {"pretty", view_t::pretty},   {"spectro", view_t::spectro}, {"timeline", view_t::timeline},
    };
    for (auto& p : NAMES) {
        if (n == p.first) {
            out = p.second;
            return true;
        }
    }
    return false;
}

std::string current_view_name()
{
    return view_name(APP.cur_view);
}

// lines of the current view as plain text
std::vector<std::string> view_lines_text()
{
    std::vector<std::string> r;
    switch (APP.cur_view) {
        case view_t::log: {
            APP.ensure_log_view();
            for (auto& vl : APP.log_view) {
                auto& lf = *APP.files[vl.file];
                auto& m = lf.msgs[vl.msg];
                if (m.is_json) r.push_back(m.json_lines[vl.sub]);
                else r.push_back(lf.display_line(vl.line));
            }
            break;
        }
        case view_t::text: {
            APP.rebuild_text_view();
            if (APP.text_file >= 0) {
                auto& lf = *APP.files[APP.text_file];
                for (int i : APP.text_visible) {
                    std::string s = lf.lines[i];
                    if (!s.empty() && s.back() == '\r') s.pop_back();
                    r.push_back(s);
                }
            }
            break;
        }
        case view_t::db: {
            std::string out;
            render_db(APP.db, out, true);
            r = split_lines(out);
            break;
        }
        default: break;
    }
    return r;
}

static int& cur_top()
{
    switch (APP.cur_view) {
        case view_t::text: return APP.text_top;
        case view_t::db: return APP.db_top;
        default: return APP.log_top;
    }
}

static int cur_view_size()
{
    switch (APP.cur_view) {
        case view_t::log: APP.ensure_log_view(); return (int) APP.log_view.size();
        case view_t::text: APP.rebuild_text_view(); return (int) APP.text_visible.size();
        case view_t::db: return (int) APP.db.rows.size();
        default: return 0;
    }
}

void print_view(std::FILE* out)
{
    switch (APP.cur_view) {
        case view_t::log: {
            APP.ensure_log_view();
            for (int i = APP.log_top; i < (int) APP.log_view.size(); i++) {
                auto& vl = APP.log_view[i];
                auto& lf = *APP.files[vl.file];
                auto& m = lf.msgs[vl.msg];
                std::string s = m.is_json ? m.json_lines[vl.sub] : lf.display_line(vl.line);
                fputs(s.c_str(), out);
                fputc('\n', out);
            }
            break;
        }
        case view_t::text: {
            APP.rebuild_text_view();
            if (APP.text_file >= 0) {
                auto& lf = *APP.files[APP.text_file];
                for (int i = APP.text_top; i < (int) APP.text_visible.size(); i++) {
                    std::string s = lf.lines[APP.text_visible[i]];
                    if (!s.empty() && s.back() == '\r') s.pop_back();
                    fputs(s.c_str(), out);
                    fputc('\n', out);
                }
            }
            break;
        }
        case view_t::db: {
            if (APP.db.rows.empty()) break;
            db_result sub = APP.db;
            if (APP.db_top > 0) {
                sub.rows.erase(sub.rows.begin(),
                               sub.rows.begin() + std::min((size_t) APP.db_top, sub.rows.size()));
            }
            std::string s;
            render_db(sub, s, true);
            fputs(s.c_str(), out);
            break;
        }
        default: break;
    }
}

// --- filters ----------------------------------------------------------------

static std::vector<filter_def>& cur_filters()
{
    return is_text_view() ? APP.text_filters : APP.filters;
}

static cmd_result add_filter(const std::string& args, bool is_in)
{
    if (APP.cur_view == view_t::db) {
        return make_error("db view does not support filtering");
    }
    if (args.empty()) {
        return make_error("expecting a regular expression to filter");
    }
    std::string err;
    int off = 0;
    auto re = regex::compile(args, &err, &off);
    if (!re) {
        return regex_error(args, err, off);
    }
    auto& fl = cur_filters();
    for (auto& f : fl) {
        if (f.pattern == args) {
            return make_error("filter already exists -- " + args);
        }
    }
    filter_def f;
    f.id = APP.next_filter_id++;
    f.is_in = is_in;
    f.pattern = args;
    f.re = re;
    fl.push_back(f);
    APP.log_dirty = true;
    return ok_result("info: filter now active");
}

static cmd_result cmd_filter_in(const std::string& args)
{
    return add_filter(args, true);
}

static cmd_result cmd_filter_out(const std::string& args)
{
    return add_filter(args, false);
}

static cmd_result cmd_delete_filter(const std::string& args)
{
    if (args.empty()) return make_error("expecting a filter to delete");
    auto& fl = cur_filters();
    for (auto it = fl.begin(); it != fl.end(); ++it) {
        if (it->pattern == args) {
            fl.erase(it);
            APP.log_dirty = true;
            return ok_result("info: deleted filter");
        }
    }
    return make_error("unknown filter -- " + args);
}

static cmd_result cmd_enable_disable_filter(const std::string& args, bool enable)
{
    if (args.empty()) return make_error("expecting a filter to " + std::string(enable ? "enable" : "disable"));
    auto& fl = cur_filters();
    for (auto& f : fl) {
        if (f.pattern == args) {
            if (f.enabled == enable) {
                return ok_result(std::string("info: filter already ") + (enable ? "enabled" : "disabled"));
            }
            f.enabled = enable;
            APP.log_dirty = true;
            return ok_result(std::string("info: filter ") + (enable ? "enabled" : "disabled"));
        }
    }
    return make_error("no such filter -- " + args);
}

static bool FILTERING_ENABLED = true;
static std::vector<bool> SAVED_ENABLED;

static cmd_result cmd_toggle_filtering(const std::string&)
{
    auto& fl = cur_filters();
    if (FILTERING_ENABLED) {
        SAVED_ENABLED.clear();
        for (auto& f : fl) {
            SAVED_ENABLED.push_back(f.enabled);
            f.enabled = false;
        }
        FILTERING_ENABLED = false;
    } else {
        for (size_t i = 0; i < fl.size() && i < SAVED_ENABLED.size(); i++)
            fl[i].enabled = SAVED_ENABLED[i];
        FILTERING_ENABLED = true;
    }
    APP.log_dirty = true;
    return ok_result();
}

extern cmd_result compile_msg_expr(const std::string& expr, sqlite3_stmt** out,
                                   const std::string& what);

static cmd_result cmd_filter_expr(const std::string& args)
{
    if (args.empty()) return make_error("expecting an SQL expression");
    sqlite3_stmt* stmt = nullptr;
    auto r = compile_msg_expr(args, &stmt, "filter");
    if (!r.ok) return r;
    if (APP.filter_expr_stmt) sqlite3_finalize(APP.filter_expr_stmt);
    APP.filter_expr_stmt = stmt;
    APP.filter_expr = args;
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_clear_filter_expr(const std::string&)
{
    if (APP.filter_expr_stmt) sqlite3_finalize(APP.filter_expr_stmt);
    APP.filter_expr_stmt = nullptr;
    APP.filter_expr.clear();
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_set_min_log_level(const std::string& args)
{
    if (args.empty()) return make_error("expecting a log level name");
    int l = level_from_name(lower(args));
    if (l < 0) {
        l = string2level(args.data(), args.size());
    }
    APP.min_level = l;
    APP.log_dirty = true;
    return ok_result(std::string("info: minimum log level is now -- ") + level_name(l));
}

// --- time parsing for commands -----------------------------------------------

extern bool parse_relative_time(const std::string& s, int64_t base_usecs, int64_t& out,
                                std::string* err);

static int64_t top_time()
{
    APP.ensure_log_view();
    if (APP.log_view.empty()) return now_usecs();
    int t = std::min(APP.log_top, (int) APP.log_view.size() - 1);
    auto& vl = APP.log_view[t];
    auto& lf = *APP.files[vl.file];
    return lf.meta[lf.msgs[vl.msg].first_line].time_usecs;
}

static bool parse_cmd_time(const std::string& args, int64_t& out, std::string& err)
{
    if (args == "here") {
        out = top_time();
        return true;
    }
    if (parse_relative_time(args, top_time(), out, &err)) return true;
    return false;
}

static cmd_result cmd_hide_lines(const std::string& args, bool before)
{
    if (args.empty()) return make_error("expecting a date/time");
    int64_t t;
    std::string err;
    if (!parse_cmd_time(args, t, err)) {
        return make_error("unable to parse time -- " + args, err);
    }
    if (before) APP.hide_before = t;
    else APP.hide_after = t;
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_show_lines_before_and_after(const std::string&)
{
    APP.hide_before.reset();
    APP.hide_after.reset();
    APP.log_dirty = true;
    return ok_result();
}

// --- navigation -------------------------------------------------------------

static cmd_result cmd_goto(const std::string& args)
{
    int size = cur_view_size();
    if (args.empty()) return ok_result();
    std::string a = trim(args);
    char* end = nullptr;
    if (!a.empty() && a.back() == '%') {
        double pct = strtod(a.c_str(), &end);
        if (end && *end == '%') {
            int line = (int) (size * pct / 100.0);
            if (line >= size) line = size - 1;
            if (line < 0) line = 0;
            cur_top() = line;
            return ok_result();
        }
    }
    long long v = strtoll(a.c_str(), &end, 10);
    if (end && *end == '\0' && !a.empty()) {
        if (v < 0) v = size + v;
        if (v >= size) v = size - 1;
        if (v < 0) v = 0;
        cur_top() = (int) v;
        return ok_result();
    }
    if (APP.cur_view == view_t::log) {
        int64_t t;
        std::string err;
        if (parse_cmd_time(a, t, err)) {
            APP.ensure_log_view();
            int idx = (int) APP.log_view.size() - 1;
            for (int i = 0; i < (int) APP.log_view.size(); i++) {
                auto& vl = APP.log_view[i];
                auto& lf = *APP.files[vl.file];
                if (lf.meta[lf.msgs[vl.msg].first_line].time_usecs >= t) {
                    idx = i;
                    break;
                }
            }
            if (idx < 0) idx = 0;
            APP.log_top = idx;
            return ok_result();
        }
    }
    return make_error("invalid argument: " + a,
                      "expecting line number/percentage, timestamp, or relative time");
}

static cmd_result cmd_relative_goto(const std::string& args)
{
    int size = cur_view_size();
    std::string a = trim(args);
    char* end = nullptr;
    if (!a.empty() && a.back() == '%') {
        double pct = strtod(a.c_str(), &end);
        int delta = (int) (size * pct / 100.0);
        int nt = cur_top() + delta;
        if (nt >= size) nt = size - 1;
        if (nt < 0) nt = 0;
        cur_top() = nt;
        return ok_result();
    }
    long long v = strtoll(a.c_str(), &end, 10);
    if (end && *end == '\0' && !a.empty()) {
        int nt = cur_top() + (int) v;
        if (nt >= size) nt = size - 1;
        if (nt < 0) nt = 0;
        cur_top() = nt;
        return ok_result();
    }
    return make_error("invalid line number -- " + a);
}

static bool line_is_marked(int vi)
{
    auto& vl = APP.log_view[vi];
    return APP.marks.count({vl.file, vl.line * 1024 + vl.sub}) > 0;
}

static cmd_result cmd_next_prev_mark(const std::string& args, bool next)
{
    APP.ensure_log_view();
    std::vector<std::string> types = shlex_split(args);
    if (types.empty()) types.push_back("user");
    int n = (int) APP.log_view.size();
    int start = APP.log_top;
    auto matches = [&](int vi) {
        auto& vl = APP.log_view[vi];
        auto& lf = *APP.files[vl.file];
        auto& ll = lf.meta[lf.msgs[vl.msg].first_line];
        for (auto& t : types) {
            if (t == "error" && vl.sub == 0 && ll.level >= LEVEL_ERROR && ll.level != LEVEL_INVALID)
                return true;
            if (t == "warning" && vl.sub == 0 && ll.level == LEVEL_WARNING) return true;
            if (t == "user" && line_is_marked(vi)) return true;
        }
        return false;
    };
    if (next) {
        for (int i = start + 1; i < n; i++) {
            if (matches(i)) {
                APP.log_top = i;
                return ok_result();
            }
        }
    } else {
        for (int i = start - 1; i >= 0; i--) {
            if (matches(i)) {
                APP.log_top = i;
                return ok_result();
            }
        }
    }
    cmd_result r;
    std::string tn = types.empty() ? "user" : types[0];
    r.msg = std::string("info: no more ") + tn + " bookmarks " + (next ? "after" : "before") + " here";
    return r;
}

static cmd_result cmd_mark(const std::string&)
{
    if (APP.cur_view == view_t::log) {
        APP.ensure_log_view();
        if (APP.log_view.empty()) return ok_result();
        int t = std::min(APP.log_top, (int) APP.log_view.size() - 1);
        auto& vl = APP.log_view[t];
        auto key = std::make_pair(vl.file, vl.line * 1024 + vl.sub);
        if (APP.marks.count(key)) APP.marks.erase(key);
        else APP.marks.insert(key);
        // also track message-level mark for SQL
        auto& lf = *APP.files[vl.file];
        auto mkey = std::make_pair(vl.file, lf.msgs[vl.msg].first_line);
        (void) mkey;
    } else if (APP.cur_view == view_t::text) {
        APP.rebuild_text_view();
        if (APP.text_visible.empty()) return ok_result();
        int t = std::min(APP.text_top, (int) APP.text_visible.size() - 1);
        auto key = std::make_pair(APP.text_file, APP.text_visible[t]);
        if (APP.text_marks.count(key)) APP.text_marks.erase(key);
        else APP.text_marks.insert(key);
    }
    return ok_result();
}

