static std::string csv_quote(const std::string& s)
{
    bool need = s.find_first_of(",\"\n\r") != std::string::npos;
    if (!need) return s;
    std::string r = "\"";
    for (char c : s) {
        if (c == '"') r += "\"\"";
        else r.push_back(c);
    }
    r += "\"";
    return r;
}

static std::string json_double(double d)
{
    if (std::isnan(d) || std::isinf(d)) return "null";
    char buf[64];
    snprintf(buf, sizeof(buf), "%.20g", d);
    std::string s = buf;
    if (s.find_first_of(".eEn") == std::string::npos) s += ".0";
    return s;
}

static std::string cell_json(const db_cell& c)
{
    switch (c.type) {
        case SQLITE_NULL: return "null";
        case SQLITE_INTEGER: return std::to_string(c.ival);
        case SQLITE_FLOAT: return json_double(c.dval);
        default:
            if (c.is_json) {
                js::value v;
                if (js::parse(c.text, v)) return js::dump(v);
            }
            return js::quote(c.text);
    }
}

static std::string cell_json_pretty(const db_cell& c, int indent_level)
{
    if (c.is_json && c.type == SQLITE_TEXT) {
        js::value v;
        if (js::parse(c.text, v)) {
            std::string s = js::dump_pretty(v, 4);
            // indent continuation lines
            std::string pad(indent_level * 4, ' ');
            std::string r;
            for (char ch : s) {
                r.push_back(ch);
                if (ch == '\n') r += pad;
            }
            return r;
        }
    }
    return cell_json(c);
}

static cmd_result need_db_result()
{
    return make_error("no query result to write, use ';' to execute a query");
}

static bool parse_write_args(const std::string& args, std::string& path, bool& anonymize)
{
    anonymize = false;
    std::string a = trim(args);
    if (startswith(a, "--anonymize")) {
        anonymize = true;
        a = trim(a.substr(11));
    }
    path = a;
    return !path.empty();
}

extern std::string anonymize_text(const std::string& s);

static cmd_result cmd_write_csv(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s;
    for (size_t i = 0; i < APP.db.cols.size(); i++) {
        if (i) s += ",";
        s += csv_quote(APP.db.cols[i].name);
    }
    s += "\n";
    for (auto& row : APP.db.rows) {
        for (size_t i = 0; i < row.size(); i++) {
            if (i) s += ",";
            std::string t = row[i].text;
            if (anon && row[i].type == SQLITE_TEXT) t = anonymize_text(t);
            s += csv_quote(t);
        }
        s += "\n";
    }
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_json(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s = "[\n";
    for (size_t r = 0; r < APP.db.rows.size(); r++) {
        auto& row = APP.db.rows[r];
        s += "    {\n";
        for (size_t i = 0; i < row.size(); i++) {
            s += "        " + js::quote(APP.db.cols[i].name) + ": ";
            db_cell c = row[i];
            if (anon && c.type == SQLITE_TEXT) c.text = anonymize_text(c.text);
            s += cell_json_pretty(c, 2);
            if (i + 1 < row.size()) s += ",";
            s += "\n";
        }
        s += "    }";
        if (r + 1 < APP.db.rows.size()) s += ",";
        s += "\n";
    }
    s += "]\n";
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_jsonlines(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s;
    for (auto& row : APP.db.rows) {
        s += "{";
        for (size_t i = 0; i < row.size(); i++) {
            if (i) s += ",";
            db_cell c = row[i];
            if (anon && c.type == SQLITE_TEXT) c.text = anonymize_text(c.text);
            s += js::quote(APP.db.cols[i].name) + ":" + cell_json(c);
        }
        s += "}\n";
    }
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_json_cols(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    std::string s = "[\n";
    for (size_t c = 0; c < APP.db.cols.size(); c++) {
        auto& col = APP.db.cols[c];
        s += "    ";
        if (c) s += ",";
        std::string type = "null";
        switch (col.type) {
            case SQLITE_INTEGER: type = "integer"; break;
            case SQLITE_FLOAT: type = "float"; break;
            case SQLITE_TEXT: type = "string"; break;
            case SQLITE_BLOB: type = "blob"; break;
        }
        s += "{\"name\":" + js::quote(col.name) + ",\"type\":\"" + type
            + "\",\"width\":" + std::to_string(col.width) + ",\"values\":[";
        for (size_t r = 0; r < APP.db.rows.size(); r++) {
            if (r) s += ",";
            s += cell_json(APP.db.rows[r][c]);
        }
        s += "]}\n";
    }
    s += "    ]\n";
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static std::string repeat_str(const std::string& s, int n)
{
    std::string r;
    for (int i = 0; i < n; i++) r += s;
    return r;
}

static cmd_result cmd_write_table(const std::string& args)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    if (!APP.db.valid) return need_db_result();
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    auto& res = APP.db;
    std::string s;
    const std::string H = "\xe2\x94\x81";  // ━
    s += "\xe2\x94\x8f";  // ┏
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x94\xb3";  // ┳
        s += repeat_str(H, res.cols[c].width);
    }
    s += "\xe2\x94\x93\n";  // ┓
    s += "\xe2\x94\x83";    // ┃
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x94\x83";
        auto& col = res.cols[c];
        int hw = utf8_width(col.name);
        int pad = col.width - hw;
        if (pad < 0) pad = 0;
        int left = pad / 2;
        s += "\x1b[1m" + std::string(left, ' ') + col.name + std::string(pad - left, ' ') + "\x1b[0m";
    }
    s += "\xe2\x94\x83\n";
    s += "\xe2\x94\xa1";  // ┡
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x95\x87";  // ╇
        s += repeat_str(H, res.cols[c].width);
    }
    s += "\xe2\x94\xa9\n";  // ┩
    for (auto& row : res.rows) {
        s += "\xe2\x94\x82";  // │
        for (size_t c = 0; c < res.cols.size(); c++) {
            if (c) s += "\xe2\x94\x82";
            auto& col = res.cols[c];
            std::string disp = truncate_cell(scrub_ws(row[c].text), 120);
            if (anon && row[c].type == SQLITE_TEXT) disp = anonymize_text(disp);
            int w = utf8_width(disp);
            int pad = col.width - w;
            if (pad < 0) pad = 0;
            if (col.rjust) s += std::string(pad, ' ') + disp;
            else s += disp + std::string(pad, ' ');
        }
        s += "\xe2\x94\x82\n";
    }
    s += "\xe2\x94\x94";  // └
    for (size_t c = 0; c < res.cols.size(); c++) {
        if (c) s += "\xe2\x94\xb4";  // ┴
        s += repeat_str(H, res.cols[c].width);
    }
    s += "\xe2\x94\x98\n";  // ┘
    fputs(s.c_str(), out.fp);
    close_output(out);
    return ok_result();
}

static cmd_result write_marked(const std::string& args, bool append, bool raw)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    std::vector<std::string> lines;
    if (APP.cur_view == view_t::log) {
        APP.ensure_log_view();
        std::set<std::pair<int, int>> done_msgs;
        for (int i = 0; i < (int) APP.log_view.size(); i++) {
            if (!line_is_marked(i)) continue;
            auto& vl = APP.log_view[i];
            auto& lf = *APP.files[vl.file];
            if (raw) {
                if (done_msgs.count({vl.file, vl.msg})) continue;
                done_msgs.insert({vl.file, vl.msg});
                auto& m = lf.msgs[vl.msg];
                if (m.is_json) {
                    lines.push_back(lf.lines[m.first_line]);
                } else {
                    for (int k = 0; k < m.line_count; k++) {
                        std::string s = lf.lines[m.first_line + k];
                        lines.push_back(s);
                    }
                }
            } else {
                auto& m = lf.msgs[vl.msg];
                lines.push_back(m.is_json ? m.json_lines[vl.sub] : lf.display_line(vl.line));
            }
        }
    } else if (APP.cur_view == view_t::text) {
        APP.rebuild_text_view();
        for (int i : APP.text_visible) {
            if (APP.text_marks.count({APP.text_file, i})) {
                lines.push_back(APP.files[APP.text_file]->lines[i]);
            }
        }
    } else if (APP.cur_view == view_t::db) {
        if (raw) {
            // raw db rows
            for (auto& row : APP.db.rows) {
                std::string s;
                for (auto& c : row) s += c.text;
                lines.push_back(s);
            }
        }
    }
    if (lines.empty() && !(raw && APP.cur_view == view_t::db)) {
        return make_error("no lines marked to write, use 'm' to mark lines");
    }
    auto out = open_output(path, append);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    for (auto& l : lines) {
        std::string s = anon ? anonymize_text(l) : l;
        fputs(s.c_str(), out.fp);
        fputc('\n', out.fp);
    }
    close_output(out);
    return ok_result();
}

static cmd_result cmd_write_to(const std::string& args)
{
    return write_marked(args, false, false);
}

static cmd_result cmd_append_to(const std::string& args)
{
    return write_marked(args, true, false);
}

static cmd_result cmd_write_raw_to(const std::string& args)
{
    return write_marked(args, false, true);
}

static cmd_result cmd_write_view_to(const std::string& args, bool screen)
{
    std::string path;
    bool anon;
    if (!parse_write_args(args, path, anon)) return make_error("expecting file name");
    auto out = open_output(path, false);
    if (!out.fp) return make_error("unable to open file -- " + path, out.err);
    if (APP.cur_view == view_t::db) {
        std::string s;
        db_result sub = APP.db;
        int top = screen ? APP.db_top : 0;
        if (top > 0)
            sub.rows.erase(sub.rows.begin(), sub.rows.begin() + std::min((size_t) top, sub.rows.size()));
        render_db(sub, s, screen);
        if (anon) s = anonymize_text(s);
        fputs(s.c_str(), out.fp);
    } else {
        auto lines = view_lines_text();
        int start = screen ? cur_top() : 0;
        for (int i = start; i < (int) lines.size(); i++) {
            std::string s = anon ? anonymize_text(lines[i]) : lines[i];
            fputs(s.c_str(), out.fp);
            fputc('\n', out.fp);
        }
    }
    close_output(out);
    return ok_result();
}

// --- misc commands ----------------------------------------------------------

static std::string unescape_echo(const std::string& s)
{
    std::string r;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            r.push_back(s[++i]);
        } else {
            r.push_back(s[i]);
        }
    }
    return r;
}

static cmd_result cmd_echo(const std::string& args_in)
{
    std::string args = args_in;
    bool nl = true;
    if (args == "-n" || startswith(args, "-n ")) {
        nl = false;
        args = args.size() > 3 ? args.substr(3) : "";
    }
    std::string msg = substitute_vars(args);
    msg = unescape_echo(msg);
    std::FILE* fp = APP.redirect ? APP.redirect : stdout;
    if (!APP.redirect) APP.stdout_used = true;
    fputs(msg.c_str(), fp);
    if (nl) fputc('\n', fp);
    fflush(fp);
    return ok_result();
}

static cmd_result cmd_eval(const std::string& args)
{
    if (args.empty()) return make_error("expecting a command or query to evaluate");
    bool ok = true;
    std::string errvar;
    std::string expanded = substitute_vars(args, &ok, &errvar);
    std::string saved_line = CUR_CMDLINE, saved_name = CUR_CMDNAME;
    auto r = execute_command_line(expanded);
    CUR_CMDLINE = saved_line;
    CUR_CMDNAME = saved_name;
    if (!r.ok) {
        // re-attribute
        if (r.err.location.empty()) {
            r.err.location = APP.src.name + ":" + std::to_string(APP.src.line);
            r.err.snippet = {CUR_CMDLINE};
            r.err.help = help_lines_for_command("eval");
        }
    }
    return r;
}

static std::string strftime_utc(const char* fmt, int64_t secs)
{
    time_t t = (time_t) secs;
    struct tm tm;
    gmtime_r(&t, &tm);
    char buf[256];
    strftime(buf, sizeof(buf), fmt, &tm);
    return buf;
}

static cmd_result cmd_current_time(const std::string&)
{
    int64_t now = now_usecs() / 1000000;
    return ok_result(strftime_utc("%a %b %d %H:%M:%S %Y  %z %Z", now) + " -- " + std::to_string(now));
}

static cmd_result cmd_unix_time(const std::string& args)
{
    if (args.empty()) return make_error("expecting a unix time value");
    char* end = nullptr;
    long long v = strtoll(args.c_str(), &end, 10);
    if (!end || *end != '\0') {
        return make_error("invalid unix time -- " + args);
    }
    return ok_result(strftime_utc("%a %b %d %H:%M:%S %Y  %z %Z", v) + " -- " + std::to_string(v));
}

static cmd_result cmd_switch_to_view(const std::string& args)
{
    view_t v;
    if (!view_from_name(trim(args), v)) {
        return make_error("invalid view name -- " + trim(args));
    }
    if (APP.cur_view != v) {
        APP.view_stack.push_back(APP.cur_view);
        APP.cur_view = v;
    }
    return ok_result();
}

static cmd_result cmd_toggle_view(const std::string& args)
{
    view_t v;
    if (!view_from_name(trim(args), v)) {
        return make_error("invalid view name -- " + trim(args));
    }
    if (APP.cur_view == v) {
        if (!APP.view_stack.empty()) {
            APP.cur_view = APP.view_stack.back();
            APP.view_stack.pop_back();
        }
    } else {
        APP.view_stack.push_back(APP.cur_view);
        APP.cur_view = v;
    }
    return ok_result();
}

static cmd_result cmd_hide_show_fields(const std::string& args, bool hide)
{
    auto names = shlex_split(args);
    if (names.empty()) return make_error("Expecting a log message field name");
    std::vector<std::string> unknown;
    for (auto& n : names) {
        std::string fname = n;
        bool found = false;
        auto dot = n.find('.');
        for (auto& f : all_formats()) {
            if (dot != std::string::npos && n.substr(0, dot) == f->name) {
                if (f->find_value(n.substr(dot + 1))) found = true;
            } else if (f->find_value(n)) {
                found = true;
            }
        }
        if (!found) {
            unknown.push_back(n);
            continue;
        }
        if (hide) APP.hidden_fields.insert(n);
        else APP.hidden_fields.erase(n);
    }
    if (!unknown.empty()) {
        std::string s;
        for (auto& u : unknown) {
            if (!s.empty()) s += ", ";
            s += u;
        }
        return make_error("unknown field(s) -- " + s);
    }
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_highlight(const std::string& args)
{
    if (args.empty()) return make_error("expecting a regular expression to highlight");
    std::string err;
    int off = 0;
    auto re = regex::compile(args, &err, &off);
    if (!re) return regex_error(args, err, off);
    for (auto& h : APP.highlights) {
        if (h.first == args) return make_error("highlight already exists -- " + args);
    }
    APP.highlights.emplace_back(args, "");
    return ok_result();
}

static cmd_result cmd_clear_highlight(const std::string& args)
{
    if (args.empty()) return make_error("expecting a regular expression");
    for (auto it = APP.highlights.begin(); it != APP.highlights.end(); ++it) {
        if (it->first == args) {
            APP.highlights.erase(it);
            return ok_result();
        }
    }
    return make_error("highlight does not exist -- " + args);
}

static cmd_result cmd_noop(const std::string&)
{
    return ok_result();
}

static cmd_result cmd_create_search_table(const std::string& args)
{
    auto sp = args.find_first_of(" \t");
    std::string name = sp == std::string::npos ? args : args.substr(0, sp);
    std::string pattern = sp == std::string::npos ? "" : trim(args.substr(sp));
    if (name.empty()) return make_error("expecting a table name");
    if (pattern.empty()) pattern = APP.last_search;
    if (pattern.empty()) return make_error("expecting a regular expression");
    std::string err;
    int off = 0;
    auto re = regex::compile(pattern, &err, &off);
    if (!re) return regex_error(pattern, err, off);
    register_search_table(name, pattern, nullptr, "");
    std::string sql = "CREATE VIRTUAL TABLE lnav_db." + name + " USING log_vtab_impl(" + name + ")";
    char* emsg = nullptr;
    if (sqlite3_exec(APP.db_handle, sql.c_str(), nullptr, nullptr, &emsg) != SQLITE_OK) {
        std::string e = emsg ? emsg : "";
        sqlite3_free(emsg);
        return make_error("unable to create table -- " + name, e);
    }
    APP.search_tables[name] = pattern;
    return ok_result();
}

static cmd_result cmd_delete_search_table(const std::string& args)
{
    auto names = shlex_split(args);
    if (names.empty()) return make_error("expecting a table name");
    for (auto& n : names) {
        if (!APP.search_tables.count(n)) {
            return make_error("unknown search table -- " + n);
        }
        std::string sql = "DROP TABLE lnav_db." + n;
        sqlite3_exec(APP.db_handle, sql.c_str(), nullptr, nullptr, nullptr);
        APP.search_tables.erase(n);
    }
    return ok_result();
}

static cmd_result cmd_config(const std::string& args)
