static cmd_result cmd_open(const std::string& args)
{
    auto paths = shlex_split(args);
    if (paths.empty()) return make_error("expecting file name to open");
    for (auto& p : paths) {
        if (p == "--since" || p == "--until" || startswith(p, "--since=") || startswith(p, "--until="))
            continue;
        std::shared_ptr<logfile> lf;
        std::string err = open_logfile(p, lf);
        if (!err.empty()) {
            return make_error("cannot open file: " + p, err);
        }
        bool dup = false;
        for (auto& f : APP.files)
            if (f->path == lf->path) dup = true;
        if (dup) continue;
        APP.files.push_back(lf);
        if (!lf->is_log()) APP.text_file = (int) APP.files.size() - 1;
    }
    compute_unique_paths(APP.files);
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_close(const std::string& args)
{
    if (args.empty()) {
        // close focused file
        if (APP.cur_view == view_t::text && APP.text_file >= 0) {
            APP.files.erase(APP.files.begin() + APP.text_file);
        } else {
            APP.ensure_log_view();
            if (!APP.log_view.empty()) {
                int fi = APP.log_view[std::min(APP.log_top, (int) APP.log_view.size() - 1)].file;
                APP.files.erase(APP.files.begin() + fi);
            }
        }
    } else {
        std::string p = abspath(args);
        bool found = false;
        for (size_t i = 0; i < APP.files.size(); i++) {
            if (APP.files[i]->path == realpath_str(p) || APP.files[i]->arg_path == args) {
                APP.files.erase(APP.files.begin() + i);
                found = true;
                break;
            }
        }
        if (!found) return make_error("no such file -- " + args);
    }
    APP.text_file = -1;
    for (int i = (int) APP.files.size() - 1; i >= 0; i--) {
        if (!APP.files[i]->is_log()) {
            APP.text_file = i;
            break;
        }
    }
    APP.marks.clear();
    APP.log_dirty = true;
    return ok_result();
}

