static cmd_result cmd_sh(const std::string& args)
{
    std::string cmd = trim(args);
    std::string name;
    if (startswith(cmd, "--name=")) {
        auto sp = cmd.find(' ');
        name = cmd.substr(7, sp == std::string::npos ? std::string::npos : sp - 7);
        cmd = sp == std::string::npos ? "" : trim(cmd.substr(sp));
    }
    if (cmd.empty()) return make_error("expecting a command to execute");
    FILE* p = popen(cmd.c_str(), "r");
    if (!p) return make_error("unable to execute command", strerror(errno));
    std::string data;
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), p)) > 0) data.append(buf, n);
    pclose(p);
    auto lf = logfile_from_string(name.empty() ? "sh-" + cmd : name, data);
    APP.files.push_back(lf);
    if (!lf->is_log()) APP.text_file = (int) APP.files.size() - 1;
    compute_unique_paths(APP.files);
    APP.log_dirty = true;
    return ok_result();
}

static cmd_result cmd_pipe_to(const std::string& args, bool line_only)
{
    std::string cmd = trim(args);
    if (cmd.empty()) return make_error("expecting a command to execute");
    std::string input;
    APP.ensure_log_view();
    if (line_only) {
        auto lines = view_lines_text();
        int t = cur_top();
        if (t < (int) lines.size()) input = lines[t] + "\n";
    } else {
        for (int i = 0; i < (int) APP.log_view.size(); i++) {
            if (line_is_marked(i)) {
                auto& vl = APP.log_view[i];
                input += APP.files[vl.file]->display_line(vl.line) + "\n";
            }
        }
    }
    fflush(stdout);
    FILE* p = popen(cmd.c_str(), "w");
    if (!p) return make_error("unable to execute command", strerror(errno));
    fwrite(input.data(), 1, input.size(), p);
    pclose(p);
    return ok_result();
}

