static cmd_result cmd_tag(const std::string& args, bool add)
{
    auto tags = shlex_split(args);
    if (tags.empty()) return make_error("expecting one or more tags");
    APP.ensure_log_view();
    if (APP.log_view.empty()) return ok_result();
    int t = std::min(APP.log_top, (int) APP.log_view.size() - 1);
    while (t > 0 && APP.log_view[t].sub != 0) t--;
    sqlite3_stmt* stmt = nullptr;
    std::string q = "SELECT log_tags FROM all_logs WHERE log_line = " + std::to_string(t);
    std::vector<std::string> cur;
    if (sqlite3_prepare_v2(APP.db_handle, q.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW && sqlite3_column_type(stmt, 0) != SQLITE_NULL) {
            js::value v;
            if (js::parse((const char*) sqlite3_column_text(stmt, 0), v) && v.is_array()) {
                for (auto& e : *v.arr) cur.push_back(e.as_string());
            }
        }
        sqlite3_finalize(stmt);
    }
    for (auto tg : tags) {
        if (!startswith(tg, "#")) tg = "#" + tg;
        auto it = std::find(cur.begin(), cur.end(), tg);
        if (add) {
            if (it == cur.end()) cur.push_back(tg);
        } else if (it != cur.end()) {
            cur.erase(it);
        }
    }
    js::value arr = js::value::make_array();
    for (auto& c : cur) arr.push(js::value::make_string(c));
    if (cur.empty()) return run_sql_on_focused("log_tags = NULL");
    return run_sql_on_focused("log_tags = " + sql_quote(js::dump(arr)));
}

