std::string substitute_vars(const std::string& s, bool* ok, std::string* errvar)
{
    std::string r;
    if (ok) *ok = true;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (c == '\\' && i + 1 < s.size() && s[i + 1] == '$') {
            r += "\\$";
            i++;
            continue;
        }
        if (c == '$' && i + 1 < s.size()) {
            size_t j = i + 1;
            std::string name;
            if (s[j] == '{') {
                size_t e = s.find('}', j);
                if (e == std::string::npos) {
                    r.push_back(c);
                    continue;
                }
                name = s.substr(j + 1, e - j - 1);
                i = e;
            } else if (isalpha((unsigned char) s[j]) || s[j] == '_') {
                while (j < s.size() && (isalnum((unsigned char) s[j]) || s[j] == '_')) j++;
                name = s.substr(i + 1, j - i - 1);
                i = j - 1;
            } else if (isdigit((unsigned char) s[j]) || s[j] == '#') {
                name = s.substr(j, 1);
                i = j;
            } else {
                r.push_back(c);
                continue;
            }
            bool found = false;
            std::string v = get_env_var(name, &found);
            r += v;
            continue;
        }
        r.push_back(c);
    }
    return r;
}

