static bool parse_unit(const std::string& u, int64_t& usecs)
{
    std::string l = lower(u);
    if (l == "s" || l == "sec" || l == "secs" || l == "second" || l == "seconds") usecs = 1000000LL;
    else if (l == "m" || l == "min" || l == "mins" || l == "minute" || l == "minutes")
        usecs = 60 * 1000000LL;
    else if (l == "h" || l == "hr" || l == "hrs" || l == "hour" || l == "hours")
        usecs = 3600 * 1000000LL;
    else if (l == "d" || l == "day" || l == "days") usecs = 86400 * 1000000LL;
    else if (l == "w" || l == "week" || l == "weeks") usecs = 7 * 86400 * 1000000LL;
    else if (l == "ms" || l == "msec" || l == "msecs") usecs = 1000LL;
    else if (l == "us" || l == "usec") usecs = 1LL;
    else return false;
    return true;
}

