                    o.until = val;
                    o.has_until = true;
                }
            } else {
                unexpected.push_back(a);
            }
            continue;
        }
        // short options, possibly combined
        for (size_t j = 1; j < a.size(); j++) {
            char c = a[j];
            auto take_value = [&](const std::string& label, const std::string& tname) -> std::string {
                if (j + 1 < a.size()) {
                    std::string v = a.substr(j + 1);
                    j = a.size();
                    return v;
                }
                if (i + 1 >= argc) cli_error(label + ": 1 required " + tname + " missing", 114);
                j = a.size();
                return argv[++i];
            };
            switch (c) {
                case 'h': o.help = true; break;
                case 'H': o.Help = true; break;
                case 'W': o.warn = true; break;
                case 'u': o.update = true; break;
                case 'V': o.version = true; break;
                case 'r': o.recursive = true; break;
                case 'R': o.rotated = true; break;
                case 't': o.timestamp = true; break;
                case 'n': o.headless = true; break;
                case 'N': o.no_default = true; break;
                case 'q': o.quiet = true; break;
                case 'i': o.install = true; break;
                case 'C': o.check = true; break;
                case 'm':
                    o.manage = true;
                    if (j + 1 < a.size()) {
                        unexpected.push_back("-" + a.substr(j + 1));
                    }
                    j = a.size();
                    break;
                case 'I': o.config_dirs.push_back(take_value("-I", "TEXT:DIR")); break;
                case 'd': o.debug_file = take_value("-d", "FILE"); break;
                case 'S':
                    o.since = take_value("--since", "TEXT");
                    o.has_since = true;
                    break;
                case 'U':
                    o.until = take_value("--until", "TEXT");
                    o.has_until = true;
                    break;
                case 'c': o.cmds.emplace_back('c', take_value("-c", "")); break;
                case 'f': o.cmds.emplace_back('f', take_value("-f", "")); break;
                case 'e': o.cmds.emplace_back('e', take_value("-e", "")); break;
                default: unexpected.push_back(std::string("-") + c); break;
            }
        }
    }
    if (o.manage && !o.mgmt_args.empty() && false) {
    }
    if (!unexpected.empty()) {
        if (unexpected.size() == 1) {
            cli_error("The following argument was not expected: " + unexpected[0], 109);
        }
        std::string s;
        for (auto it = unexpected.rbegin(); it != unexpected.rend(); ++it) {
            if (!s.empty()) s += " ";
            s += *it;
        }
        cli_error("The following arguments were not expected: " + s, 109);
    }
}

static void add_path(const std::string& path, bool recursive, std::vector<std::string>& out,
                     std::vector<std::string>& errors, bool top)
{
    struct stat st;
    if (stat(path.c_str(), &st) != 0) {
        // try glob
        glob_t g;
        if (glob(path.c_str(), 0, nullptr, &g) == 0) {
            for (size_t i = 0; i < g.gl_pathc; i++) add_path(g.gl_pathv[i], recursive, out, errors, false);
            globfree(&g);
            return;
        }
        int e = errno;
        (void) e;
        errors.push_back("  error: unable to open file: " + path + "\n reason: No such file or directory\n");
        return;
    }
    if (S_ISDIR(st.st_mode)) {
        std::string pattern = abspath(path);
        if (!pattern.empty() && pattern.back() == '/') pattern.pop_back();
        glob_t g;
        std::vector<std::string> entries;
        if (glob((pattern + "/*").c_str(), 0, nullptr, &g) == 0) {
            for (size_t i = 0; i < g.gl_pathc; i++) entries.push_back(g.gl_pathv[i]);
            globfree(&g);
        }
        std::vector<std::string> files;
        for (auto& e : entries) {
            struct stat est;
            if (stat(e.c_str(), &est) != 0) continue;
            if (S_ISDIR(est.st_mode)) {
                if (recursive) add_path(e, recursive, out, errors, false);
                continue;
            }
            files.push_back(e);
        }
        if (files.empty() && top && entries.empty()) {
            std::string p = pattern + "/*";
            errors.push_back("  error: unable to open file: " + p + "\n reason: failed to find path of \xe2\x80\x9c" + p
                             + "\xe2\x80\x9d\n |        reason: No such file or directory\n");
            return;
        }
        for (auto& f : files) out.push_back(f);
        return;
    }
    if (access(path.c_str(), R_OK) != 0) {
        errors.push_back("  error: file exists, but is not readable: " + path + "\n reason: "
                         + std::string(strerror(errno)) + "\n");
        return;
    }
    out.push_back(path);
}

static std::string read_all_stdin()
{
    std::string data;
    char buf[65536];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), stdin)) > 0) data.append(buf, n);
    return data;
}

int management_main(const std::vector<std::string>& args);

int main(int argc, char** argv)
{
    setvbuf(stderr, nullptr, _IONBF, 0);
    cli_opts o;
    parse_args(argc, argv, o);

    if (o.version) {
        printf("%s\n", VERSION_STR);
        return 0;
    }
    if (o.help) {
        print_usage(argv[0]);
        return 0;
    }
    if (o.manage) {
        return management_main(o.mgmt_args);
    }
    // validate commands
    for (auto& c : o.cmds) {
        if (c.first == 'c') {
            const std::string& v = c.second;
            if (v.empty() || (v[0] != ':' && v[0] != ';' && v[0] != '|' && v[0] != '/')) {
                fprintf(stderr,
                        "  error: invalid value for \xe2\x80\x9c-c\xe2\x80\x9d option\n"
                        " --> command-line argument\n");
                std::string snip = " -c " + v;
                std::string caret = "    ^ command type prefix is missing";
                auto pad = [](std::string s) {
                    int w = utf8_width(s);
                    if (w < 40) s += std::string(40 - w, ' ');
                    return s;
                };
                fprintf(stderr, " | %s\n", pad(snip).c_str());
                fprintf(stderr, " | %s\n", pad(caret).c_str());
                fprintf(stderr,
                        " = help: command arguments must start with one of the following symbols to denote the type of command:\n"
                        "            : - an lnav command   (e.g. :goto 42)\n"
                        "            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)\n"
                        "            | - an lnav script    (e.g. |rename-stdin foo)\n");
                return 105;
            }
        }
    }
    if (o.install && o.files.empty()) {
        cli_error("-i requires file", 107);
    }

    APP.headless = o.headless;
    APP.quiet = o.quiet;
    APP.config_dirs = o.config_dirs;

    auto ferrs = load_formats(o.config_dirs);
    if (!ferrs.empty()) {
        for (auto& e : ferrs) {
            fprintf(stderr, "  error: %s\n", e.message.c_str());
            if (!e.reason.empty()) fprintf(stderr, " reason: %s\n", e.reason.c_str());
            if (!e.location.empty()) fprintf(stderr, " --> %s\n", e.location.c_str());
        }
        return 1;
    }
    if (o.check) {
        return 0;
    }
    if (o.Help && !o.headless) {
        if (!isatty(STDOUT_FILENO)) {
            fprintf(stderr,
                    "  error: unable to display interactive text UI\n"
                    " reason: stdout is not a TTY\n"
                    " = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n");
            return 1;
        }
    }
    if (o.Help) {
        const std::string* h = builtin_data("help.txt");
        if (h) fwrite(h->data(), 1, h->size(), stdout);
        return 0;
    }
    if (o.update) {
        printf("No formats from git repositories found, use 'lnav -i extra' to install third-party formats\n");
        return 0;
    }

    if (o.has_since) {
        int64_t t;
        std::string err;
        extern bool parse_relative_time(const std::string& s, int64_t base, int64_t& out,
                                        std::string* err);
        if (!parse_relative_time(o.since, now_usecs(), t, &err)) {
            fprintf(stderr, "  error: invalid 'since' time \xe2\x80\x9c%s\xe2\x80\x9d\n reason: Unrecognized input\n",
                    o.since.c_str());
            return 1;
        }
        APP.since = t;
        APP.has_since = true;
    }
    if (o.has_until) {
        int64_t t;
        std::string err;
        extern bool parse_relative_time(const std::string& s, int64_t base, int64_t& out,
                                        std::string* err);
        if (!parse_relative_time(o.until, now_usecs(), t, &err)) {
            fprintf(stderr, "  error: invalid 'until' time \xe2\x80\x9c%s\xe2\x80\x9d\n reason: Unrecognized input\n",
                    o.until.c_str());
            return 1;
        }
        APP.until = t;
        APP.has_until = true;
    }

    // gather files
    std::vector<std::string> paths;
    std::vector<std::string> errors;
    for (auto& f : o.files) {
        if (o.rotated) {
            std::string p = abspath(f) + ".*";
            glob_t g;
            if (glob(p.c_str(), 0, nullptr, &g) != 0) {
                errors.push_back("  error: unable to open file: " + p + "\n reason: failed to find path of \xe2\x80\x9c" + p
                                 + "\xe2\x80\x9d\n |        reason: No such file or directory\n");
            } else {
                globfree(&g);
            }
        }
        add_path(f, o.recursive, paths, errors, true);
    }
    bool use_stdin = false;
    if (o.files.empty()) {
        if (!isatty(STDIN_FILENO)) {
            use_stdin = true;
        } else if (!o.no_default && o.cmds.empty()) {
            const char* defaults[] = {"/var/log/messages", "/var/log/system.log", "/var/log/syslog",
                                      nullptr};
            bool any = false;
            for (int i = 0; defaults[i]; i++) {
                if (access(defaults[i], R_OK) == 0) {
                    paths.push_back(defaults[i]);
                    any = true;
                    break;
                }
            }
            if (!any && o.headless) {
                fprintf(stderr,
                        "  error: nothing to do\n"
                        " reason: no files given or default files found\n"
                        " = help: use the \xe2\x80\x9c-N\xe2\x80\x9d option to open lnav without loading any files\n");
                return 1;
            }
        }
    }
    for (auto& p : paths) {
        std::shared_ptr<logfile> lf;
        std::string err = open_logfile(p, lf);
        if (!err.empty()) {
            errors.push_back("  error: unable to open file: " + p + "\n reason: " + err + "\n");
            continue;
        }
        bool dup = false;
        for (auto& e : APP.files) {
            if (e->path == lf->path) dup = true;
        }
        if (!dup) APP.files.push_back(lf);
    }
    for (auto& e : errors) fputs(e.c_str(), stderr);
    if (!o.headless && !isatty(STDOUT_FILENO)) {
        fprintf(stderr,
                "  error: unable to display interactive text UI\n"
                " reason: stdout is not a TTY\n"
                " = help: pass the -n option to run lnav in headless mode or don't redirect stdout\n");
        return 1;
    }
    if (!errors.empty()) return 1;
    if (!o.headless) {
        fprintf(stderr, "  error: interactive mode is not supported in this build\n");
        return 1;
    }
    if (use_stdin) {
        std::string data = read_all_stdin();
        auto lf = logfile_from_string("stdin", data);
        lf->from_stdin = true;
        lf->unique_path = "stdin";
        APP.files.push_back(lf);
    }
    compute_unique_paths(APP.files);
    for (auto& f : APP.files)
        if (f->from_stdin) f->unique_path = "stdin";
    // current text file = last text file
    for (int i = (int) APP.files.size() - 1; i >= 0; i--) {
        if (!APP.files[i]->is_log()) {
            APP.text_file = i;
            break;
        }
    }
    APP.cur_view = APP.log_file_count() > 0 ? view_t::log : (APP.text_file >= 0 ? view_t::text : view_t::log);

    sql_init();
    APP.ensure_log_view();

    std::vector<cmd_result> results;
    int idx = 0;
    for (auto& c : o.cmds) {
        idx++;
        APP.src.name = "command-option";
        APP.src.line = idx;
        cmd_result r;
        if (c.first == 'c') {
            r = execute_command_line(c.second);
        } else if (c.first == 'f') {
            r = execute_command_line("|" + c.second);
        } else if (c.first == 'e') {
            r = execute_command_line(":sh " + c.second);
        }
        results.push_back(r);
    }
    bool output_view = true;
    for (auto& r : results) {
        if (!r.ok) {
            fputs(render_user_message(r.err).c_str(), stderr);
            output_view = false;
        } else if (!r.msg.empty()) {
            if (startswith(r.msg, "info:")) {
                continue;
            }
            fputs(r.msg.c_str(), stdout);
            fputc('\n', stdout);
            APP.stdout_used = true;
        }
    }
    if (output_view && !APP.quiet && !APP.stdout_used) {
        print_view(stdout);
    }
    fflush(stdout);
    if (APP.redirect) fclose(APP.redirect);
    return 0;
}
