static bool get_json_time(const log_format& fmt, const js::value& root, date_time_scanner& dts,
                          int64_t& usecs, exttm& tm)
{
    const js::value* tv = jsonlog_lookup(root, fmt.timestamp_field);
    if (!tv) return false;
    if (tv->is_number()) {
        double d = tv->as_double();
        if (!fmt.timestamp_formats.empty()) {
            std::string s = tv->is_int() ? std::to_string(tv->i) : tv->s;
            int rc = dts.scan(s.data(), s.size(), tm, usecs, false);
            return rc > 0;
        }
        double secs = d / (double) fmt.timestamp_divisor;
        usecs = (int64_t) llround(secs * 1000000.0);
        tm = epoch_to_tm(usecs / 1000000, (int) ((usecs % 1000000) * 1000));
        tm.flags = ETF_YEAR_SET | ETF_MONTH_SET | ETF_DAY_SET | ETF_EPOCH_TIME;
        return true;
    }
    if (!tv->is_string()) return false;
    const std::string& s = tv->s;
    int rc = dts.scan(s.data(), s.size(), tm, usecs, false);
    return rc > 0;
}

