{
    size_t i = 0;
    while (i < line.size() && isspace((unsigned char) line[i])) i++;
    if (i >= line.size() || line[i] != '{') return false;
    js::value root;
    if (!js::parse(line, root) || !root.is_object()) return false;
    date_time_scanner dts;
    if (!fmt.timestamp_formats.empty()) dts.custom = &fmt.timestamp_formats;
    int64_t us;
    exttm tm;
    if (!get_json_time(fmt, root, dts, us, tm)) return false;
    return true;
}

void jsonlog_index(logfile& lf, int first_match)
{
    auto& fmt = *lf.fmt;
    date_time_scanner dts;
    if (!fmt.timestamp_formats.empty()) dts.custom = &fmt.timestamp_formats;
    dts.set_base_time(lf.mtime);
    int64_t last_time = 0;
    bool have_time = false;
    for (int i = 0; i < (int) lf.lines.size(); i++) {
        const std::string& line = lf.lines[i];
        auto& ll = lf.meta[i];
        js::value root;
        logmsg m;
        m.first_line = i;
        m.line_count = 1;
        bool ok = false;
        int64_t us = 0;
        exttm tm;
        if (js::parse(line, root) && root.is_object()) {
            if (get_json_time(fmt, root, dts, us, tm)) ok = true;
        }
        if (ok) {
            ll.actual_usecs = us;
            ll.time_usecs = (have_time && us < last_time) ? last_time : us;
            if (!have_time || us > last_time) last_time = us;
            have_time = true;
            ll.has_tm = true;
            ll.tm = tm;
            ll.ts_flags = tm.flags;
            int level = LEVEL_INFO;
            const js::value* lv = jsonlog_lookup(root, fmt.level_field);
            if (lv && !lv->is_null()) {
                level = fmt.convert_level(jsonlog_value_str(*lv));
            }
            ll.level = level;
            m.json = root;
            m.is_json = true;
        } else {
            ll.actual_usecs = last_time;
            ll.time_usecs = last_time;
            ll.level = LEVEL_INVALID;
            m.is_json = true;
            m.json = js::value();
        }
        ll.msg_index = (int) lf.msgs.size();
        lf.msgs.push_back(m);
    }
    extern void jsonlog_render_all(logfile & lf);
    jsonlog_render_all(lf);
}
