#include <algorithm>
#include <cstring>

#include "app.hh"
#include "jsonlog.hh"
#include "logfile.hh"
#include "util.hh"

static std::string transform(const std::string& s, const std::string& how)
{
    if (how == "uppercase") return upper(s);
    if (how == "lowercase") return lower(s);
    if (how == "capitalize") {
        std::string r = s;
        if (!r.empty()) r[0] = toupper((unsigned char) r[0]);
        return r;
    }
    return s;
}

static std::string json_display_value(const js::value& v)
{
    return jsonlog_value_str(v);
}

static std::string ts_string(const logfile& lf, const logmsg& m, const line_format_elem& el)
{
    auto& ll = lf.meta[m.first_line];
    const js::value* tv = jsonlog_lookup(m.json, lf.fmt->timestamp_field);
    if (!el.timestamp_format.empty()) {
        exttm tm = epoch_to_tm(ll.time_usecs / 1000000, (int) (ll.time_usecs % 1000000) * 1000);
        tm.flags = ETF_MILLIS_SET;
        return ftime_fmt(el.timestamp_format, tm);
    }
    if (tv && tv->is_string()) {
        if (ll.ts_flags & ETF_ZONE_SET) {
            int prec = 3;
            if (ll.ts_flags & ETF_MICROS_SET) prec = 6;
            if (ll.ts_flags & ETF_NANOS_SET) prec = 6;
            std::string s = format_iso_time(ll.actual_usecs, prec, 'T');
            return s;
        }
        return tv->s;
    }
    return format_iso_time(ll.actual_usecs, 3, 'T');
}

static void render_msg(logfile& lf, logmsg& m, std::vector<int>& auto_widths)
{
    auto& fmt = *lf.fmt;
    m.json_lines.clear();
    if (m.json.is_null() || !m.json.is_object()) {
        m.json_lines.push_back(lf.lines[m.first_line]);
        return;
    }
    std::string line;
    std::set<std::string> used;
    used.insert(fmt.timestamp_field);
    for (size_t ei = 0; ei < fmt.line_format.size(); ei++) {
        auto& el = fmt.line_format[ei];
        if (!el.is_field) {
            line += el.text;
            continue;
        }
        std::string val;
        bool have = false;
        if (el.field == "__timestamp__") {
            val = ts_string(lf, m, el);
            have = true;
        } else if (el.field == "__level__") {
            val = level_name(lf.meta[m.first_line].level);
            have = true;
        } else {
            used.insert(el.field);
