static std::string arg_text(sqlite3_value* v)
{
    const unsigned char* t = sqlite3_value_text(v);
    if (!t) return "";
    return std::string((const char*) t, sqlite3_value_bytes(v));
}

static bool arg_null(sqlite3_value* v)
{
    return sqlite3_value_type(v) == SQLITE_NULL;
}

static void result_text(sqlite3_context* ctx, const std::string& s)
{
    sqlite3_result_text(ctx, s.data(), (int) s.size(), SQLITE_TRANSIENT);
