// regex cache
static std::shared_ptr<regex> cached_regex(sqlite3_context* ctx, const std::string& pat)
{
    static std::map<std::string, std::shared_ptr<regex>> CACHE;
    auto it = CACHE.find(pat);
    if (it != CACHE.end()) return it->second;
    std::string err;
    int off = 0;
    auto re = regex::compile(pat, &err, &off);
    if (!re) {
        std::string m = "Invalid regular expression: " + err;
        sqlite3_result_error(ctx, m.c_str(), -1);
        return nullptr;
    }
    CACHE[pat] = re;
    return re;
}

static void fn_regexp(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0]) || arg_null(argv[1])) {
        sqlite3_result_null(ctx);
        return;
    }
    auto re = cached_regex(ctx, arg_text(argv[0]));
    if (!re) return;
    std::string s = arg_text(argv[1]);
    sqlite3_result_int(ctx, re->search(s) ? 1 : 0);
}

static js::value capture_value(const std::string& s)
{
    // convert numbers when possible
    if (!s.empty()) {
        char* end = nullptr;
        errno = 0;
        long long v = strtoll(s.c_str(), &end, 10);
        if (end && *end == '\0' && errno == 0 && (isdigit((unsigned char) s[0]) || s[0] == '-')) {
            js::value r = js::value::make_int(v);
            return r;
        }
        double d = strtod(s.c_str(), &end);
        if (end && *end == '\0' && (isdigit((unsigned char) s[0]) || s[0] == '-' || s[0] == '.')
            && s.find_first_of("xXnN") == std::string::npos)
        {
            js::value r = js::value::make_real(d);
            r.s = s;
            return r;
        }
    }
    return js::value::make_string(s);
}

static void fn_regexp_match(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_error(ctx, "no regular expression given", -1);
        return;
    }
    if (arg_null(argv[1])) {
        sqlite3_result_null(ctx);
        return;
    }
    auto re = cached_regex(ctx, arg_text(argv[0]));
    if (!re) return;
    std::string s = arg_text(argv[1]);
    std::vector<regex_capture> caps;
    if (!re->match(s, caps)) {
        sqlite3_result_null(ctx);
        return;
    }
    int cc = re->capture_count();
    if (cc == 0) {
        result_text(ctx, s.substr(caps[0].start, caps[0].length()));
        return;
    }
    if (cc == 1 && re->names().empty()) {
        if (!caps[1].valid()) {
            sqlite3_result_null(ctx);
            return;
        }
        std::string v = s.substr(caps[1].start, caps[1].length());
        js::value jv = capture_value(v);
        if (jv.is_int()) sqlite3_result_int64(ctx, jv.i);
        else if (jv.is_real()) sqlite3_result_double(ctx, jv.d);
        else result_text(ctx, v);
        return;
    }
    js::value obj = js::value::make_object();
    int unnamed = 0;
    for (int i = 1; i <= cc; i++) {
        std::string n = re->index_name(i);
        if (n.empty()) n = "col_" + std::to_string(unnamed++);
        if (!caps[i].valid()) {
            obj.set(n, js::value());
            continue;
        }
        obj.set(n, capture_value(s.substr(caps[i].start, caps[i].length())));
    }
