static std::string expand_replacement(const std::string& repl, const std::string& s,
                                      const std::vector<regex_capture>& caps, const regex& re)
{
    std::string r;
    for (size_t i = 0; i < repl.size(); i++) {
        char c = repl[i];
        if (c == '\\' && i + 1 < repl.size()) {
            char n = repl[i + 1];
            if (isdigit((unsigned char) n)) {
                int idx = n - '0';
                i++;
                if (idx < (int) caps.size() && caps[idx].valid())
                    r += s.substr(caps[idx].start, caps[idx].length());
                continue;
            }
            if (n == '\\') {
                r.push_back('\\');
                i++;
                continue;
            }
        }
        r.push_back(c);
    }
    return r;
}

static void fn_regexp_replace(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    auto re = cached_regex(ctx, arg_text(argv[1]));
    if (!re) return;
    std::string repl = arg_text(argv[2]);
    std::string out;
    size_t off = 0;
    std::vector<regex_capture> caps;
    while (off <= s.size() && re->match(s.data(), s.size(), off, caps)) {
        out += s.substr(off, caps[0].start - off);
        out += expand_replacement(repl, s, caps, *re);
        if (caps[0].end == caps[0].start) {
            if (caps[0].end < (int) s.size()) out.push_back(s[caps[0].end]);
            off = caps[0].end + 1;
        } else {
            off = caps[0].end;
        }
    }
    if (off < s.size()) out += s.substr(off);
    result_text(ctx, out);
}

