        {"regexp_replace", 3, fn_regexp_replace, true},
        {"startswith", 2, fn_startswith, true},
        {"endswith", 2, fn_endswith, true},
        {"raise_error", -1, fn_raise_error, false},
        {"lnav_version", 0, fn_lnav_version, true},
    };
    for (auto& f : FUNCS) {
        sqlite3_create_function(db, f.name, f.nargs,
                                SQLITE_UTF8 | (f.deterministic ? SQLITE_DETERMINISTIC : 0), nullptr,
                                f.fn, nullptr, nullptr);
    }
    register_more_functions(db);
}
