static void fn_charindex(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0]) || arg_null(argv[1])) {
        sqlite3_result_null(ctx);
        return;
    }
    auto needle = utf8_chars(arg_text(argv[0]));
    auto hay = utf8_chars(arg_text(argv[1]));
    long long start = argc > 2 ? sqlite3_value_int64(argv[2]) - 1 : 0;
    if (start < 0) start = 0;
    if (needle.empty()) {
        sqlite3_result_int(ctx, 0);
        return;
    }
    for (size_t i = start; i + needle.size() <= hay.size(); i++) {
        bool m = true;
        for (size_t j = 0; j < needle.size(); j++) {
            if (hay[i + j] != needle[j]) {
                m = false;
                break;
            }
        }
        if (m) {
            sqlite3_result_int64(ctx, (sqlite3_int64) i + 1);
            return;
        }
    }
    sqlite3_result_int(ctx, 0);
}

