    std::string r;
    long long start = (long long) ch.size() - n;
    if (start < 0) start = 0;
    for (long long i = start; i < (long long) ch.size(); i++) r += ch[i];
    result_text(ctx, r);
}

static void fn_reverse(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    auto ch = utf8_chars(arg_text(argv[0]));
    std::string r;
    for (auto it = ch.rbegin(); it != ch.rend(); ++it) r += *it;
    result_text(ctx, r);
}

static void fn_proper(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    bool start = true;
    for (auto& c : s) {
        if (isspace((unsigned char) c)) {
            start = true;
        } else {
            c = start ? toupper((unsigned char) c) : tolower((unsigned char) c);
            start = false;
        }
    }
    result_text(ctx, s);
}

static void fn_padl(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    long long n = sqlite3_value_int64(argv[1]);
    long long l = (long long) utf8_len(s);
    if (l < n) s = std::string(n - l, ' ') + s;
    result_text(ctx, s);
}

static void fn_padr(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    long long n = sqlite3_value_int64(argv[1]);
    long long l = (long long) utf8_len(s);
    if (l < n) s += std::string(n - l, ' ');
    result_text(ctx, s);
}

static void fn_padc(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    long long n = sqlite3_value_int64(argv[1]);
    long long l = (long long) utf8_len(s);
    if (l < n) {
        long long total = n - l;
        long long left = total / 2;
        long long right = total - left;
        s = std::string(left, ' ') + s + std::string(right, ' ');
    }
    result_text(ctx, s);
}

static void fn_strfilter(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0]) || arg_null(argv[1])) {
        sqlite3_result_null(ctx);
        return;
    }
    auto src = utf8_chars(arg_text(argv[0]));
    auto keep = utf8_chars(arg_text(argv[1]));
    std::string r;
    for (auto& c : src) {
        if (std::find(keep.begin(), keep.end(), c) != keep.end()) r += c;
    }
    result_text(ctx, r);
}

// --- path functions ---------------------------------------------------------

static void fn_basename(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string p = arg_text(argv[0]);
    if (p.empty()) {
        result_text(ctx, ".");
        return;
    }
    size_t end = p.size();
    while (end > 1 && (p[end - 1] == '/' || p[end - 1] == '\\')) end--;
    if (end == 1 && (p[0] == '/' || p[0] == '\\')) {
        result_text(ctx, p.substr(0, 1));
        return;
    }
    size_t start = end;
    while (start > 0 && p[start - 1] != '/' && p[start - 1] != '\\') start--;
    result_text(ctx, p.substr(start, end - start));
}

static void fn_dirname(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string p = arg_text(argv[0]);
    if (p.empty()) {
        result_text(ctx, ".");
        return;
    }
    size_t end = p.size();
    while (end > 1 && (p[end - 1] == '/' || p[end - 1] == '\\')) end--;
    size_t pos = end;
    while (pos > 0 && p[pos - 1] != '/' && p[pos - 1] != '\\') pos--;
    if (pos == 0) {
        result_text(ctx, ".");
        return;
    }
    size_t dend = pos - 1;
    while (dend > 0 && (p[dend - 1] == '/' || p[dend - 1] == '\\')) dend--;
    if (dend == 0) {
        result_text(ctx, p.substr(0, 1));
        return;
    }
    result_text(ctx, p.substr(0, dend));
}

static void fn_joinpath(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    std::string r;
    for (int i = 0; i < argc; i++) {
        if (arg_null(argv[i])) continue;
        std::string p = arg_text(argv[i]);
        if (p.empty()) continue;
        if (p[0] == '/' || p[0] == '\\') {
            r = p;
        } else if (r.empty()) {
            r = p;
        } else {
            if (r.back() != '/' && r.back() != '\\') r += "/";
            r += p;
        }
    }
    result_text(ctx, r);
}

static void fn_readlink(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string p = arg_text(argv[0]);
    char buf[PATH_MAX];
    ssize_t n = readlink(p.c_str(), buf, sizeof(buf) - 1);
    if (n < 0) {
        if (errno == EINVAL) {
            result_text(ctx, p);
            return;
        }
        std::string m = "unable to read link: " + p + " -- " + strerror(errno);
        sqlite3_result_error(ctx, m.c_str(), -1);
        return;
    }
    result_text(ctx, std::string(buf, n));
}

static void fn_realpath(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string p = arg_text(argv[0]);
    char buf[PATH_MAX];
    if (!realpath(p.c_str(), buf)) {
        std::string m = "Could not get real path for " + p + " -- " + strerror(errno);
        sqlite3_result_error(ctx, m.c_str(), -1);
        return;
    }
    result_text(ctx, buf);
}

// --- json functions -----------------------------------------------------------

static js::value sql_to_json(sqlite3_value* v)
{
    switch (sqlite3_value_type(v)) {
        case SQLITE_NULL: return js::value();
        case SQLITE_INTEGER: return js::value::make_int(sqlite3_value_int64(v));
        case SQLITE_FLOAT: {
            js::value r = js::value::make_real(sqlite3_value_double(v));
            char buf[64];
            snprintf(buf, sizeof(buf), "%.20g", r.d);
            r.s = buf;
            if (r.s.find_first_of(".eEn") == std::string::npos) r.s += ".0";
            return r;
        }
        default: {
            std::string t = arg_text(v);
            if (sqlite3_value_subtype(v) == 74) {
                js::value r;
                if (js::parse(t, r)) return r;
            }
            return js::value::make_string(t);
        }
    }
}

static void fn_jget(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        if (argc > 2) sqlite3_result_value(ctx, argv[2]);
        else sqlite3_result_null(ctx);
        return;
    }
    std::string text = arg_text(argv[0]);
    std::string ptr = argc > 1 ? arg_text(argv[1]) : "";
    js::value root;
    if (!js::parse(text, root)) {
        if (argc > 2) {
            sqlite3_result_value(ctx, argv[2]);
            return;
        }
        sqlite3_result_null(ctx);
        return;
    }
    const js::value* cur = &root;
    if (!ptr.empty()) {
        if (ptr[0] != '/') {
            sqlite3_result_error(ctx, "Invalid JSON pointer", -1);
            return;
        }
        size_t pos = 1;
        while (cur && pos <= ptr.size()) {
            size_t e = ptr.find('/', pos);
            std::string tok = ptr.substr(pos, e == std::string::npos ? std::string::npos : e - pos);
            tok = replace_all(replace_all(tok, "~1", "/"), "~0", "~");
            if (cur->is_object()) {
                cur = cur->get(tok);
            } else if (cur->is_array()) {
                char* end = nullptr;
                long idx = strtol(tok.c_str(), &end, 10);
                if (end && *end == '\0' && idx >= 0 && idx < (long) cur->arr->size())
                    cur = &(*cur->arr)[idx];
                else cur = nullptr;
            } else {
                cur = nullptr;
            }
            if (e == std::string::npos) break;
            pos = e + 1;
        }
    }
    if (!cur) {
        if (argc > 2) sqlite3_result_value(ctx, argv[2]);
        else sqlite3_result_null(ctx);
        return;
    }
    switch (cur->t) {
        case js::type_t::null: sqlite3_result_null(ctx); break;
        case js::type_t::boolean: sqlite3_result_int(ctx, cur->b ? 1 : 0); break;
        case js::type_t::integer: sqlite3_result_int64(ctx, cur->i); break;
        case js::type_t::real: sqlite3_result_double(ctx, cur->d); break;
        case js::type_t::string: result_text(ctx, cur->s); break;
        default: result_json(ctx, js::dump(*cur));
    }
}

static void fn_json_concat(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    js::value arr = js::value::make_array();
    for (int i = 0; i < argc; i++) {
        if (arg_null(argv[i])) continue;
        if (i == 0) {
            js::value v;
            if (js::parse(arg_text(argv[0]), v)) {
                if (v.is_array()) {
                    for (auto& e : *v.arr) arr.push(e);
                } else {
                    arr.push(v);
                }
            }
            continue;
        }
        if (sqlite3_value_subtype(argv[i]) == 74 || sqlite3_value_type(argv[i]) == SQLITE_TEXT) {
            js::value v;
            std::string t = arg_text(argv[i]);
            if (sqlite3_value_subtype(argv[i]) == 74 && js::parse(t, v)) {
                if (v.is_array()) {
                    for (auto& e : *v.arr) arr.push(e);
                } else {
                    arr.push(v);
                }
                continue;
            }
        }
        arr.push(sql_to_json(argv[i]));
    }
    result_json(ctx, js::dump(arr));
}

static bool json_equal(const js::value& a, const js::value& b)
{
    if (a.is_number() && b.is_number()) return a.as_double() == b.as_double();
    if (a.t != b.t) return false;
    switch (a.t) {
        case js::type_t::null: return true;
        case js::type_t::boolean: return a.b == b.b;
        case js::type_t::string: return a.s == b.s;
        default: return js::dump(a) == js::dump(b);
    }
}

static void fn_json_contains(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_int(ctx, 0);
        return;
    }
    js::value v;
    if (!js::parse(arg_text(argv[0]), v)) {
        sqlite3_result_error(ctx, "Invalid JSON", -1);
        return;
    }
    js::value needle = sql_to_json(argv[1]);
    if (v.is_array()) {
        for (auto& e : *v.arr) {
            if (json_equal(e, needle)) {
                sqlite3_result_int(ctx, 1);
                return;
            }
        }
        sqlite3_result_int(ctx, 0);
        return;
    }
    sqlite3_result_int(ctx, json_equal(v, needle) ? 1 : 0);
}

struct json_agg {
    js::value* v;
};

static void json_group_array_step(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    auto** pp = (js::value**) sqlite3_aggregate_context(ctx, sizeof(js::value*));
    if (!*pp) *pp = new js::value(js::value::make_array());
    for (int i = 0; i < argc; i++) (*pp)->push(sql_to_json(argv[i]));
}

static void json_group_array_final(sqlite3_context* ctx)
{
    auto** pp = (js::value**) sqlite3_aggregate_context(ctx, 0);
    if (!pp || !*pp) {
        result_json(ctx, "[]");
        return;
    }
    result_json(ctx, js::dump(**pp));
    delete *pp;
    *pp = nullptr;
}

static void json_group_object_step(sqlite3_context* ctx, int argc, sqlite3_value** argv)
