    auto** pp = (js::value**) sqlite3_aggregate_context(ctx, sizeof(js::value*));
    if (!*pp) *pp = new js::value(js::value::make_object());
    for (int i = 0; i + 1 < argc; i += 2) {
        if (arg_null(argv[i])) continue;
        (*pp)->obj->emplace_back(arg_text(argv[i]), sql_to_json(argv[i + 1]));
    }
}

static void json_group_object_final(sqlite3_context* ctx)
