static void json_count_of_step(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    auto** pp = (js::value**) sqlite3_aggregate_context(ctx, sizeof(js::value*));
    if (!*pp) *pp = new js::value(js::value::make_object());
    if (arg_null(argv[0])) return;
    std::string k = arg_text(argv[0]);
    js::value* v = (*pp)->get_mut(k);
    if (v) v->i++;
    else (*pp)->set(k, js::value::make_int(1));
