static void json_sum_of_step(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    auto** pp = (js::value**) sqlite3_aggregate_context(ctx, sizeof(js::value*));
    if (!*pp) *pp = new js::value(js::value::make_object());
    if (arg_null(argv[0])) return;
    std::string k = arg_text(argv[0]);
    js::value* v = (*pp)->get_mut(k);
    bool isint = sqlite3_value_type(argv[1]) == SQLITE_INTEGER;
    if (!v) {
        (*pp)->set(k, isint ? js::value::make_int(sqlite3_value_int64(argv[1]))
                            : js::value::make_real(sqlite3_value_double(argv[1])));
        return;
    }
    if (v->is_int() && isint) {
        v->i += sqlite3_value_int64(argv[1]);
    } else {
        double d = v->as_double() + sqlite3_value_double(argv[1]);
        *v = js::value::make_real(d);
    }
}

