// parse_url / unparse_url
static std::string url_decode(const std::string& s, bool plus_space)
{
    std::string r;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '%' && i + 2 < s.size() + 1 && i + 2 <= s.size() - 1 + 1 && i + 2 < s.size() + 0 + 1) {
            if (i + 2 < s.size() || i + 2 == s.size() - 1 + 1) {
            }
            if (i + 2 <= s.size() - 1) {
                r.push_back((char) strtol(s.substr(i + 1, 2).c_str(), nullptr, 16));
                i += 2;
                continue;
            }
        }
        if (plus_space && s[i] == '+') {
            r.push_back(' ');
            continue;
        }
        r.push_back(s[i]);
    }
    return r;
}

static std::string url_encode_component(const std::string& s)
{
    std::string r;
    char buf[4];
    for (unsigned char c : s) {
        if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
            r.push_back(c);
        } else {
            snprintf(buf, sizeof(buf), "%%%02X", c);
            r += buf;
        }
    }
    return r;
}

static void fn_parse_url(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string u = arg_text(argv[0]);
    js::value r = js::value::make_object();
    size_t p = u.find("://");
    if (p == std::string::npos) {
        std::string m = "invalid URL: " + u;
        sqlite3_result_error(ctx, m.c_str(), -1);
        return;
    }
    std::string scheme = u.substr(0, p);
    std::string rest = u.substr(p + 3);
    std::string fragment, query, path = "/", authority;
    bool has_frag = false, has_query = false;
    size_t h = rest.find('#');
    if (h != std::string::npos) {
        fragment = rest.substr(h + 1);
        rest = rest.substr(0, h);
        has_frag = true;
    }
    size_t q = rest.find('?');
    if (q != std::string::npos) {
        query = rest.substr(q + 1);
        rest = rest.substr(0, q);
        has_query = true;
    }
    size_t sl = rest.find('/');
    if (sl != std::string::npos) {
        path = rest.substr(sl);
        authority = rest.substr(0, sl);
    } else {
        authority = rest;
    }
    js::value username, password, port, host;
    size_t at = authority.rfind('@');
    if (at != std::string::npos) {
        std::string ui = authority.substr(0, at);
        authority = authority.substr(at + 1);
        size_t c = ui.find(':');
        if (c != std::string::npos) {
            username = js::value::make_string(url_decode(ui.substr(0, c), false));
            password = js::value::make_string(url_decode(ui.substr(c + 1), false));
        } else {
            username = js::value::make_string(url_decode(ui, false));
        }
    }
    std::string hoststr = authority;
    if (!authority.empty() && authority[0] == '[') {
        size_t e = authority.find(']');
        if (e != std::string::npos) {
            hoststr = authority.substr(0, e + 1);
            if (e + 1 < authority.size() && authority[e + 1] == ':') {
                port = js::value::make_int(atoll(authority.substr(e + 2).c_str()));
            }
        }
    } else {
        size_t c = authority.rfind(':');
        if (c != std::string::npos) {
            hoststr = authority.substr(0, c);
            port = js::value::make_int(atoll(authority.substr(c + 1).c_str()));
        }
    }
    host = js::value::make_string(hoststr);
    r.set("scheme", js::value::make_string(scheme));
    r.set("username", username);
    r.set("password", password);
    r.set("host", host);
    r.set("port", port);
    r.set("path", js::value::make_string(url_decode(path, false)));
    r.set("query", has_query ? js::value::make_string(query) : js::value());
    if (has_query) {
        js::value params = js::value::make_object();
        for (auto& kv : split(query, '&')) {
            if (kv.empty()) continue;
            size_t e = kv.find('=');
            if (e == std::string::npos) {
                params.set(url_decode(kv, true), js::value());
            } else {
                params.set(url_decode(kv.substr(0, e), true), js::value::make_string(url_decode(kv.substr(e + 1), true)));
            }
        }
        r.set("parameters", params);
    } else {
        r.set("parameters", js::value());
    }
    r.set("fragment", has_frag ? js::value::make_string(fragment) : js::value());
    result_json(ctx, js::dump(r));
}

static void fn_unparse_url(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    js::value v;
    if (!js::parse(arg_text(argv[0]), v) || !v.is_object()) {
        sqlite3_result_error(ctx, "invalid URL object", -1);
        return;
    }
    auto gs = [&](const char* k) -> std::string {
        auto* e = v.get(k);
        if (!e || e->is_null()) return "";
        return jsonlog_value_str(*e);
    };
    std::string r = gs("scheme") + "://";
    std::string user = gs("username"), pass = gs("password");
    if (!user.empty()) {
        r += url_encode_component(user);
        if (!pass.empty()) r += ":" + url_encode_component(pass);
        r += "@";
    }
    r += gs("host");
    std::string port = gs("port");
    if (!port.empty()) r += ":" + port;
    std::string path = gs("path");
    if (path.empty()) path = "/";
    r += path;
    auto* params = v.get("parameters");
    std::string query = gs("query");
    if (params && params->is_object() && !params->obj->empty()) {
        std::string qs;
        for (auto& kv : *params->obj) {
            if (!qs.empty()) qs += "&";
            qs += url_encode_component(kv.first);
            if (!kv.second.is_null()) qs += "=" + url_encode_component(jsonlog_value_str(kv.second));
        }
        r += "?" + qs;
    } else if (!query.empty()) {
        r += "?" + query;
    }
    std::string frag = gs("fragment");
    if (!frag.empty()) r += "#" + frag;
    result_text(ctx, r);
}

static void fn_lnav_top_file(sqlite3_context* ctx, int, sqlite3_value**)
{
    APP.ensure_log_view();
    if (APP.cur_view == view_t::log && !APP.log_view.empty()) {
        int t = std::min(APP.log_top, (int) APP.log_view.size() - 1);
        result_text(ctx, APP.files[APP.log_view[t].file]->path);
        return;
    }
    if (APP.cur_view == view_t::text && APP.text_file >= 0) {
        result_text(ctx, APP.files[APP.text_file]->path);
        return;
    }
    sqlite3_result_null(ctx);
}

