// --- string functions --------------------------------------------------------

static size_t utf8_len(const std::string& s)
{
    size_t n = 0;
    for (unsigned char c : s)
        if ((c & 0xC0) != 0x80) n++;
    return n;
}

static std::vector<std::string> utf8_chars(const std::string& s)
{
    std::vector<std::string> r;
    size_t i = 0;
    while (i < s.size()) {
        size_t b = i;
        i++;
        while (i < s.size() && (((unsigned char) s[i]) & 0xC0) == 0x80) i++;
        r.push_back(s.substr(b, i - b));
    }
    return r;
}

static void fn_replicate(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    long long n = sqlite3_value_int64(argv[1]);
    if (n < 0) {
        sqlite3_result_error(ctx, "domain error", -1);
        return;
    }
    std::string r;
    for (long long i = 0; i < n; i++) r += s;
    result_text(ctx, r);
}

static void fn_charindex(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0]) || arg_null(argv[1])) {
        sqlite3_result_null(ctx);
        return;
    }
    auto needle = utf8_chars(arg_text(argv[0]));
    auto hay = utf8_chars(arg_text(argv[1]));
    long long start = argc > 2 ? sqlite3_value_int64(argv[2]) - 1 : 0;
    if (start < 0) start = 0;
    if (needle.empty()) {
        sqlite3_result_int(ctx, 0);
        return;
    }
    for (size_t i = start; i + needle.size() <= hay.size(); i++) {
        bool m = true;
        for (size_t j = 0; j < needle.size(); j++) {
            if (hay[i + j] != needle[j]) {
                m = false;
                break;
            }
        }
        if (m) {
            sqlite3_result_int64(ctx, (sqlite3_int64) i + 1);
            return;
        }
    }
    sqlite3_result_int(ctx, 0);
}

