// --- humanize -----------------------------------------------------------------

std::string humanize_duration_ms(int64_t ms)
{
    bool neg = ms < 0;
    if (neg) ms = -ms;
    if (ms == 0) return "0s";
    struct iv {
        int64_t len;
        const char* sym;
        int width;
    };
    const iv ivs[] = {{1000, "ms", 3}, {60, "s", 2}, {60, "m", 2}, {24, "h", 2}, {0, "d", 0}};
    std::string r;
    int64_t remaining = ms;
    for (int i = 0; i < 5; i++) {
        int64_t amount;
        if (ivs[i].len) {
            amount = remaining % ivs[i].len;
            remaining /= ivs[i].len;
        } else {
            amount = remaining;
            remaining = 0;
        }
        if (i == 0 && amount == 0 && remaining > 0) continue;
        if (amount == 0 && remaining == 0) break;
        char buf[32];
        if (remaining == 0) snprintf(buf, sizeof(buf), "%lld%s", (long long) amount, ivs[i].sym);
        else snprintf(buf, sizeof(buf), "%0*lld%s", ivs[i].width, (long long) amount, ivs[i].sym);
        r.insert(0, buf);
    }
    if (neg) r.insert(0, "-");
    return r;
}

static void fn_humanize_duration(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    double secs = sqlite3_value_double(argv[0]);
    int64_t ms = (int64_t) llround(secs * 1000.0);
    result_text(ctx, humanize_duration_ms(ms));
}

std::string humanize_file_size_str(double value)
{
    static const char* UNITS[] = {" ", "K", "M", "G", "T", "P", "E"};
    if (value < 0) return "Unknown";
    double ex = value > 0 ? std::floor(std::min(log(value) / log(1000.0), 6.0)) : 0;
    double divisor = pow(1000.0, ex);
    char buf[64];
    if (divisor <= 1) {
        snprintf(buf, sizeof(buf), "%lldB", (long long) value);
        return buf;
    }
    snprintf(buf, sizeof(buf), "%.1f%sB", value / divisor, UNITS[(int) ex]);
    return buf;
}

