    std::vector<double>* vals;
};

static void sparkline_step(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    auto** pp = (std::vector<double>**) sqlite3_aggregate_context(ctx, sizeof(void*));
    if (!*pp) *pp = new std::vector<double>();
    if (arg_null(argv[0])) return;
