extern bool parse_relative_time(const std::string& s, int64_t base, int64_t& out, std::string* err);

static bool value_to_usecs(sqlite3_value* v, int64_t& out)
{
    switch (sqlite3_value_type(v)) {
        case SQLITE_INTEGER: out = sqlite3_value_int64(v) * 1000; return true;  // msecs
        case SQLITE_FLOAT: out = (int64_t) (sqlite3_value_double(v) * 1000.0); return true;
        case SQLITE_NULL: return false;
        default: {
            std::string s = arg_text(v);
            return parse_relative_time(s, now_usecs(), out, nullptr);
        }
    }
}

static bool parse_slice(const std::string& s, int64_t& usecs)
{
    std::string t = trim(s);
    size_t i = 0;
    int64_t total = 0;
    bool any = false;
    while (i < t.size()) {
        while (i < t.size() && t[i] == ' ') i++;
        size_t ns = i;
        while (i < t.size() && (isdigit((unsigned char) t[i]) || t[i] == '.')) i++;
        double n = ns == i ? 1 : atof(t.substr(ns, i - ns).c_str());
        while (i < t.size() && t[i] == ' ') i++;
        size_t us = i;
        while (i < t.size() && isalpha((unsigned char) t[i])) i++;
        std::string unit = lower(t.substr(us, i - us));
        if (unit.empty()) return false;
        int64_t mult;
        if (unit == "s" || unit == "sec" || unit == "secs" || unit == "second" || unit == "seconds") mult = 1000000;
        else if (unit == "m" || unit == "min" || unit == "mins" || unit == "minute" || unit == "minutes") mult = 60000000LL;
        else if (unit == "h" || unit == "hr" || unit == "hour" || unit == "hours") mult = 3600000000LL;
        else if (unit == "d" || unit == "day" || unit == "days") mult = 86400000000LL;
        else if (unit == "w" || unit == "week" || unit == "weeks") mult = 7 * 86400000000LL;
        else if (unit == "ms") mult = 1000;
        else return false;
        total += (int64_t) (n * mult);
        any = true;
    }
    usecs = total;
    return any && total > 0;
}

static void fn_timeslice(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    int64_t t;
    if (!value_to_usecs(argv[0], t)) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string slice = arg_null(argv[1]) ? "" : arg_text(argv[1]);
    int64_t sl;
    if (!parse_slice(slice, sl)) {
        std::string m = "unable to parse time slice value: " + slice;
        sqlite3_result_error(ctx, m.c_str(), -1);
        return;
    }
    int64_t r = t - (((t % sl) + sl) % sl);
    result_text(ctx, format_sql_time(r));
}

static void fn_timediff(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    int64_t a, b;
    if (!value_to_usecs(argv[0], a) || !value_to_usecs(argv[1], b)) {
        sqlite3_result_null(ctx);
        return;
    }
    sqlite3_result_double(ctx, (double) (a - b) / 1000000.0);
}

// --- encode/decode ------------------------------------------------------------

static const char* B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static std::string b64_encode(const std::string& in)
{
    std::string out;
    int val = 0, valb = -6;
    for (unsigned char c : in) {
        val = (val << 8) + c;
        valb += 8;
        while (valb >= 0) {
            out.push_back(B64[(val >> valb) & 0x3F]);
            valb -= 6;
        }
    }
    if (valb > -6) out.push_back(B64[((val << 8) >> (valb + 8)) & 0x3F]);
    while (out.size() % 4) out.push_back('=');
    return out;
}

static std::string b64_decode(const std::string& in)
{
    std::string out;
    std::vector<int> T(256, -1);
    for (int i = 0; i < 64; i++) T[(unsigned char) B64[i]] = i;
    int val = 0, valb = -8;
    for (unsigned char c : in) {
        if (T[c] == -1) continue;
        val = (val << 6) + T[c];
        valb += 6;
        if (valb >= 0) {
            out.push_back(char((val >> valb) & 0xFF));
            valb -= 8;
        }
    }
    return out;
}

static void fn_encode(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    std::string alg = lower(arg_text(argv[1]));
    if (alg == "base64") {
        result_text(ctx, b64_encode(s));
    } else if (alg == "hex") {
        std::string r;
        char buf[4];
        for (unsigned char c : s) {
            snprintf(buf, sizeof(buf), "%02x", c);
            r += buf;
        }
        result_text(ctx, r);
    } else if (alg == "uri") {
        std::string r;
        char buf[4];
        for (unsigned char c : s) {
            if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
                r.push_back(c);
            } else {
                snprintf(buf, sizeof(buf), "%%%02X", c);
                r += buf;
            }
        }
        result_text(ctx, r);
    } else {
        std::string m = "invalid algorithm: " + alg;
        sqlite3_result_error(ctx, m.c_str(), -1);
    }
}

static void fn_decode(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string s = arg_text(argv[0]);
    std::string alg = lower(arg_text(argv[1]));
    if (alg == "base64") {
        std::string d = b64_decode(s);
        sqlite3_result_blob(ctx, d.data(), (int) d.size(), SQLITE_TRANSIENT);
    } else if (alg == "hex") {
        std::string r;
        for (size_t i = 0; i + 1 < s.size(); i += 2) r.push_back((char) strtol(s.substr(i, 2).c_str(), nullptr, 16));
        sqlite3_result_blob(ctx, r.data(), (int) r.size(), SQLITE_TRANSIENT);
    } else if (alg == "uri") {
        std::string r;
        for (size_t i = 0; i < s.size(); i++) {
            if (s[i] == '%' && i + 2 < s.size() + 0 && i + 2 <= s.size() - 1 + 1) {
                if (i + 2 < s.size() || i + 2 == s.size() - 0) {
                }
                r.push_back((char) strtol(s.substr(i + 1, 2).c_str(), nullptr, 16));
                i += 2;
            } else {
                r.push_back(s[i]);
            }
        }
        result_text(ctx, r);
    } else {
        std::string m = "invalid algorithm: " + alg;
        sqlite3_result_error(ctx, m.c_str(), -1);
    }
}

static void fn_gzip(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    std::string in;
    for (int i = 0; i < argc; i++) {
        if (arg_null(argv[i])) continue;
        const void* b = sqlite3_value_blob(argv[i]);
        in.append((const char*) b, sqlite3_value_bytes(argv[i]));
    }
    z_stream zs;
    memset(&zs, 0, sizeof(zs));
    deflateInit2(&zs, Z_DEFAULT_COMPRESSION, Z_DEFLATED, 15 + 16, 8, Z_DEFAULT_STRATEGY);
    zs.next_in = (Bytef*) in.data();
    zs.avail_in = in.size();
    std::string out;
    char buf[16384];
    int rc;
    do {
        zs.next_out = (Bytef*) buf;
        zs.avail_out = sizeof(buf);
        rc = deflate(&zs, Z_FINISH);
        out.append(buf, sizeof(buf) - zs.avail_out);
    } while (rc == Z_OK);
    deflateEnd(&zs);
    sqlite3_result_blob(ctx, out.data(), (int) out.size(), SQLITE_TRANSIENT);
}

static void fn_gunzip(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    std::string out;
    for (int i = 0; i < argc; i++) {
        if (arg_null(argv[i])) continue;
        const void* b = sqlite3_value_blob(argv[i]);
        int n = sqlite3_value_bytes(argv[i]);
        z_stream zs;
        memset(&zs, 0, sizeof(zs));
        inflateInit2(&zs, 15 + 32);
        zs.next_in = (Bytef*) b;
        zs.avail_in = n;
        char buf[16384];
        int rc;
        do {
            zs.next_out = (Bytef*) buf;
            zs.avail_out = sizeof(buf);
            rc = inflate(&zs, Z_NO_FLUSH);
            out.append(buf, sizeof(buf) - zs.avail_out);
        } while (rc == Z_OK);
        inflateEnd(&zs);
        if (rc != Z_STREAM_END) {
            sqlite3_result_error(ctx, "unable to uncompress data", -1);
            return;
        }
    }
    sqlite3_result_text(ctx, out.data(), (int) out.size(), SQLITE_TRANSIENT);
}

