static void fn_shell_exec(sqlite3_context* ctx, int argc, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string cmd = arg_text(argv[0]);
    std::string input = argc > 1 && !arg_null(argv[1]) ? arg_text(argv[1]) : "";
    std::string tmp;
    if (argc > 1 && !arg_null(argv[1])) {
        char tpl[] = "/tmp/lnav-shell-exec-XXXXXX";
        int fd = mkstemp(tpl);
        if (fd >= 0) {
            if (write(fd, input.data(), input.size()) < 0) {
            }
            close(fd);
            tmp = tpl;
            cmd = "(" + cmd + ") < " + tmp;
        }
    }
    FILE* p = popen(cmd.c_str(), "r");
    if (!p) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string out;
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), p)) > 0) out.append(buf, n);
    pclose(p);
    if (!tmp.empty()) unlink(tmp.c_str());
    result_text(ctx, out);
}

// fuzzy match (fts_fuzzy_match style)
static bool fuzzy_match_recursive(const char* pattern, const char* str, int& outScore,
                                  const char* strBegin, const unsigned char* srcMatches,
                                  unsigned char* matches, int maxMatches, int nextMatch,
                                  int& recursionCount, int recursionLimit)
{
    ++recursionCount;
    if (recursionCount >= recursionLimit) return false;
    if (*pattern == '\0' || *str == '\0') return false;
    bool recursiveMatch = false;
    unsigned char bestRecursiveMatches[256];
    int bestRecursiveScore = 0;
    bool first_match = true;
    while (*pattern != '\0' && *str != '\0') {
        if (tolower((unsigned char) *pattern) == tolower((unsigned char) *str)) {
            if (nextMatch >= maxMatches) return false;
            if (first_match && srcMatches) {
                memcpy(matches, srcMatches, nextMatch);
                first_match = false;
            }
            unsigned char recursiveMatches[256];
            int recursiveScore;
            if (fuzzy_match_recursive(pattern, str + 1, recursiveScore, strBegin, matches,
                                      recursiveMatches, sizeof(recursiveMatches), nextMatch,
                                      recursionCount, recursionLimit))
            {
                if (!recursiveMatch || recursiveScore > bestRecursiveScore) {
                    memcpy(bestRecursiveMatches, recursiveMatches, 256);
                    bestRecursiveScore = recursiveScore;
                }
                recursiveMatch = true;
            }
            matches[nextMatch++] = (unsigned char) (str - strBegin);
            ++pattern;
        }
        ++str;
    }
    bool matched = *pattern == '\0';
    if (matched) {
        const int sequential_bonus = 15;
        const int separator_bonus = 30;
        const int camel_bonus = 30;
        const int first_letter_bonus = 15;
        const int leading_letter_penalty = -5;
        const int max_leading_letter_penalty = -15;
        const int unmatched_letter_penalty = -1;
        while (*str != '\0') ++str;
        outScore = 100;
        int penalty = leading_letter_penalty * matches[0];
        if (penalty < max_leading_letter_penalty) penalty = max_leading_letter_penalty;
        outScore += penalty;
        int unmatched = (int) (str - strBegin) - nextMatch;
        outScore += unmatched_letter_penalty * unmatched;
        for (int i = 0; i < nextMatch; ++i) {
            unsigned char currIdx = matches[i];
            if (i > 0) {
                unsigned char prevIdx = matches[i - 1];
                if (currIdx == (prevIdx + 1)) outScore += sequential_bonus;
            }
            if (currIdx > 0) {
                char neighbor = strBegin[currIdx - 1];
                char curr = strBegin[currIdx];
                if (islower((unsigned char) neighbor) && isupper((unsigned char) curr)) outScore += camel_bonus;
                bool neighborSeparator = neighbor == '_' || neighbor == ' ' || neighbor == '-'
                    || neighbor == '/' || neighbor == '.';
                if (neighborSeparator) outScore += separator_bonus;
            } else {
                outScore += first_letter_bonus;
            }
        }
    }
    if (recursiveMatch && (!matched || bestRecursiveScore > outScore)) {
        memcpy(matches, bestRecursiveMatches, maxMatches);
        outScore = bestRecursiveScore;
        return true;
    } else if (matched) {
        return true;
    }
    return false;
}

static void fn_fuzzy_match(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0]) || arg_null(argv[1])) {
        sqlite3_result_null(ctx);
        return;
    }
    std::string pat = arg_text(argv[0]);
    std::string str = arg_text(argv[1]);
    if (pat.empty()) {
        sqlite3_result_int(ctx, 0);
        return;
    }
    unsigned char matches[256];
    int score = 0;
    int rc = 0;
    if (str.size() > 255) str = str.substr(0, 255);
    if (fuzzy_match_recursive(pat.c_str(), str.c_str(), score, str.c_str(), nullptr, matches,
                              sizeof(matches), 0, rc, 10))
    {
        sqlite3_result_int(ctx, score);
    } else {
        sqlite3_result_null(ctx);
    }
}

// logfmt2json / extract
static js::value scalar_from_text(const std::string& v, bool quoted)
{
    if (quoted) return js::value::make_string(v);
    if (v == "true") return js::value::make_bool(true);
    if (v == "false") return js::value::make_bool(false);
    if (v == "null") return js::value();
    char* end = nullptr;
    if (!v.empty() && (isdigit((unsigned char) v[0]) || ((v[0] == '-' || v[0] == '+') && v.size() > 1))) {
        errno = 0;
        long long iv = strtoll(v.c_str(), &end, 10);
        if (end && *end == '\0' && errno == 0) return js::value::make_int(iv);
        double d = strtod(v.c_str(), &end);
        if (end && *end == '\0') {
            js::value r = js::value::make_real(d);
            r.s = v;
            return r;
        }
    }
    return js::value::make_string(v);
}

static bool parse_logfmt(const std::string& s, js::value& out)
{
    out = js::value::make_object();
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && isspace((unsigned char) s[i])) i++;
        if (i >= s.size()) break;
        size_t ks = i;
        while (i < s.size() && s[i] != '=' && !isspace((unsigned char) s[i])) i++;
        std::string key = s.substr(ks, i - ks);
        if (i >= s.size() || s[i] != '=') {
            out.set(key, js::value::make_bool(true));
            continue;
        }
        i++;
        std::string val;
        bool quoted = false;
        if (i < s.size() && s[i] == '"') {
            quoted = true;
            i++;
            while (i < s.size() && s[i] != '"') {
                if (s[i] == '\\' && i + 1 < s.size()) {
                    i++;
                    char e = s[i];
                    if (e == 'n') val.push_back('\n');
                    else if (e == 't') val.push_back('\t');
                    else val.push_back(e);
                } else {
                    val.push_back(s[i]);
                }
                i++;
            }
            if (i < s.size()) i++;
        } else {
            size_t vs = i;
            while (i < s.size() && !isspace((unsigned char) s[i])) i++;
            val = s.substr(vs, i - vs);
        }
        out.set(key, scalar_from_text(val, quoted));
    }
    return true;
}

static void fn_logfmt2json(sqlite3_context* ctx, int, sqlite3_value** argv)
{
    if (arg_null(argv[0])) {
        sqlite3_result_null(ctx);
        return;
    }
    js::value v;
    parse_logfmt(arg_text(argv[0]), v);
    result_json(ctx, js::dump(v));
}

