    static auto HEX_RE = regex::compile(R"(^0x[0-9a-fA-F]+\b)");
    static auto URL_RE = regex::compile(R"(^[a-zA-Z][a-zA-Z0-9+.-]*://[^\s"']+)");
    static auto PATH_RE = regex::compile(R"(^(?:/[\w.\-]+)+/?)");
    std::vector<regex_capture> caps;
    while (i < s.size()) {
        char c = s[i];
        token t;
        t.start = i;
        if (isspace((unsigned char) c)) {
            size_t j = i;
            while (j < s.size() && isspace((unsigned char) s[j])) j++;
            t.type = tok_t::white;
            t.text = s.substr(i, j - i);
            i = j;
        } else if (c == '"' || c == '\'') {
            size_t j = i + 1;
            std::string v;
            while (j < s.size() && s[j] != c) {
                if (s[j] == '\\' && j + 1 < s.size()) {
                    v.push_back(s[j + 1]);
                    j += 2;
                    continue;
                }
                v.push_back(s[j]);
                j++;
