            t.text = s.substr(i, caps[0].end - i);
            i = caps[0].end;
        } else if (IP_RE->match(s.data(), s.size(), i, caps, PCRE2_ANCHORED)) {
            t.type = tok_t::ip;
            t.text = s.substr(i, caps[0].end - i);
            i = caps[0].end;
        } else if (HEX_RE->match(s.data(), s.size(), i, caps, PCRE2_ANCHORED)) {
            t.type = tok_t::hex;
