struct spooky_ctx {
    u64 data[2 * NUMVARS];
    u64 state[NUMVARS];
    size_t length = 0;
    uint8_t remainder = 0;

    void init(u64 s1, u64 s2)
    {
        length = 0;
        remainder = 0;
        state[0] = s1;
        state[1] = s2;
    }

    void update(const void* message, size_t len)
    {
        u64 h[NUMVARS];
        size_t new_length = len + remainder;
        if (new_length < BUFSIZE) {
            memcpy(&((uint8_t*) data)[remainder], message, len);
