            remainder = (uint8_t) new_length;
            return;
        }
        if (length < BUFSIZE) {
            h[0] = h[3] = h[6] = h[9] = state[0];
            h[1] = h[4] = h[7] = h[10] = state[1];
            h[2] = h[5] = h[8] = h[11] = SC_CONST;
        } else {
