        for (size_t i = 0; i < nblocks; i++) {
            u64 blk[NUMVARS];
            memcpy(blk, p + i * BLOCKSIZE, BLOCKSIZE);
            mix(blk, h);
        }
        size_t rem = len - nblocks * BLOCKSIZE;
        remainder = (uint8_t) rem;
        memcpy(data, p + nblocks * BLOCKSIZE, rem);
        memcpy(state, h, sizeof(h));
    }

    void final(u64* hash1, u64* hash2)
    {
