            mix(d, h);
            d += NUMVARS;
            rem -= BLOCKSIZE;
        }
        memset(&((uint8_t*) d)[rem], 0, BLOCKSIZE - rem);
        ((uint8_t*) d)[BLOCKSIZE - 1] = rem;
        end_block(d, h);
