    auto* def = (simple_table*) aux;
    int rc = sqlite3_declare_vtab(db, def->schema.c_str());
    if (rc != SQLITE_OK) {
        *err = sqlite3_mprintf("%s", sqlite3_errmsg(db));
        return rc;
    }
    auto* vt = new st_vtab();
    memset(&vt->base, 0, sizeof(vt->base));
    vt->def = def;
    *ppvt = &vt->base;
    return SQLITE_OK;
}

static int st_disconnect(sqlite3_vtab* vt)
{
    delete (st_vtab*) vt;
    return SQLITE_OK;
}

static int st_best_index(sqlite3_vtab* tab, sqlite3_index_info* info)
{
    auto* vt = (st_vtab*) tab;
    auto& args = vt->def->arg_cols;
    std::vector<int> found(args.size(), -1);
    for (int i = 0; i < info->nConstraint; i++) {
        auto& c = info->aConstraint[i];
        if (!c.usable || c.op != SQLITE_INDEX_CONSTRAINT_EQ) continue;
        for (size_t a = 0; a < args.size(); a++) {
            if (args[a] == c.iColumn) found[a] = i;
        }
    }
    int nused = 0;
    for (size_t a = 0; a < args.size(); a++) {
        if (found[a] < 0) break;
        info->aConstraintUsage[found[a]].argvIndex = ++nused;
        info->aConstraintUsage[found[a]].omit = 1;
    }
    if (nused < vt->def->required_args) {
        info->estimatedCost = 1e12;
    } else {
        info->estimatedCost = 1000;
    }
    info->idxNum = nused;
    return SQLITE_OK;
}

static int st_open(sqlite3_vtab*, sqlite3_vtab_cursor** cur)
{
    auto* c = new st_cursor();
    memset(&c->base, 0, sizeof(c->base));
    *cur = &c->base;
    return SQLITE_OK;
}

static int st_close(sqlite3_vtab_cursor* cur)
{
    delete (st_cursor*) cur;
    return SQLITE_OK;
}

static int st_filter(sqlite3_vtab_cursor* cur, int idxnum, const char*, int argc, sqlite3_value** argv)
{
    auto* c = (st_cursor*) cur;
    auto* vt = (st_vtab*) cur->pVtab;
    std::vector<sqlite3_value*> args(argv, argv + argc);
    c->rows.clear();
    c->idx = 0;
    if ((int) args.size() < vt->def->required_args) {
        return SQLITE_OK;
    }
    vt->def->fill(args, c->rows);
    return SQLITE_OK;
}

static int st_next(sqlite3_vtab_cursor* cur)
{
    ((st_cursor*) cur)->idx++;
    return SQLITE_OK;
}

static int st_eof(sqlite3_vtab_cursor* cur)
{
    auto* c = (st_cursor*) cur;
    return c->idx >= c->rows.size();
}

static int st_column(sqlite3_vtab_cursor* cur, sqlite3_context* ctx, int col)
{
    auto* c = (st_cursor*) cur;
    auto& row = c->rows[c->idx];
    if (col >= (int) row.size()) {
        sqlite3_result_null(ctx);
        return SQLITE_OK;
    }
    auto& v = row[col];
    switch (v.type) {
        case SQLITE_NULL: sqlite3_result_null(ctx); break;
        case SQLITE_INTEGER: sqlite3_result_int64(ctx, v.i); break;
        case SQLITE_FLOAT: sqlite3_result_double(ctx, v.d); break;
        case SQLITE_BLOB: sqlite3_result_blob(ctx, v.s.data(), (int) v.s.size(), SQLITE_TRANSIENT); break;
        default:
            sqlite3_result_text(ctx, v.s.data(), (int) v.s.size(), SQLITE_TRANSIENT);
            if (v.json) sqlite3_result_subtype(ctx, 74);
    }
    return SQLITE_OK;
}

static int st_rowid(sqlite3_vtab_cursor* cur, sqlite3_int64* rowid)
{
    *rowid = (sqlite3_int64) ((st_cursor*) cur)->idx;
    return SQLITE_OK;
}

static int st_update(sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64* rowid)
{
    auto* vt = (st_vtab*) tab;
    if (!vt->def->update) {
        tab->zErrMsg = sqlite3_mprintf("table is read-only");
        return SQLITE_READONLY;
    }
    return vt->def->update(tab, argc, argv, rowid);
}

static sqlite3_module ST_MODULE = {
    0,       st_connect, st_connect, st_best_index, st_disconnect, st_disconnect,
    st_open, st_close,   st_filter,  st_next,       st_eof,        st_column,
    st_rowid, st_update, nullptr,    nullptr,       nullptr,       nullptr,
    nullptr, nullptr,    nullptr,    nullptr,       nullptr,       nullptr,
};

static std::string arg_str(sqlite3_value* v)
{
    const unsigned char* t = sqlite3_value_text(v);
    return t ? std::string((const char*) t, sqlite3_value_bytes(v)) : "";
}

static std::vector<simple_table*> TABLES;

static void register_table(sqlite3* db, const std::string& name, simple_table* t, bool eponymous)
{
    TABLES.push_back(t);
    std::string mod = name + "_impl";
    sqlite3_create_module(db, mod.c_str(), &ST_MODULE, t);
    std::string sql = "CREATE VIRTUAL TABLE lnav_db." + name + " USING " + mod + "()";
    sqlite3_exec(db, sql.c_str(), nullptr, nullptr, nullptr);
}

std::string spooky_line_hash(const std::string& s);
std::string current_view_name();

static std::string content_id_for(const logfile& lf)
{
    extern std::string spooky_text_hash(const std::string& s);
    if (lf.is_log()) {
        for (auto& m : lf.msgs) {
            auto& ll = lf.meta[m.first_line];
            if (ll.has_tm) return "v1:" + spooky_text_hash(lf.lines[m.first_line]);
        }
    }
    return "v1:" + spooky_text_hash(lf.path);
}

static const char* VIEW_NAMES[] = {"log", "text", "help", "histogram", "db", "schema", "pretty", "spectro", "timeline"};

void sql_register_misc_vtabs(sqlite3* db)
{
    // lnav_file
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE lnav_file (device INTEGER, inode INTEGER, filepath TEXT, mimetype TEXT, "
            "content_id TEXT, format TEXT, lines INTEGER, time_offset INTEGER, options_path TEXT, "
            "options TEXT, content BLOB HIDDEN)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            for (auto& f : APP.files) {
                std::vector<cell> r;
                r.push_back(cell::integer((int64_t) f->dev));
                r.push_back(cell::integer((int64_t) f->ino));
                r.push_back(cell::text(f->path));
                r.push_back(cell::text(f->mimetype()));
                r.push_back(cell::text(content_id_for(*f)));
                r.push_back(f->fmt ? cell::text(f->fmt->name) : cell::null());
                r.push_back(cell::integer((int64_t) f->lines.size()));
                r.push_back(cell::integer(f->time_offset));
                r.push_back(cell::null());
                r.push_back(cell::null());
                r.push_back(cell::blob(f->content));
                rows.push_back(r);
            }
        };
        t->update = [](sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1) {
                tab->zErrMsg = sqlite3_mprintf("Rows cannot be deleted from the lnav_file table");
                return SQLITE_ERROR;
            }
            if (sqlite3_value_type(argv[0]) == SQLITE_NULL) {
                tab->zErrMsg = sqlite3_mprintf("Rows cannot be inserted into the lnav_file table");
                return SQLITE_ERROR;
            }
            int64_t idx = sqlite3_value_int64(argv[0]);
            if (idx >= 0 && idx < (int64_t) APP.files.size()) {
                auto& f = APP.files[idx];
                if (sqlite3_value_type(argv[2 + 7]) == SQLITE_INTEGER) {
                    f->time_offset = sqlite3_value_int64(argv[2 + 7]);
                }
            }
            return SQLITE_OK;
        };
        register_table(db, "lnav_file", t, true);
    }
    // environ
    {
        auto* t = new simple_table();
        t->schema = "CREATE TABLE environ (name TEXT PRIMARY KEY, value TEXT)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            for (char** e = environ; e && *e; e++) {
                std::string kv = *e;
                auto eq = kv.find('=');
                if (eq == std::string::npos) continue;
                rows.push_back({cell::text(kv.substr(0, eq)), cell::text(kv.substr(eq + 1))});
            }
        };
        t->update = [](sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1) {
                // delete: need name of row; rowid is index
                int64_t idx = sqlite3_value_int64(argv[0]);
                int64_t i = 0;
                for (char** e = environ; e && *e; e++, i++) {
                    if (i == idx) {
                        std::string kv = *e;
                        unsetenv(kv.substr(0, kv.find('=')).c_str());
                        break;
                    }
                }
                return SQLITE_OK;
            }
            if (sqlite3_value_type(argv[2]) == SQLITE_NULL) {
                tab->zErrMsg = sqlite3_mprintf("A non-empty name and value must be provided when inserting an environment variable");
                return SQLITE_ERROR;
            }
            std::string name = arg_str(argv[2]);
            if (name.empty() || name.find('=') != std::string::npos) {
                tab->zErrMsg = sqlite3_mprintf("A non-empty name and value must be provided when inserting an environment variable");
                return SQLITE_ERROR;
            }
            if (sqlite3_value_type(argv[0]) != SQLITE_NULL) {
                // update: remove old name
                int64_t idx = sqlite3_value_int64(argv[0]);
                int64_t i = 0;
                for (char** e = environ; e && *e; e++, i++) {
                    if (i == idx) {
                        std::string kv = *e;
                        std::string old = kv.substr(0, kv.find('='));
                        if (old != name) unsetenv(old.c_str());
                        break;
                    }
                }
            }
            std::string value = arg_str(argv[3]);
            setenv(name.c_str(), value.c_str(), 1);
            return SQLITE_OK;
        };
        register_table(db, "environ", t, true);
    }
    // lnav_view_stack
    {
        auto* t = new simple_table();
        t->schema = "CREATE TABLE lnav_view_stack (name TEXT)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            std::vector<std::string> names;
            for (auto& v : APP.view_stack) names.push_back(VIEW_NAMES[(int) v]);
            names.push_back(VIEW_NAMES[(int) APP.cur_view]);
            for (auto& n : names) rows.push_back({cell::text(n)});
        };
        register_table(db, "lnav_view_stack", t, true);
    }
    // lnav_views
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE lnav_views (name TEXT PRIMARY KEY, top INTEGER, left INTEGER, height INTEGER, "
            "inner_height INTEGER, top_time DATETIME, top_file TEXT, paused INTEGER, search TEXT, "
            "filtering INTEGER, movement TEXT, top_meta TEXT, selection INTEGER, options TEXT, "
            "selected_text TEXT, row_details TEXT)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            APP.ensure_log_view();
            for (int vi = 0; vi < 9; vi++) {
                std::vector<cell> r;
                r.push_back(cell::text(VIEW_NAMES[vi]));
                int top = 0, inner = 0;
                cell top_time = cell::null(), top_file = cell::null();
                if (vi == 0) {
                    top = APP.log_top;
                    inner = (int) APP.log_view.size();
                    if (!APP.log_view.empty()) {
                        auto& vl = APP.log_view[std::min(top, inner - 1)];
                        auto& lf = *APP.files[vl.file];
                        top_time = cell::text(format_sql_time(lf.meta[lf.msgs[vl.msg].first_line].time_usecs));
                        top_file = cell::text(lf.path);
                    }
                } else if (vi == 1) {
                    top = APP.text_top;
                    APP.rebuild_text_view();
                    inner = (int) APP.text_visible.size();
                    if (APP.text_file >= 0) top_file = cell::text(APP.files[APP.text_file]->path);
                } else if (vi == 4) {
                    top = APP.db_top;
                    inner = (int) APP.db.rows.size();
                }
                r.push_back(cell::integer(top));
                r.push_back(cell::integer(0));
                r.push_back(cell::integer(vi == 0 ? 24 : (vi == 1 ? std::max(inner, 1) : 1)));
                r.push_back(cell::integer(inner));
                r.push_back(top_time);
                r.push_back(top_file);
                r.push_back(cell::integer(0));
                r.push_back(cell::text(""));
                r.push_back(cell::integer(vi == 0 || vi == 1 || vi == 8 ? 1 : 0));
                r.push_back(cell::text(vi == 7 || vi == 8 ? "cursor" : "top"));
                r.push_back(cell::null());
                r.push_back(cell::integer(top));
                r.push_back(cell::text("{\"hidden-fields\":\"hide\",\"word-wrap\":\"none\"}", true));
                r.push_back(cell::null());
                r.push_back(cell::null());
                rows.push_back(r);
            }
        };
        t->update = [](sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1 || sqlite3_value_type(argv[0]) == SQLITE_NULL) {
                tab->zErrMsg = sqlite3_mprintf("views cannot be inserted or deleted");
                return SQLITE_ERROR;
            }
            std::string name = arg_str(argv[2]);
            int64_t top = sqlite3_value_int64(argv[3]);
            if (name == "log") APP.log_top = (int) top;
            else if (name == "text") APP.text_top = (int) top;
            else if (name == "db") APP.db_top = (int) top;
            return SQLITE_OK;
        };
        register_table(db, "lnav_views", t, true);
    }
    // lnav_view_filters
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE lnav_view_filters (view_name TEXT, filter_id INTEGER, enabled INTEGER, "
            "type TEXT, language TEXT, pattern TEXT)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            for (auto& f : APP.filters) {
                rows.push_back({cell::text("log"), cell::integer(f.id), cell::integer(f.enabled ? 1 : 0),
                                cell::text(f.is_in ? "in" : "out"), cell::text(f.lang), cell::text(f.pattern)});
            }
            if (!APP.filter_expr.empty()) {
                rows.push_back({cell::text("log"), cell::integer(0), cell::integer(1), cell::text("in"),
                                cell::text("sql"), cell::text(APP.filter_expr)});
            }
            for (auto& f : APP.text_filters) {
                rows.push_back({cell::text("text"), cell::integer(f.id), cell::integer(f.enabled ? 1 : 0),
                                cell::text(f.is_in ? "in" : "out"), cell::text(f.lang), cell::text(f.pattern)});
            }
        };
        t->update = [](sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1) {
                int64_t idx = sqlite3_value_int64(argv[0]);
                int64_t n = (int64_t) APP.filters.size();
                if (idx < n) APP.filters.erase(APP.filters.begin() + idx);
                else if (idx - n - (APP.filter_expr.empty() ? 0 : 1) < (int64_t) APP.text_filters.size()) {
                    int64_t ti = idx - n - (APP.filter_expr.empty() ? 0 : 1);
                    if (ti >= 0) APP.text_filters.erase(APP.text_filters.begin() + ti);
                    else APP.filter_expr.clear();
                }
                APP.log_dirty = true;
                return SQLITE_OK;
            }
            std::string view = sqlite3_value_type(argv[2]) == SQLITE_NULL ? "log" : arg_str(argv[2]);
            bool enabled = sqlite3_value_type(argv[4]) == SQLITE_NULL ? true : sqlite3_value_int(argv[4]) != 0;
            std::string type = sqlite3_value_type(argv[5]) == SQLITE_NULL ? "out" : arg_str(argv[5]);
            std::string lang = sqlite3_value_type(argv[6]) == SQLITE_NULL ? "regex" : arg_str(argv[6]);
            std::string pattern = arg_str(argv[7]);
            std::string err;
            int off;
            auto re = regex::compile(pattern, &err, &off);
            if (!re && lang == "regex") {
                tab->zErrMsg = sqlite3_mprintf("invalid regular expression: %s", err.c_str());
                return SQLITE_ERROR;
            }
            auto& fl = view == "text" ? APP.text_filters : APP.filters;
            if (sqlite3_value_type(argv[0]) == SQLITE_NULL) {
                filter_def f;
                f.id = APP.next_filter_id++;
                f.enabled = enabled;
                f.is_in = type == "in";
                f.lang = lang;
                f.pattern = pattern;
                f.re = re;
                fl.push_back(f);
            } else {
                int64_t idx = sqlite3_value_int64(argv[0]);
                if (idx < (int64_t) APP.filters.size()) {
                    auto& f = APP.filters[idx];
                    f.enabled = enabled;
                    f.is_in = type == "in";
                    f.pattern = pattern;
                    f.re = re;
                }
            }
            APP.log_dirty = true;
            return SQLITE_OK;
        };
        register_table(db, "lnav_view_filters", t, true);
    }
    // lnav_view_filter_stats
    {
        auto* t = new simple_table();
        t->schema = "CREATE TABLE lnav_view_filter_stats (view_name TEXT, filter_id INTEGER, hits INTEGER)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            APP.log_dirty = true;
            APP.ensure_log_view();
            for (auto& f : APP.filters) {
                rows.push_back({cell::text("log"), cell::integer(f.id), cell::integer(f.hits)});
            }
            APP.rebuild_text_view();
            for (auto& f : APP.text_filters) {
                rows.push_back({cell::text("text"), cell::integer(f.id), cell::integer(f.hits)});
            }
        };
        register_table(db, "lnav_view_filter_stats", t, true);
    }
    // lnav_view_files
    {
        auto* t = new simple_table();
        t->schema = "CREATE TABLE lnav_view_files (view_name TEXT, filepath TEXT, visible INTEGER)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t& rows) {
            for (auto& f : APP.files) {
                rows.push_back({cell::text(f->is_log() ? "log" : "text"), cell::text(f->path),
                                cell::integer(f->visible ? 1 : 0)});
            }
        };
        t->update = [](sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64*) {
            if (argc == 1 || sqlite3_value_type(argv[0]) == SQLITE_NULL) return SQLITE_OK;
            int64_t idx = sqlite3_value_int64(argv[0]);
            if (idx >= 0 && idx < (int64_t) APP.files.size()) {
                APP.files[idx]->visible = sqlite3_value_int(argv[4]) != 0;
                APP.log_dirty = true;
            }
            return SQLITE_OK;
        };
        register_table(db, "lnav_view_files", t, true);
    }
    // lnav_file_metadata
    {
        auto* t = new simple_table();
        t->schema = "CREATE TABLE lnav_file_metadata (filepath TEXT, descriptor TEXT, mimetype TEXT, content TEXT)";
        t->fill = [](const std::vector<sqlite3_value*>&, rows_t&) {};
        register_table(db, "lnav_file_metadata", t, true);
    }
    // regexp_capture
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE regexp_capture (match_index INTEGER, capture_index INTEGER, capture_name TEXT, "
            "capture_count INTEGER, range_start INTEGER, range_stop INTEGER, content TEXT, value TEXT HIDDEN, "
            "pattern TEXT HIDDEN)";
        t->arg_cols = {7, 8};
        t->required_args = 2;
        t->fill = [](const std::vector<sqlite3_value*>& args, rows_t& rows) {
            if (sqlite3_value_type(args[0]) == SQLITE_NULL || sqlite3_value_type(args[1]) == SQLITE_NULL) return;
            std::string s = arg_str(args[0]);
            std::string pat = arg_str(args[1]);
            auto re = regex::compile(pat);
            if (!re) return;
            std::vector<regex_capture> caps;
            size_t off = 0;
            int mi = 0;
            while (off <= s.size() && re->match(s.data(), s.size(), off, caps)) {
                int cc = re->capture_count() + 1;
                for (int ci = 0; ci < cc; ci++) {
                    std::string name = re->index_name(ci);
                    std::vector<cell> r;
                    r.push_back(cell::integer(mi));
                    r.push_back(cell::integer(ci));
                    r.push_back(name.empty() ? cell::null() : cell::text(name));
                    r.push_back(cell::integer(cc));
                    if (caps[ci].valid()) {
                        r.push_back(cell::integer(caps[ci].start + 1));
                        r.push_back(cell::integer(caps[ci].end + 1));
                        r.push_back(cell::text(s.substr(caps[ci].start, caps[ci].length())));
                    } else {
                        r.push_back(cell::null());
                        r.push_back(cell::null());
                        r.push_back(cell::null());
                    }
                    rows.push_back(r);
                }
                mi++;
                off = caps[0].end > caps[0].start ? caps[0].end : caps[0].end + 1;
            }
        };
        register_table(db, "regexp_capture", t, true);
    }
    // regexp_capture_into_json
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE regexp_capture_into_json (match_index INTEGER, content TEXT, value TEXT HIDDEN, "
            "pattern TEXT HIDDEN, flags TEXT HIDDEN)";
        t->arg_cols = {2, 3, 4};
        t->required_args = 2;
        t->fill = [](const std::vector<sqlite3_value*>& args, rows_t& rows) {
            if (sqlite3_value_type(args[0]) == SQLITE_NULL || sqlite3_value_type(args[1]) == SQLITE_NULL) return;
            std::string s = arg_str(args[0]);
            std::string pat = arg_str(args[1]);
            auto re = regex::compile(pat);
            if (!re) return;
            std::vector<regex_capture> caps;
            size_t off = 0;
            int mi = 0;
            extern js::value capture_value_pub(const std::string& s);
            while (off <= s.size() && re->match(s.data(), s.size(), off, caps)) {
                js::value obj = js::value::make_object();
                int unnamed = 0;
                for (int ci = 1; ci <= re->capture_count(); ci++) {
                    std::string n = re->index_name(ci);
                    if (n.empty()) n = "col_" + std::to_string(unnamed++);
                    if (!caps[ci].valid()) {
                        obj.set(n, js::value());
                        continue;
                    }
                    obj.set(n, capture_value_pub(s.substr(caps[ci].start, caps[ci].length())));
                }
                rows.push_back({cell::integer(mi++), cell::text(js::dump(obj), true)});
                off = caps[0].end > caps[0].start ? caps[0].end : caps[0].end + 1;
            }
        };
        register_table(db, "regexp_capture_into_json", t, true);
    }
    // generate_series
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE generate_series (value INTEGER, start INTEGER HIDDEN, stop INTEGER HIDDEN, "
            "step INTEGER HIDDEN)";
        t->arg_cols = {1, 2, 3};
        t->required_args = 1;
        t->fill = [](const std::vector<sqlite3_value*>& args, rows_t& rows) {
            int64_t start = sqlite3_value_int64(args[0]);
            int64_t stop = args.size() > 1 ? sqlite3_value_int64(args[1]) : INT32_MAX;
            int64_t step = args.size() > 2 ? sqlite3_value_int64(args[2]) : 1;
            if (step == 0) step = 1;
            if (step > 0) {
                for (int64_t v = start; v <= stop && rows.size() < 10000000; v += step)
                    rows.push_back({cell::integer(v)});
            } else {
                // count down from stop to start
                int64_t lo = start, hi = stop;
                if (lo > hi) std::swap(lo, hi);
                int64_t n = (hi - lo) / (-step);
                for (int64_t v = lo + n * (-step); v >= lo; v += step) rows.push_back({cell::integer(v)});
            }
        };
        sqlite3_create_module(db, "generate_series", &ST_MODULE, t);
        TABLES.push_back(t);
    }
    // fstat
    {
        auto* t = new simple_table();
        t->schema =
            "CREATE TABLE fstat (st_parent TEXT, st_name TEXT, st_dev INTEGER, st_ino INTEGER, "
