struct simple_table {
    std::string schema;  // CREATE TABLE x(...)
    std::vector<int> arg_cols;  // hidden argument columns (in order)
    std::function<void(const std::vector<sqlite3_value*>& args, rows_t& rows)> fill;
    std::function<int(sqlite3_vtab* tab, int argc, sqlite3_value** argv, sqlite3_int64* rowid)> update;
    int required_args = 0;
