static std::string decode_entities(const std::string& s)
{
    std::string r;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '&') {
            size_t e = s.find(';', i);
            if (e != std::string::npos) {
                std::string ent = s.substr(i + 1, e - i - 1);
                if (ent == "lt") r += "<";
                else if (ent == "gt") r += ">";
                else if (ent == "amp") r += "&";
                else if (ent == "quot") r += "\"";
                else if (ent == "apos") r += "'";
                else if (!ent.empty() && ent[0] == '#') {
                    uint32_t cp = ent.size() > 1 && (ent[1] == 'x' || ent[1] == 'X')
                        ? (uint32_t) strtoul(ent.c_str() + 2, nullptr, 16)
                        : (uint32_t) strtoul(ent.c_str() + 1, nullptr, 10);
                    utf8_append(r, cp);
                } else {
                    r += s.substr(i, e - i + 1);
                }
                i = e;
                continue;
            }
        }
        r.push_back(s[i]);
    }
    return r;
}

static bool parse_xml(const std::string& s, std::shared_ptr<xnode>& root, std::string& err)
{
    auto doc = std::make_shared<xnode>();
    doc->name = "";
    std::vector<xnode*> stack = {doc.get()};
    size_t i = 0;
    while (i < s.size()) {
        if (s[i] == '<') {
            if (s.compare(i, 4, "<!--") == 0) {
                size_t e = s.find("-->", i);
                if (e == std::string::npos) {
                    err = "unterminated comment";
                    return false;
                }
                i = e + 3;
                continue;
            }
            if (s.compare(i, 2, "<?") == 0 || s.compare(i, 2, "<!") == 0) {
                size_t e = s.find('>', i);
                if (e == std::string::npos) return false;
                i = e + 1;
                continue;
            }
