static std::vector<std::string> split_top(const std::string& s, char sep)
{
    std::vector<std::string> r;
    int depth = 0;
    char quote = 0;
    std::string cur;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (quote) {
            cur.push_back(c);
            if (c == '\\' && i + 1 < s.size()) {
                cur.push_back(s[++i]);
                continue;
            }
            if (c == quote) quote = 0;
            continue;
        }
        if (c == '"' || c == '\'') {
            quote = c;
            cur.push_back(c);
            continue;
        }
        if (c == '(' || c == '{' || c == '[') depth++;
        if (c == ')' || c == '}' || c == ']') depth--;
        if (depth == 0 && (c == sep || (sep == '|' && c == '\n'))) {
            if (sep == '|' && c == '|' && i + 1 < s.size() && s[i + 1] == '|') {
                cur += "||";
                i++;
                continue;
            }
            r.push_back(cur);
            cur.clear();
            continue;
        }
        cur.push_back(c);
    }
    r.push_back(cur);
    return r;
}

static std::string strip_braces(const std::string& s)
{
    std::string t = trim(s);
    if (t.size() >= 2 && t.front() == '{' && t.back() == '}') return trim(t.substr(1, t.size() - 2));
    return t;
}

static std::string translate_expr(const std::string& in)
{
    std::string e = trim(in);
    // aggregate function calls written as "func arg"
    static const std::pair<const char*, const char*> AGG[] = {
        {"count_distinct", "COUNT(DISTINCT %)"}, {"count", "COUNT(%)"}, {"sum", "SUM(%)"},
        {"average", "AVG(%)"}, {"avg", "AVG(%)"}, {"min", "MIN(%)"}, {"max", "MAX(%)"},
        {"stddev", "STDDEV(%)"}, {"any", "MAX(%)"}, {"every", "MIN(%)"},
    };
    for (auto& a : AGG) {
        std::string fn = a.first;
        if (startswith(e, fn + " ")) {
            std::string arg = trim(e.substr(fn.size()));
            std::string targ = arg == "this" ? "*" : translate_expr(arg);
            std::string tpl = a.second;
            if (targ == "*" && fn != "count") targ = "*";
            return replace_all(tpl, "%", targ);
        }
    }
    std::string r;
    for (size_t i = 0; i < e.size(); i++) {
        char c = e[i];
        if (c == '"') {
            size_t j = i + 1;
            std::string lit;
            while (j < e.size() && e[j] != '"') {
                if (e[j] == '\\' && j + 1 < e.size()) {
                    lit.push_back(e[j + 1]);
                    j += 2;
                    continue;
                }
                lit.push_back(e[j]);
                j++;
            }
            r += "'" + replace_all(lit, "'", "''") + "'";
            i = j;
            continue;
        }
        if (c == '\'') {
            size_t j = e.find('\'', i + 1);
            if (j == std::string::npos) j = e.size();
            r += e.substr(i, j - i + 1);
            i = j;
            continue;
        }
        if (c == 's' && i + 1 < e.size() && e[i + 1] == '"' && (i == 0 || !isalnum((unsigned char) e[i - 1]))) {
            size_t j = e.find('"', i + 2);
            if (j == std::string::npos) j = e.size();
            r += e.substr(i + 2, j - i - 2);
            i = j;
            continue;
        }
        if (c == '=' && i + 1 < e.size() && e[i + 1] == '=') {
            r += "=";
            i++;
            continue;
        }
        if (c == '&' && i + 1 < e.size() && e[i + 1] == '&') {
            r += "AND";
            i++;
            continue;
        }
        if (c == '|' && i + 1 < e.size() && e[i + 1] == '|') {
            r += "OR";
            i++;
            continue;
        }
        if (c == '!' && (i + 1 >= e.size() || e[i + 1] != '=')) {
            r += "NOT ";
            continue;
        }
        if (startswith(e.substr(i), "this.")) {
            i += 4;
            continue;
        }
        if (c == '~' && i + 1 < e.size() && e[i + 1] == '=') {
            r += "REGEXP";
            i++;
            continue;
        }
        r.push_back(c);
    }
    r = replace_all(r, " null", " NULL");
    return r;
}

