struct qstate {
    std::string from;
    std::vector<std::string> selects;
    std::vector<std::string> wheres;
    std::vector<std::string> groups;
    std::vector<std::string> havings;
    std::vector<std::string> orders;
    std::string limit, offset;
    bool aggregated = false;

    std::string render() const
    {
        std::string s = "SELECT ";
        if (selects.empty()) s += "*";
        for (size_t i = 0; i < selects.size(); i++) {
            if (i) s += ", ";
            s += selects[i];
        }
        s += " FROM " + from;
        if (!wheres.empty()) {
            s += " WHERE ";
            for (size_t i = 0; i < wheres.size(); i++) {
                if (i) s += " AND ";
                s += "(" + wheres[i] + ")";
            }
        }
        if (!groups.empty()) {
            s += " GROUP BY ";
            for (size_t i = 0; i < groups.size(); i++) {
                if (i) s += ", ";
                s += groups[i];
            }
        }
        if (!havings.empty()) {
            s += " HAVING ";
            for (size_t i = 0; i < havings.size(); i++) {
                if (i) s += " AND ";
                s += "(" + havings[i] + ")";
            }
        }
        if (!orders.empty()) {
            s += " ORDER BY ";
            for (size_t i = 0; i < orders.size(); i++) {
                if (i) s += ", ";
                s += orders[i];
            }
        }
        if (!limit.empty()) {
            s += " LIMIT " + limit;
            if (!offset.empty()) s += " OFFSET " + offset;
        }
        return s;
    }

    void wrap()
    {
        std::string sub = "(" + render() + ")";
        *this = qstate();
        from = sub;
    }
};

static std::vector<std::string> items_of(const std::string& args)
{
    std::vector<std::string> r;
    for (auto& it : split_top(strip_braces(args), ',')) {
        std::string t = trim(it);
        if (!t.empty()) r.push_back(t);
    }
    return r;
}

static void apply_aggregate(qstate& q, const std::string& args, const std::vector<std::string>& groups)
{
    if (q.aggregated || !q.limit.empty()) q.wrap();
    q.selects.clear();
    for (auto& g : groups) q.selects.push_back(g);
    for (auto& it : items_of(args)) {
        std::string name, expr;
        split_assign(it, name, expr);
        std::string sql = translate_expr(expr);
        if (!name.empty()) sql += " AS " + name;
        q.selects.push_back(sql);
    }
    q.groups = groups;
    q.aggregated = true;
}

bool prql_to_sql(const std::string& prql, std::string& sql, std::string& err)
{
    qstate q;
    // strip comments
    std::string text;
    for (auto& line : split(prql, '\n')) {
        auto h = line.find('#');
        text += (h == std::string::npos ? line : line.substr(0, h)) + "\n";
    }
    auto stages = split_top(text, '|');
    bool first = true;
    for (auto& st_raw : stages) {
        std::string st = trim(st_raw);
        if (st.empty()) continue;
        size_t sp = st.find_first_of(" \t\n");
        std::string tr = sp == std::string::npos ? st : st.substr(0, sp);
        std::string args = sp == std::string::npos ? "" : trim(st.substr(sp));
        if (first) {
            if (tr != "from") {
                err = "expecting 'from' at the start of the pipeline";
                return false;
            }
            q.from = args;
            first = false;
            continue;
        }
        if (tr == "select") {
            if (!q.selects.empty() && !q.aggregated) {
                // re-projection: just replace if simple
                q.wrap();
            } else if (q.aggregated) {
                q.wrap();
            }
            for (auto& it : items_of(args)) {
                std::string name, expr;
                split_assign(it, name, expr);
                std::string s = translate_expr(expr);
                if (!name.empty()) s += " AS " + name;
                q.selects.push_back(s);
            }
        } else if (tr == "derive") {
            if (q.aggregated || !q.limit.empty()) q.wrap();
            if (q.selects.empty()) q.selects.push_back("*");
            for (auto& it : items_of(args)) {
                std::string name, expr;
                split_assign(it, name, expr);
                std::string s = translate_expr(expr);
                if (!name.empty()) s += " AS " + name;
                q.selects.push_back(s);
            }
        } else if (tr == "filter") {
            if (!q.limit.empty()) q.wrap();
            if (q.aggregated) {
                q.havings.push_back(translate_expr(args));
            } else {
                q.wheres.push_back(translate_expr(args));
            }
        } else if (tr == "take") {
            std::string a = trim(args);
            auto dd = a.find("..");
            if (dd != std::string::npos) {
                long lo = atol(a.substr(0, dd).c_str());
                long hi = atol(a.substr(dd + 2).c_str());
                if (lo < 1) lo = 1;
                q.limit = std::to_string(hi - lo + 1);
                q.offset = std::to_string(lo - 1);
            } else {
                if (!q.limit.empty()) {
                    long cur = atol(q.limit.c_str());
                    long n = atol(a.c_str());
                    q.limit = std::to_string(std::min(cur, n));
                } else {
                    q.limit = a;
                }
            }
        } else if (tr == "sort") {
            if (!q.limit.empty()) q.wrap();
            q.orders.clear();
            for (auto& it : items_of(args)) {
                std::string t = trim(it);
                if (!t.empty() && t[0] == '-') {
                    q.orders.push_back(translate_expr(t.substr(1)) + " DESC");
                } else if (!t.empty() && t[0] == '+') {
                    q.orders.push_back(translate_expr(t.substr(1)));
                } else {
                    q.orders.push_back(translate_expr(t));
                }
            }
        } else if (tr == "group") {
            // group {cols} (aggregate {...})
            size_t p = args.find('(');
            std::string cols = p == std::string::npos ? args : args.substr(0, p);
            std::string inner = p == std::string::npos ? "" : args.substr(p + 1);
            if (!inner.empty() && inner.back() == ')') inner.pop_back();
            std::vector<std::string> groups;
            for (auto& g : items_of(cols)) groups.push_back(translate_expr(g));
            inner = trim(inner);
            if (startswith(inner, "aggregate")) {
                apply_aggregate(q, trim(inner.substr(9)), groups);
            } else {
                if (q.aggregated || !q.limit.empty()) q.wrap();
                q.selects = groups;
                q.groups = groups;
                q.aggregated = true;
            }
        } else if (tr == "aggregate") {
            apply_aggregate(q, args, {});
        } else if (tr == "stats.count_by") {
            std::vector<std::string> groups;
            for (auto& g : items_of(args)) groups.push_back(translate_expr(g));
            apply_aggregate(q, "{total = count this}", groups);
            q.orders = {"total DESC"};
        } else if (tr == "stats.average_of") {
            apply_aggregate(q, "{avg = average " + args + "}", {});
        } else if (tr == "stats.sum_of") {
            apply_aggregate(q, "{sum = sum " + args + "}", {});
        } else {
            err = "unknown transform -- " + tr;
            return false;
        }
    }
    sql = q.render();
    return true;
}
