// A small PRQL to SQL translator supporting a subset of the language.
#include <string>
#include <vector>

#include "util.hh"

static std::vector<std::string> split_top(const std::string& s, char sep)
{
    std::vector<std::string> r;
    int depth = 0;
    char quote = 0;
    std::string cur;
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (quote) {
            cur.push_back(c);
            if (c == '\\' && i + 1 < s.size()) {
                cur.push_back(s[++i]);
                continue;
            }
            if (c == quote) quote = 0;
            continue;
        }
        if (c == '"' || c == '\'') {
            quote = c;
            cur.push_back(c);
            continue;
        }
        if (c == '(' || c == '{' || c == '[') depth++;
        if (c == ')' || c == '}' || c == ']') depth--;
        if (depth == 0 && (c == sep || (sep == '|' && c == '\n'))) {
            if (sep == '|' && c == '|' && i + 1 < s.size() && s[i + 1] == '|') {
                cur += "||";
                i++;
                continue;
            }
            r.push_back(cur);
            cur.clear();
            continue;
        }
        cur.push_back(c);
    }
    r.push_back(cur);
    return r;
}

static std::string strip_braces(const std::string& s)
{
    std::string t = trim(s);
    if (t.size() >= 2 && t.front() == '{' && t.back() == '}') return trim(t.substr(1, t.size() - 2));
    return t;
}

static std::string translate_expr(const std::string& in)
{
    std::string e = trim(in);
    // aggregate function calls written as "func arg"
    static const std::pair<const char*, const char*> AGG[] = {
        {"count_distinct", "COUNT(DISTINCT %)"}, {"count", "COUNT(%)"}, {"sum", "SUM(%)"},
        {"average", "AVG(%)"}, {"avg", "AVG(%)"}, {"min", "MIN(%)"}, {"max", "MAX(%)"},
        {"stddev", "STDDEV(%)"}, {"any", "MAX(%)"}, {"every", "MIN(%)"},
    };
    for (auto& a : AGG) {
        std::string fn = a.first;
        if (startswith(e, fn + " ")) {
            std::string arg = trim(e.substr(fn.size()));
            std::string targ = arg == "this" ? "*" : translate_expr(arg);
            std::string tpl = a.second;
            if (targ == "*" && fn != "count") targ = "*";
            return replace_all(tpl, "%", targ);
        }
    }
    std::string r;
    for (size_t i = 0; i < e.size(); i++) {
        char c = e[i];
        if (c == '"') {
            size_t j = i + 1;
            std::string lit;
            while (j < e.size() && e[j] != '"') {
                if (e[j] == '\\' && j + 1 < e.size()) {
                    lit.push_back(e[j + 1]);
                    j += 2;
                    continue;
                }
                lit.push_back(e[j]);
                j++;
            }
            r += "'" + replace_all(lit, "'", "''") + "'";
            i = j;
            continue;
        }
        if (c == '\'') {
            size_t j = e.find('\'', i + 1);
            if (j == std::string::npos) j = e.size();
            r += e.substr(i, j - i + 1);
            i = j;
            continue;
        }
        if (c == 's' && i + 1 < e.size() && e[i + 1] == '"' && (i == 0 || !isalnum((unsigned char) e[i - 1]))) {
            size_t j = e.find('"', i + 2);
            if (j == std::string::npos) j = e.size();
            r += e.substr(i + 2, j - i - 2);
            i = j;
            continue;
        }
        if (c == '=' && i + 1 < e.size() && e[i + 1] == '=') {
            r += "=";
            i++;
            continue;
        }
        if (c == '&' && i + 1 < e.size() && e[i + 1] == '&') {
            r += "AND";
            i++;
            continue;
        }
        if (c == '|' && i + 1 < e.size() && e[i + 1] == '|') {
            r += "OR";
            i++;
            continue;
        }
        if (c == '!' && (i + 1 >= e.size() || e[i + 1] != '=')) {
            r += "NOT ";
            continue;
        }
        if (startswith(e.substr(i), "this.")) {
            i += 4;
            continue;
        }
        if (c == '~' && i + 1 < e.size() && e[i + 1] == '=') {
            r += "REGEXP";
            i++;
            continue;
        }
        r.push_back(c);
    }
    r = replace_all(r, " null", " NULL");
    return r;
}

// "name = expr" -> (name, expr)
static void split_assign(const std::string& item, std::string& name, std::string& expr)
{
    int depth = 0;
    for (size_t i = 0; i < item.size(); i++) {
        char c = item[i];
        if (c == '(' || c == '{') depth++;
        if (c == ')' || c == '}') depth--;
        if (depth == 0 && c == '=' && (i + 1 >= item.size() || item[i + 1] != '=')
            && (i == 0 || (item[i - 1] != '!' && item[i - 1] != '<' && item[i - 1] != '>' && item[i - 1] != '=')))
        {
            name = trim(item.substr(0, i));
            expr = trim(item.substr(i + 1));
            return;
        }
    }
    name.clear();
    expr = trim(item);
}

struct qstate {
    std::string from;
    std::vector<std::string> selects;
    std::vector<std::string> wheres;
    std::vector<std::string> groups;
    std::vector<std::string> havings;
    std::vector<std::string> orders;
    std::string limit, offset;
    bool aggregated = false;

    std::string render() const
    {
        std::string s = "SELECT ";
        if (selects.empty()) s += "*";
        for (size_t i = 0; i < selects.size(); i++) {
            if (i) s += ", ";
            s += selects[i];
        }
        s += " FROM " + from;
        if (!wheres.empty()) {
            s += " WHERE ";
            for (size_t i = 0; i < wheres.size(); i++) {
                if (i) s += " AND ";
                s += "(" + wheres[i] + ")";
            }
        }
        if (!groups.empty()) {
            s += " GROUP BY ";
            for (size_t i = 0; i < groups.size(); i++) {
                if (i) s += ", ";
                s += groups[i];
            }
        }
        if (!havings.empty()) {
            s += " HAVING ";
            for (size_t i = 0; i < havings.size(); i++) {
                if (i) s += " AND ";
                s += "(" + havings[i] + ")";
            }
        }
        if (!orders.empty()) {
            s += " ORDER BY ";
            for (size_t i = 0; i < orders.size(); i++) {
                if (i) s += ", ";
                s += orders[i];
            }
        }
        if (!limit.empty()) {
            s += " LIMIT " + limit;
            if (!offset.empty()) s += " OFFSET " + offset;
        }
        return s;
    }

    void wrap()
    {
        std::string sub = "(" + render() + ")";
        *this = qstate();
        from = sub;
    }
};

static std::vector<std::string> items_of(const std::string& args)
{
    std::vector<std::string> r;
    for (auto& it : split_top(strip_braces(args), ',')) {
        std::string t = trim(it);
        if (!t.empty()) r.push_back(t);
    }
    return r;
}

static void apply_aggregate(qstate& q, const std::string& args, const std::vector<std::string>& groups)
{
    if (q.aggregated || !q.limit.empty()) q.wrap();
