        }
        r.push_back({mt::punct, std::string(1, c), ""});
        i++;
    }
    return r;
}

js::value tok_json(const mtok& t)
{
    switch (t.type) {
        case mt::number: {
            if (t.text.find_first_of(".eE") == std::string::npos) {
                errno = 0;
                long long v = strtoll(t.text.c_str(), nullptr, 10);
                if (errno == 0) return js::value::make_int(v);
            }
            js::value r = js::value::make_real(strtod(t.text.c_str(), nullptr));
            r.s = t.text;
            return r;
        }
        case mt::quoted: return js::value::make_string(t.value);
        default: return js::value::make_string(t.text);
    }
}

}  // namespace

void msg_format_and_values(const std::string& body, std::string& fmt, std::string& values)
{
    auto toks = mtokenize(body);
    js::value out = js::value::make_object();
    std::string f;
    int col = 0;
    bool any = false;
    auto add = [&](const std::string& key, const js::value& v) {
        std::string k = key;
        if (out.get(k)) {
            int n = 1;
            while (out.get(k + "_" + std::to_string(n))) n++;
            k = k + "_" + std::to_string(n);
        }
        out.set(k, v);
        any = true;
    };
    for (size_t i = 0; i < toks.size(); i++) {
        auto& t = toks[i];
        // key=value
        if ((t.type == mt::word || t.type == mt::symbol) && i + 2 < toks.size() + 0 && i + 1 < toks.size()
            && toks[i + 1].type == mt::punct && toks[i + 1].text == "=" && i + 2 < toks.size()
            && (is_value_type(toks[i + 2].type) || toks[i + 2].type == mt::word))
        {
            f += t.text + "=#";
            add(t.text, tok_json(toks[i + 2]));
            i += 2;
            continue;
        }
        // key: rest-of-line
        if (t.type == mt::word && i + 2 < toks.size() && toks[i + 1].type == mt::punct
            && toks[i + 1].text == ":" && toks[i + 2].type == mt::white)
        {
            size_t j = i + 3;
            std::string rest;
            size_t k = j;
            while (k < toks.size() && toks[k].type != mt::eol) {
                rest += toks[k].text;
                k++;
            }
            std::string tr = rtrim(rest);
            if (!tr.empty()) {
                f += t.text + ":" + toks[i + 2].text + "#";
                // keep trailing whitespace in format
                f += rest.substr(tr.size());
                if (k == j + 1 && is_value_type(toks[j].type)) add(t.text, tok_json(toks[j]));
                else add(t.text, js::value::make_string(tr));
                i = k - 1;
                continue;
            }
        }
        if (is_value_type(t.type)) {
            f += "#";
            add("col_" + std::to_string(col++), tok_json(t));
            continue;
        }
        if (t.type == mt::punct && t.text == "-" && (i == 0 || toks[i - 1].type == mt::white || toks[i - 1].type == mt::punct)
            && (i + 1 >= toks.size() || toks[i + 1].type == mt::white || toks[i + 1].type == mt::punct || toks[i + 1].type == mt::eol))
        {
            f += "#";
            add("col_" + std::to_string(col++), js::value::make_string("-"));
            continue;
        }
        f += t.text;
    }
    fmt = f;
    values = any ? js::dump(out) : "null";
}
