// A simple structural pretty-printer: breaks lines after opening brackets and
// commas inside of brackets, indenting nested content.
std::string pretty_print_text(const std::string& s)
{
    std::string out;
    int depth = 0;
    char quote = 0;
    auto newline = [&]() {
        while (!out.empty() && out.back() == ' ') out.pop_back();
        out += "\n";
        out.append(depth * 4, ' ');
    };
    for (size_t i = 0; i < s.size(); i++) {
        char c = s[i];
        if (quote) {
            out.push_back(c);
            if (c == '\\' && i + 1 < s.size()) {
                out.push_back(s[++i]);
                continue;
            }
            if (c == quote) quote = 0;
            continue;
        }
        if (c == '"') {
            quote = c;
            out.push_back(c);
            continue;
        }
        if (c == '{' || c == '[') {
            // empty containers stay inline
            size_t j = i + 1;
            while (j < s.size() && s[j] == ' ') j++;
            if (j < s.size() && ((c == '{' && s[j] == '}') || (c == '[' && s[j] == ']'))) {
                out.push_back(c);
                out.push_back(s[j]);
                i = j;
                continue;
            }
            out.push_back(c);
            depth++;
            newline();
            while (i + 1 < s.size() && s[i + 1] == ' ') i++;
            continue;
        }
        if ((c == '}' || c == ']') && depth > 0) {
            depth--;
            newline();
            out.push_back(c);
            continue;
        }
        if (c == ',' && depth > 0) {
            out.push_back(c);
            newline();
            while (i + 1 < s.size() && s[i + 1] == ' ') i++;
            continue;
        }
        if (c == '\n') {
            out += "\n";
            out.append(depth * 4, ' ');
            continue;
        }
        out.push_back(c);
    }
    return out;
}
